def dashboard_page_from_query(value: object) -> str:
    return _dashboard_page_from_query(value, USER_PAGE_TITLES)


def dashboard_query_value_present(value: object) -> bool:
    """Return whether a query param was explicitly supplied."""
    if isinstance(value, list):
        return any(str(item or "").strip() for item in value)
    return bool(str(value or "").strip())


def dashboard_mode_from_query(value: object, initial_page: str = "Home") -> str:
    return _dashboard_mode_from_query(value, initial_page, ADVANCED_PAGE_TITLES)


def dashboard_generated_artifact_stale_warning(root: Path = BASE_DIR) -> str:
    data_path = root / "data"
    output_path = root / "outputs"
    generated_paths = [
        data_path / "reports" / "ticker_readiness_report.csv",
        output_path / "data_onboarding_actions.csv",
        output_path / PROJECT_STATUS_NEXT_STEPS_CSV,
    ]
    source_paths = [
        data_path / "prices.csv",
        data_path / "fundamentals.csv",
        data_path / "peers.csv",
        data_path / "earnings.csv",
        data_path / "analyst_estimates.csv",
        data_path / "universe_master.csv",
        data_path / "universe_active.csv",
        data_path / "holdings.csv",
    ]
    return generated_artifact_stale_warning(
        root=root,
        generated_paths=generated_paths,
        source_paths=source_paths,
        display_root=root,
        refresh_command="make readiness or make status",
    )


def data_health_freshness_status(root: Path = BASE_DIR) -> FreshnessStatus:
    freshness = readiness_freshness_status(root)
    generated_stale_warning = dashboard_generated_artifact_stale_warning(root)
    if generated_stale_warning and freshness.status == "current":
        return FreshnessStatus("stale", generated_stale_warning, "make readiness")
    return freshness


