def sidebar_navigation_note(selected_page: str) -> tuple[str, str]:
    if selected_page == "Home":
        return "Start here.", "Home shows what is ready, what is blocked, recent progress, and the safest next review path."
    if selected_page == "Single-Stock Report":
        return (
            "Review one stock.",
            "Use this page to review one ticker's ready analysis, locked inputs, source notes, and next local proof step.",
        )
    if selected_page == STOCK_SELECTOR_PATH_TITLE:
        return (
            "Explore ready names.",
            "Filter readiness-backed research candidates by coverage, blockers, and proof freshness without turning the queue into recommendations.",
        )
    if selected_page == "Value / Re-rating":
        return (
            "Check valuation readiness.",
            "Use this page to separate valuation-ready companies, locked inputs, peer-comparison limits, and ETF/index monitor context.",
        )
    if selected_page == "Data Health":
        return (
            "Check data coverage.",
            "Use this page to see which trusted inputs are missing and which proof path should be checked next.",
        )
    if selected_page == PROOF_HISTORY_PATH_TITLE:
        return (
            "Inspect proof.",
            "Review durable proof rows and batch outcomes before trusting changed readiness states.",
        )
    if selected_page == "Monthly Picks":
        return (
            "Explore ready names.",
            "Use this page as a data-gated candidate list; empty slots mean the filters refused to force weak or unsupported names.",
        )
    if selected_page == "Final Watchlist":
        return (
            "Read research states.",
            "Use this page to read research-state buckets, blockers, and next local steps; it is not an action or recommendation list.",
        )
    if selected_page == "Universe Manager":
        return (
            "Review the universe.",
            "Use this page to review universe coverage and preview-first changes before any manual apply step.",
        )
    if selected_page == "Overview":
        return (
            "Scan broad status.",
            "Use this page for the broad status view: readiness, blockers, source notes, and copy-only next steps.",
        )
    if selected_page == "Market Direction":
        return (
            "Review market context.",
            "Use this page for local market and theme context where price history is ready; it is not a timing signal.",
        )
    if selected_page == "Momentum Leaders":
        return (
            "Review setup strength.",
            "Use this page to review local setup strength for price-ready names before opening a single-stock report.",
        )
    if selected_page == "Portfolio Review":
        return (
            "Review portfolio context.",
            "Use this page to review local holding purpose, concentration, and risk context without creating portfolio actions.",
        )
    return (
        "Review this page.",
        f"Use {format_missing(selected_page, 'this page')} as a local research view. If you feel lost, return to Home for the plain-language readiness summary.",
    )


def dashboard_page_reader_cards(page_title: str) -> list[dict[str, object]]:
    page = format_missing(page_title, "Home")
    guides = {
        "Home": {
            "analyze": "Current market-wide readiness, recent progress, example reports, and the safest next local research path.",
            "locked": "Any module without trusted local rows stays locked; broad universe coverage is not the same as analysis readiness.",
            "read": "Read readiness cards first, then What Changed Recently, then the next-step cards. Treat big universe counts as coverage, not proof that every ticker is analysis-ready.",
            "proof": "After any refresh or import, run make readiness and reopen Home before interpreting changed counts.",
            "review_route": "Start on Home for readiness, open Value / Re-rating for valuation boundaries, use Single-Stock Report for ticker proof, then use Data Health for missing-input steps.",
            "review_area": "Home next-step cards",
            "command": "make status-check TOP_N=5",
        },
        "Single-Stock Report": {
            "analyze": "One ticker's ready inputs, valuation boundary, peer boundary, optional-context gaps, and source readiness notes.",
            "locked": "Company valuation, peer comparison, earnings, and estimate sections stay withheld when trusted inputs are missing or excluded.",
            "read": "Read Review Status, then What Can Be Read Now, then the source readiness check. Locked sections are boundaries, not hidden conclusions.",
            "proof": "After trusted rows change, rerun the relevant readiness command, then regenerate the Markdown report before reading newly available sections.",
            "review_route": "Use Single-Stock Report after Home or Value / Re-rating to prove one ticker, then go to Data Health for the exact missing-input path if anything is still locked.",
            "review_area": "Single-Stock Review",
            "command": "make stock-report-md TICKER=NVDA",
        },
        STOCK_SELECTOR_PATH_TITLE: {
            "analyze": "A readiness-backed research queue for deciding which tickers deserve one-stock review next.",
            "locked": "Names with missing trusted inputs stay visibly blocked, excluded, or partial instead of being promoted by rank alone.",
            "read": "Start with readiness state, then filter by sector/theme, DCF-ready, peer-ready, price-ready, blocker, and proof freshness.",
            "proof": "After data changes, rebuild readiness and decisions before using the queue for research planning.",
            "review_route": "Use Stock Selector after Home to find ready or nearly ready names, then open Single-Stock Report for the ticker and Data Health for blockers.",
            "review_area": "Stock Selector research queue",
            "command": "make status-check TOP_N=5",
        },
        "Value / Re-rating": {
            "analyze": "Company rows with complete valuation inputs can support assumption, scenario, sensitivity, and source-readiness review.",
            "locked": "Blocked company rows need trusted fundamentals or valuation fields; ETF/index/fund rows are monitor context, not failed valuation.",
            "read": "Read the ready, locked, and excluded split before looking at rankings. Complete valuation inputs mean assumption review, not a price target.",
            "proof": "After fundamentals change, refresh valuation readiness before reading valuation output.",
            "review_route": "Use Value / Re-rating to classify ready, locked, or excluded valuation states, then open Single-Stock Report for proof and Data Health for missing-input steps.",
            "review_area": "Fundamentals / DCF Proof",
            "command": "make dcf-readiness",
        },
        "Data Health": {
            "analyze": "Which trusted inputs are ready across prices, fundamentals, company valuation, peers, earnings, and analyst estimates.",
            "locked": "Missing inputs are a proof checklist, not weak conclusions; imports should validate, preview, and apply before trust.",
            "read": "Start with the proof-path cards, then inspect row-limited candidate lists. Use validation and preview commands before trusting newly imported rows.",
            "proof": "After validate/preview/apply, run the matching readiness command and reopen Data Health before treating a path as available.",
            "review_route": "Use Data Health when Home, Value / Re-rating, or Single-Stock Report shows a lock; return to those pages only after readiness proof passes.",
            "review_area": "Data Health proof paths",
            "command": "make data-wizard TOP_N=10",
        },
    }
    guide = guides.get(
        page,
        {
            "analyze": "The saved local rows and summaries already available for this workflow page.",
            "locked": "Rows missing trusted inputs remain visible as blocked or partial rather than inferred.",
            "read": "Read summary cards first, then the table. Use the command card only when you intentionally want to rebuild saved research views.",
            "proof": "After local data changes, rerun readiness before interpreting changed research views.",
            "review_route": "Use Home for the current state, Single-Stock Report for ticker proof, and Data Health for locked-input proof steps.",
            "review_area": "Current page summary",
            "command": "make status-check TOP_N=5",
        },
    )
    return [
        {
            "kicker": "PAGE GUIDE",
            "title": f"{page}: what can I analyze now?",
            "body": f"Analyze now: {guide['analyze']}",
            "badges": ["plain English", "readiness first"],
            "command": guide["command"],
        },
        {
            "kicker": "LOCKED / EXCLUDED",
            "title": "What stays unavailable?",
            "body": f"Still locked: {guide['locked']}",
            "badges": ["no inference", "data honest"],
            "command": guide["command"],
        },
        {
            "kicker": "NEXT SAFE STEP",
            "title": "What should I do next?",
            "body": (
                "Next step: use the command only when you are ready to run it yourself. "
                "The dashboard does not run refreshes, imports, or external account actions. "
                f"Review area: {guide['review_area']}. "
                f"Proof after data changes: {guide['proof']}"
            ),
            "badges": ["copy-only", "research-only"],
            "command": guide["command"],
        },
        {
            "kicker": "READ PATH",
            "title": "How should I read this page?",
            "body": f"Read path: {guide['read']}",
            "badges": ["plain language", "no overclaim"],
            "command": guide["command"],
        },
        {
            "kicker": "REVIEW ROUTE",
            "title": "Where does this fit in the stock review path?",
            "body": f"Review route: {guide['review_route']}",
            "badges": ["one review path", "proof before interpretation"],
            "command": guide["command"],
        },
    ]


def dashboard_page_reader_summary_cards(page_title: str) -> list[dict[str, object]]:
    cards = dashboard_page_reader_cards(page_title)
    by_kicker = {str(card.get("kicker", "")): card for card in cards}
    page_guide = by_kicker.get("PAGE GUIDE", {})
    copy_next = by_kicker.get("COPY NEXT", {})
    guide_body = re.sub(r"^Analyze now:\s*", "", str(page_guide.get("body", "")).strip())
    return [
        {
            "kicker": "PAGE GUIDE",
            "title": "Quick read.",
            "body": (
                f"{guide_body} If a section is locked, open Data Health for the next proof step. "
                "Commands stay in collapsed help and never run from the dashboard."
            ),
            "badges": ["plain English", "data honest"],
            "command": "",
        }
    ]


