def price_refresh_fallback_message(include_remote_failure_prefix: bool = False) -> str:
    body = (
        "Use `make runbook-prices-broader` or `make focus-price TICKER=...` first. "
        "For downloaded OHLCV files, run `make price-normalize INPUT=data/raw/prices/NVDA.csv "
        "TICKER=NVDA SOURCE=yahoo_manual`, then `make price-validate`, `make price-preview`, and `make price-apply`."
    )
    if include_remote_failure_prefix:
        return f"Remote price refresh had source issues. {body}"
    return body


def price_refresh_cli_note_message() -> str:
    return "Copy-only: " + price_refresh_fallback_message()


def data_gap_report_notice(message: str | None) -> tuple[str, str]:
    body = message or "The local source-gap report is not ready yet, or there are currently no explicit source-gap rows to show."
    return body, "make data-sources"


def format_value(value: object, fallback: str = "Not available") -> str:
    text = format_missing(value, fallback=fallback)
    if text == fallback:
        return text
    number = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
    if pd.isna(number):
        return text
    if abs(float(number)) >= 1_000_000:
        return f"{float(number) / 1_000_000:.1f}M"
    if abs(float(number)) >= 1_000:
        return f"{float(number):,.0f}"
    return f"{float(number):.2f}".rstrip("0").rstrip(".")


def format_date_short(value: object, fallback: str = "Not available") -> str:
    text = format_missing(value, fallback=fallback)
    if text == fallback:
        return fallback
    parsed = pd.to_datetime(text, errors="coerce")
    if pd.isna(parsed):
        return text
    return parsed.strftime("%Y-%m-%d")


def format_percent(value: object, fallback: str = "Not enough history") -> str:
    number = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
    if pd.isna(number):
        return fallback
    return f"{float(number) * 100:.1f}%"


def normalize_operator_copy(text: object) -> str:
    normalized = public_status_label(text)
    if normalized == "Not available":
        return normalized
    normalized = re.sub(
        r"^Only (\d+) verified local price rows are present;",
        r"This ticker has only \1 verified local price rows;",
        normalized,
    )
    normalized = re.sub(
        r"^Only (\d+) verified local price rows are present\.",
        r"This ticker has only \1 verified local price rows.",
        normalized,
    )
    display_labels = {
        "active_universe": "Active universe",
        "master_universe": "Master universe",
        "monitor_context": "Monitor context",
        "dcf_ready_peer_mapping": "DCF-ready peer mapping",
        "price_ready_peer_mapping": "Price-ready peer mapping",
        "peer_mapping_after_price": "Peer mapping after price",
        "peer_valuation_unlock": "Peer valuation unlock",
        "monitor_proxy_context": "Monitor proxy context",
        "add_source_backed_peer_mappings": "Add source-backed peer mappings",
        "missing_peer_mapping": "Missing peer mapping",
        "peer_price_missing": "Peer price missing",
        "peer_fundamentals_missing": "Peer fundamentals missing",
        "peer_valuation_blocked": "Peer valuation blocked",
        "peer_trend_blocked": "Peer trend blocked",
        "peer_trend_possible": "Peer trend possible",
        "operating_company_dcf_excluded": "Operating-company DCF excluded",
        "insufficient_mapping": "Insufficient mapping",
        "missing_mapping": "Missing mapping",
        "dry_run_first": "Dry-run first",
        "safe_to_batch_dry_run": "Dry-run first",
        "review_only": "Review only",
        "locked_manual": "Locked manual",
        "reviewed_apply": "Reviewed apply",
        "preview_first_reviewed_apply": "Preview first, reviewed apply",
        "optional_source_ladder": "Optional source review",
        "source_activation_required": "Source review needed",
    }
    lowered = normalized.strip().lower()
    if lowered in display_labels:
        return display_labels[lowered]
    shared_replacements = [
        (r"\bfundamentals import drafts\b", "fundamentals import file rows"),
        (r"\bfundamentals import draft\b", "fundamentals import file"),
        (r"\bpeer mapping import drafts\b", "peer mapping import file rows"),
        (r"\bpeer import drafts\b", "peer import file rows"),
        (r"\bpeer import draft\b", "peer import file"),
        (r"\blocal import draft rows\b", "local import file rows"),
        (r"\blocal import draft workflows\b", "local import files"),
        (r"\bSEC import draft workflow\b", "SEC staging workflow"),
        (r"\bSEC fundamentals import draft workflow\b", "SEC fundamentals staging workflow"),
        (r"\bSEC Companyfacts import draft workflow\b", "SEC Companyfacts staging workflow"),
    ]
    for pattern, replacement in shared_replacements:
        normalized = re.sub(pattern, replacement, normalized, flags=re.IGNORECASE)
    return re.sub(r"\bmake status\b(?!-check)", "make status-check TOP_N=5", normalized)


def friendly_dashboard_card_copy(text: object) -> str:
    normalized = normalize_operator_copy(text)
    friendly_replacements = [
        (r"\bReview fundamentals import draft\b", "Review fundamentals import file"),
        (r"\bReview peer import draft\b", "Review peer import file"),
        (r"\bReview peer import draft\b", "Review peer import file"),
        (r"\bReview price import drafts import\b", "Review price import file"),
        (r"\bReview price import draft\b", "Review price import file"),
        (r"\bFundamentals import draft\b", "Fundamentals import file"),
        (r"\bfundamentals import draft\b", "fundamentals import file"),
        (r"\bPeer import draft\b", "Peer import file"),
        (r"\bpeer import draft\b", "peer import file"),
        (r"\bStaged peers import\b", "Peer import file"),
        (r"\bpeer import draft\b", "peer import file"),
        (r"\bStaged price import\b", "Price import file"),
        (r"\bstaged price import\b", "price import file"),
        (r"\bLocal import draft rows\b", "Local import file rows"),
        (r"\blocal import draft rows\b", "local import file rows"),
        (r"\blocal import draft workflows\b", "local import files"),
        (r"\bSEC import draft workflow\b", "SEC staging workflow"),
        (r"\bSEC fundamentals import draft workflow\b", "SEC fundamentals staging workflow"),
        (r"\bSEC Companyfacts import draft workflow\b", "SEC Companyfacts staging workflow"),
        (r"\bstaged local workflow\b", "local import file workflow"),
        (r"\bstaged flow\b", "import file flow"),
        (r"\blive fundamentals import drafts\b", "live local fundamentals"),
        (r"\bfundamentals import drafts\b", "fundamentals import file"),
        (r"\bpeer mapping import drafts\b", "peer mapping import file"),
        (r"\bstaged peer\b", "peer import file"),
        (r"\bpeer import drafts\b", "peer import file"),
    ]
    for pattern, replacement in friendly_replacements:
        normalized = re.sub(pattern, replacement, normalized)
    return normalized.replace("row(s)", "rows").replace("ticker(s)", "tickers").replace("lane(s)", "lanes")


def review_path_fallback(dataset: object) -> str:
    lowered = format_missing(dataset, fallback="").strip().lower()
    if lowered in {"fundamentals", "dcf", "sec"}:
        return "Review fundamentals path."
    if lowered in {"peers", "peer", "peer_relative"}:
        return "Review peer path."
    if lowered in {"prices", "price", "price_history"}:
        return "Review price path."
    if lowered in {"optional_context", "context"}:
        return "Review optional context path."
    return "Review local data coverage."


GUIDED_BATCH_WORKFLOW_COPY = (
    "Use the guided data batch as the local import file workflow next so validation and preview safeguards stay in place."
)
GUIDED_BATCH_FIRST_COPY = (
    "Use the highest-leverage guided data batch first so price, fundamentals, or peer follow-through stays coordinated."
)


def command_family_fallback(command: object, default: str) -> str:
    lowered = format_missing(command, fallback="").strip().lower()
    if "imports-" in lowered or "runbook-" in lowered:
        return GUIDED_BATCH_WORKFLOW_COPY
    if "bundle-" in lowered:
        return GUIDED_BATCH_FIRST_COPY
    return default


def _badge(text: object, tone: str = "neutral") -> str:
    foreground, background = BADGE_COLORS.get(tone, BADGE_COLORS["neutral"])
    label = format_missing(text)
    return (
        f"<span style='display:inline-block;padding:0.18rem 0.48rem;border-radius:0.45rem;"
        f"font-size:0.78rem;font-weight:700;color:{foreground};background:{background};"
        f"border:1px solid {foreground}22;'>{label}</span>"
    )


def status_badge(status: object) -> str:
    text = public_status_label(status)
    lowered = text.lower()
    if any(keyword in lowered for keyword in ("broken", "avoid", "risk reduce")):
        return _badge(text, "negative")
    if any(keyword in lowered for keyword in ("extended", "review", "insufficient")):
        return _badge(text, "caution")
    if any(keyword in lowered for keyword in ("watch", "setup", "candidate", "rotation", "keep")):
        return _badge(text, "positive")
    return _badge(text, "neutral")


def score_badge(score: object) -> str:
    number = pd.to_numeric(pd.Series([score]), errors="coerce").iloc[0]
    if pd.isna(number):
        return _badge("Not available", "neutral")
    tone = "positive" if float(number) >= 75 else "info" if float(number) >= 55 else "caution" if float(number) >= 35 else "negative"
    return _badge(f"{float(number):.1f}", tone)


