def valuation_legacy_output_note() -> str:
    return (
        "Saved compatibility output behind this page uses an earlier file name, but this page treats it as "
        "valuation-readiness and re-rating context. It is not an automatic undervalued-stock list; "
        "rows missing trusted inputs stay blocked instead of being inferred."
    )


def valuation_legacy_diagnostic_frame(frame: pd.DataFrame | None) -> pd.DataFrame:
    columns = [
        "Ticker",
        "ValuationStatus",
        "FinalValueCategory",
        "MissingDataFields",
        "Reason",
    ]
    if frame is None or frame.empty:
        return pd.DataFrame(columns=columns + ["ReaderBoundary"])
    available_columns = _readiness_columns(frame, columns)
    diagnostic = frame[available_columns].copy()
    if "ValuationStatus" not in diagnostic.columns:
        diagnostic["ValuationStatus"] = ""
    if "FinalValueCategory" not in diagnostic.columns:
        diagnostic["FinalValueCategory"] = ""
    if "MissingDataFields" not in diagnostic.columns:
        diagnostic["MissingDataFields"] = ""

    status = diagnostic["ValuationStatus"].fillna("").astype(str).str.strip().str.lower()
    category = diagnostic["FinalValueCategory"].fillna("").astype(str).str.strip().str.lower()
    missing = diagnostic["MissingDataFields"].fillna("").astype(str).str.strip()
    blocked = (
        status.isin({"not_ready", "not ready", "blocked", "insufficient_data", "insufficient data", ""})
        | category.isin({"insufficient data", "not ready", "blocked", ""})
        | missing.ne("")
    )
    diagnostic["ReaderBoundary"] = (
        "Ready-row context only; verify DCF assumptions, peers, and source readiness before interpretation."
    )
    diagnostic.loc[blocked, "ReaderBoundary"] = (
        "No valuation conclusion; compatibility fields stay blocked until trusted inputs pass readiness."
    )
    return diagnostic


def preferred_single_stock_default(local_tickers: list[str], preferred: str = "NVDA") -> int:
    """Return the selectbox index for a visitor-friendly demo ticker when present."""
    if not local_tickers:
        return 0
    options = ["Custom"] + local_tickers
    preferred_upper = preferred.upper()
    for index, ticker in enumerate(options):
        if str(ticker).upper() == preferred_upper:
            return index
    return 1


def stock_report_local_context_cards(
    coverage: pd.DataFrame,
    peer_summary: dict[str, object],
) -> list[dict[str, object]]:
    peer_row: pd.Series | None = None
    if not coverage.empty and "dataset" in coverage.columns:
        peer_matches = coverage.loc[
            coverage["dataset"].astype(str).str.strip().str.lower().eq("peers")
        ]
        if not peer_matches.empty:
            peer_row = peer_matches.iloc[0]
    available_datasets = 0 if coverage.empty else int(coverage.get("ticker_present", pd.Series(dtype=object)).astype(bool).sum())
    validation_warnings = 0
    if not coverage.empty and "validation_status" in coverage.columns:
        validation_warnings = int(coverage["validation_status"].astype(str).eq("valid_with_warnings").sum())
    peer_count = int(peer_summary.get("peer_count") or 0)
    candidate_peer_count = int(peer_summary.get("candidate_peer_count") or 0)
    peer_target_file = format_missing(peer_row.get("target_file"), "") if peer_row is not None else ""
    peer_fallback_command = (
        "make imports-validate"
        if peer_target_file == "data/imports/peers.csv"
        else ticker_focus_command("peers", peer_row.get("ticker") if peer_row is not None else "", "make onboarding")
    )
    peer_focus_command = (
        preferred_row_command(
            peer_row,
            peer_fallback_command,
        )
        if peer_row is not None
        else "make onboarding"
    )
    staged_peer_import = peer_target_file == "data/imports/peers.csv"
    return [
        {
            "kicker": "DATA COVERAGE",
            "title": f"{available_datasets} available",
            "body": f"{validation_warnings} data warning{'s' if validation_warnings != 1 else ''} remain before every section can be trusted.",
            "badges": ["source-backed"],
        },
        {
            "kicker": "PEER MAPPING",
            "title": "Import file" if staged_peer_import else "Present" if peer_summary.get("peer_dataset_present") else "Missing",
            "body": (
                f"{peer_count} peer ticker{'s' if peer_count != 1 else ''} in the peer import file; run {scoped_import_sequence('<ticker-or-reviewed-batch>')} before trusting peer-relative context."
                if staged_peer_import
                else f"{peer_count} peer ticker{'s' if peer_count != 1 else ''} configured for peer-relative review."
            ),
            "badges": ["manual research", "import file" if staged_peer_import else "csv-first"],
            "command": peer_focus_command,
        },
        {
            "kicker": "PEER CANDIDATES",
            "title": format_missing(candidate_peer_count, "0"),
            "body": _peer_candidate_note(peer_summary),
            "badges": ["candidate layer", "not trusted yet"],
        },
        {
            "kicker": "PEER FUNDAMENTALS",
            "title": format_missing(peer_summary.get("peer_fundamentals_available"), "0"),
            "body": "Peer-relative valuation only uses locally available peer fundamentals and market context.",
            "badges": ["no fabrication"],
        },
        {
            "kicker": "PEER MARKET",
            "title": format_missing(peer_summary.get("peer_market_context_available"), "0"),
            "body": "Price and peer readiness remain explicit instead of being inferred from missing source rows.",
            "badges": ["research only"],
        },
    ]


def stock_report_next_step_cards(
    report_payload: dict[str, object],
    coverage: pd.DataFrame | None,
    peer_summary: dict[str, object] | None,
) -> list[dict[str, object]]:
    ticker = format_missing(report_payload.get("ticker"), "NVDA")
    readiness = _stock_report_payload_readiness(report_payload)
    valuation = report_payload.get("valuation_snapshot", {}) or {}
    asset_type = format_missing(report_payload.get("asset_type"), "").lower()
    valuation_status = format_missing(valuation.get("status"), "").lower()
    is_etf_like = asset_type in {"etf", "index_proxy", "fund"} or "excluded" in valuation_status
    warnings = report_payload.get("missing_data_warnings", []) or []
    peer_summary = peer_summary or {}
    cards: list[dict[str, object]] = []

    has_prices = bool(readiness.get("price_ready"))
    has_fundamentals = False
    fundamentals_row: pd.Series | None = None
    peer_row: pd.Series | None = None
    if coverage is not None and not coverage.empty:
        coverage_frame = coverage.copy()
        if "dataset" in coverage_frame.columns and "ticker_present" in coverage_frame.columns:
            coverage_frame["dataset"] = coverage_frame["dataset"].astype(str).str.strip().str.lower()
            coverage_frame["ticker_present_bool"] = coverage_frame["ticker_present"].astype(str).str.lower().isin({"true", "1", "yes"})
            has_prices = bool(
                coverage_frame.loc[coverage_frame["dataset"].eq("prices"), "ticker_present_bool"].any()
            )
            has_fundamentals = bool(
                coverage_frame.loc[coverage_frame["dataset"].eq("fundamentals"), "ticker_present_bool"].any()
            )
            fundamentals_matches = coverage_frame.loc[coverage_frame["dataset"].eq("fundamentals")]
            if not fundamentals_matches.empty:
                fundamentals_row = fundamentals_matches.iloc[0]
            peer_matches = coverage_frame.loc[coverage_frame["dataset"].eq("peers")]
            if not peer_matches.empty:
                peer_row = peer_matches.iloc[0]

    fundamentals_target_file = format_missing(fundamentals_row.get("target_file"), "") if fundamentals_row is not None else ""
    fundamentals_fallback = (
        "make imports-validate"
        if fundamentals_target_file == "data/imports/fundamentals.csv"
        else ticker_focus_command("fundamentals", ticker, fallback=f"make sec-stage TICKERS={ticker}")
    )
    fundamentals_command = preferred_row_command(
        fundamentals_row,
        fundamentals_fallback,
    ) if fundamentals_row is not None else ticker_focus_command(
        "fundamentals",
        ticker,
        fallback=f"make sec-stage TICKERS={ticker}",
    )
    staged_fundamentals_import = (
        fundamentals_target_file == "data/imports/fundamentals.csv"
    )
    peer_target_file = format_missing(peer_row.get("target_file"), "") if peer_row is not None else ""
    peer_fallback = (
        "make imports-validate"
        if peer_target_file == "data/imports/peers.csv"
        else ticker_focus_command("peers", ticker, fallback="make templates")
    )
    peer_command = preferred_row_command(peer_row, peer_fallback) if peer_row is not None else ticker_focus_command("peers", ticker, fallback="make templates")
    staged_peer_import = (
        peer_target_file == "data/imports/peers.csv"
    )

    if not has_prices:
        cards.append(
            {
                "kicker": "NEXT STEP",
                "title": "Fix price coverage",
                "body": (
                    f"{ticker} still needs stronger verified local price history before broader trust. "
                    "Run the PROVIDER=auto price ladder first so Yahoo, Stooq, and configured FMP/Alpha Vantage/Finnhub "
                    "fallbacks are tried before the last manual import-file path."
                ),
                "badges": ["prices", "data moat"],
                "command": ticker_focus_command("prices", ticker, fallback=f"make price-refresh TICKERS={ticker} PROVIDER=auto"),
            }
        )
    elif is_etf_like:
        cards.append(
            {
                "kicker": "NEXT STEP",
                "title": "Review ETF / market proxy",
                "body": (
                    f"{ticker} should be reviewed as market, theme, liquidity, or risk context. "
                    "Operating-company DCF and peer-relative valuation are excluded rather than failed."
                ),
                "badges": ["monitor context", "DCF excluded"],
                "command": f"make stock-report-md TICKER={ticker}",
            }
        )
    elif not readiness.get("dcf_ready") and not has_fundamentals:
        cards.append(
            {
                "kicker": "NEXT STEP",
                "title": "Review fundamentals import file" if staged_fundamentals_import else "Stage fundamentals",
                "body": (
                    f"{ticker} already has fundamentals import file rows in {fundamentals_target_file}. "
                    "Validate, preview, and apply them before trusting DCF coverage."
                    if staged_fundamentals_import
                    else (
                        f"{ticker} has enough price context for more research, but DCF coverage is still missing local fundamentals. "
                        "Stage SEC fundamentals before leaning on valuation."
                    )
                ),
                "badges": ["fundamentals", "import file" if staged_fundamentals_import else "sec queue"],
                "command": fundamentals_command,
            }
        )
    elif not readiness.get("peer_ready") or not peer_summary.get("peer_dataset_present"):
        cards.append(
            {
                "kicker": "NEXT STEP",
                "title": "Review peer import file" if staged_peer_import else "Add peer mappings",
                "body": (
                    f"{ticker} already has peer mapping import file rows in {peer_target_file}. "
                    "Validate, preview, and apply them before trusting peer-relative context."
                    if staged_peer_import
                    else (
                        f"{ticker} can be reviewed now, but peer-relative context is still partial. "
                        "Add manually researched peers if this name matters for deeper relative work."
                    )
                ),
                "badges": ["peers", "import file" if staged_peer_import else "manual research"],
                "command": peer_command,
            }
        )
    else:
        cards.append(
            {
                "kicker": "NEXT STEP",
                "title": "Review full report",
                "body": (
                    f"{ticker} already has the minimum local context for a deeper single-name pass. "
                    "Move through valuation, trend and risk context, and source readiness together."
                ),
                "badges": ["ready", "single name"],
                "command": f"make stock-report-md TICKER={ticker}",
            }
        )

    cards.append(
        {
            "kicker": "DATA GAPS",
            "title": f"{len(warnings)} visible",
            "body": (
                "Warnings stay explicit and should guide the next research step instead of being hidden behind a score."
            ),
            "badges": ["DCF excluded", "monitor context"] if is_etf_like else stock_report_readiness_badges(readiness)[:2],
        }
    )
    earnings_ready = bool(readiness.get("earnings_available") or readiness.get("earnings_ready"))
    estimates_ready = bool(readiness.get("analyst_estimates_available") or readiness.get("analyst_estimates_ready"))
    if not earnings_ready or not estimates_ready:
        missing_optional = []
        if not earnings_ready:
            missing_optional.append("earnings")
        if not estimates_ready:
            missing_optional.append("analyst estimates")
        cards.append(
            {
                "kicker": "OPTIONAL CONTEXT",
                "title": "Locked",
                "body": (
                    f"Missing optional context: {', '.join(missing_optional)}. "
                    "Core supported analysis can still be reviewed when the mode allows it; optional rows should stay unavailable until trusted local CSVs exist."
                ),
                "badges": ["trusted rows only", "lower priority"],
                "command": "make templates",
            }
        )
    return cards


def stock_report_workflow_fit_cards(
    report_payload: dict[str, object],
    coverage: pd.DataFrame | None = None,
    peer_summary: dict[str, object] | None = None,
) -> list[dict[str, object]]:
    """Return the compact single-stock workflow handoff before report details."""

    ticker = format_missing(report_payload.get("ticker"), "TICKER").upper()
    readiness = _stock_report_payload_readiness(report_payload)
    evaluation = stock_report_evaluation_summary_frame(report_payload)
    answers = {
        format_missing(row.get("Question"), ""): format_missing(row.get("Answer"), "")
        for _, row in evaluation.iterrows()
    }
    mode = answers.get("Evaluation mode", "Not classified")
    review_now = answers.get("What this report can support", "Read only sections backed by ready local inputs.")
    withheld = answers.get("What remains withheld", "Unavailable inputs remain locked until trusted rows pass readiness.")
    next_review = answers.get("Best next review step", "Review source readiness before interpreting the report.")
    confidence = answers.get("Data-confidence note", "Readiness state is the confidence boundary.")

    asset_type = stock_report_inferred_asset_type(report_payload)
    valuation = report_payload.get("valuation_snapshot", {}) or {}
    valuation_status = format_missing(valuation.get("status"), "").lower()
    price_ready = bool(readiness.get("price_ready"))
    dcf_ready = bool(readiness.get("dcf_ready"))
    peer_ready = bool(readiness.get("peer_ready"))
    earnings_ready = bool(readiness.get("earnings_available") or readiness.get("earnings_ready"))
    estimates_ready = bool(readiness.get("analyst_estimates_available") or readiness.get("analyst_estimates_ready"))
    next_cards = stock_report_next_step_cards(report_payload, coverage, peer_summary)
    next_card = next_cards[0] if next_cards else {}
    next_command = format_missing(next_card.get("command"), stock_report_md_command(ticker))
    next_title = format_missing(next_card.get("title"), "Review local report")

    route_decision = single_stock_report_data_health_route(
        asset_type=asset_type,
        valuation_status=valuation_status,
        price_ready=price_ready,
        dcf_ready=dcf_ready,
        peer_ready=peer_ready,
        earnings_ready=earnings_ready,
        estimates_ready=estimates_ready,
    )
    route = route_decision["route"]
    route_label = route_decision["route_label"]
    stop_rule = route_decision["stop_rule"]

    return [
        {
            "kicker": "RESEARCH LOOP",
            "title": f"{ticker}: review step before source-proof follow-up",
            "body": (
                "Previous proof: available data plus saved readiness checks. "
                f"Current step: read supported sections first. Next safe action: {route_label}. "
                f"Stop rule: {stop_rule}"
            ),
            "badges": ["Home -> report -> Data Health", "proof first"],
            "command": route,
        },
        {
            "kicker": "SELECTED TICKER",
            "title": f"{ticker}: {mode}",
            "body": f"{confidence} Current page state comes from available data and saved readiness checks.",
            "badges": ["ticker state", "readiness gated"],
            "command": stock_report_md_command(ticker),
        },
        {
            "kicker": "REVIEW NOW",
            "title": "What can be reviewed",
            "body": f"{review_now} Decision boundary: read this as research context only, not a ranking or action.",
            "badges": ["ready sections", "research-only"],
            "command": stock_report_md_command(ticker),
        },
        {
            "kicker": "STILL BLOCKED",
            "title": "What stays locked or excluded",
            "body": f"{withheld} Do not infer missing inputs from nearby ready sections.",
            "badges": ["blocked visible", "no inference"],
            "command": route,
        },
        {
            "kicker": "DATA HEALTH HANDOFF",
            "title": f"{route_label}: {next_title}",
            "body": (
                f"{next_review} Continue through {route_label} only if the locked fields matter for this ticker. "
                f"The route is a manual proof path in the detailed controls. Stop rule: {stop_rule}"
            ),
            "badges": ["manual proof", "research-only"],
            "command": next_command,
        },
    ]


def stock_report_price_chart_frame(history: pd.DataFrame | None) -> pd.DataFrame:
    if history is None or history.empty or "date" not in history.columns or "close" not in history.columns:
        return pd.DataFrame(columns=["Close"])

    frame = history.copy()
    frame["date"] = pd.to_datetime(frame["date"], errors="coerce")
    frame["close"] = pd.to_numeric(frame["close"], errors="coerce")
    frame = frame.loc[frame["date"].notna() & frame["close"].notna(), ["date", "close"]].copy()
    if frame.empty:
        return pd.DataFrame(columns=["Close"])

    frame = frame.sort_values("date").drop_duplicates(subset="date", keep="last")
    return frame.rename(columns={"close": "Close"}).set_index("date")


def monthly_pick_score_chart_frame(picks_frame: pd.DataFrame | None, max_rows: int = 8) -> pd.DataFrame:
    if picks_frame is None or picks_frame.empty or "Ticker" not in picks_frame.columns:
        return pd.DataFrame()

    score_columns = [
        column
        for column in ["CompositeScore", "MomentumScore", "QualityScore", "ValuationContextScore", "LiquidityScore"]
        if column in picks_frame.columns
    ]
    if not score_columns:
        return pd.DataFrame()

    frame = picks_frame.copy()
    for column in score_columns:
        frame[column] = pd.to_numeric(frame[column], errors="coerce")

    rank_columns = ["Rank"] if "Rank" in frame.columns else []
    frame = frame.loc[frame[score_columns].notna().any(axis=1), ["Ticker", *score_columns, *rank_columns]].copy()
    if frame.empty:
        return pd.DataFrame()

    frame["Ticker"] = frame["Ticker"].astype(str).str.upper().str.strip()
    if "Rank" in frame.columns:
        frame["Rank"] = pd.to_numeric(frame["Rank"], errors="coerce")
        frame = frame.sort_values(["Rank", "CompositeScore"], ascending=[True, False], na_position="last")
    else:
        frame = frame.sort_values("CompositeScore", ascending=False, na_position="last")

    frame = frame.drop_duplicates(subset=["Ticker"], keep="first").head(max_rows)
    chart_frame = frame.set_index("Ticker")[score_columns]
    return chart_frame.rename(columns={"ValuationContextScore": "ValuationScore"})


def _technical_distance_label(value: object, label: str) -> str:
    number = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
    if pd.isna(number):
        return f"{label} unavailable"
    relation = "Above" if float(number) >= 0 else "Below"
    return f"{relation} {label}"


def _atr_or_volatility_source_label(source: object) -> str:
    normalized = str(source or "").strip().lower()
    if normalized == "atr":
        return "ATR from high/low/close"
    if normalized == "volatility_proxy":
        return "Volatility proxy approximation"
    return "Volatility source unavailable"


def stock_report_technical_context_cards(report_payload: dict[str, object]) -> list[dict[str, object]]:
    screener_context = report_payload.get("screener_context", {}) or {}
    momentum = screener_context.get("momentum_leaders", {}) or {}
    watchlist = screener_context.get("final_watchlist", {}) or {}
    setup_status = format_missing(momentum.get("SetupStatus") or watchlist.get("SetupStatus"), "Not available")
    final_state = format_missing(watchlist.get("FinalState"), "Not available")
    rs_percentile = momentum.get("RSPercentile")
    relative_spy = momentum.get("RelativeReturnVsSPY")
    relative_qqq = momentum.get("RelativeReturnVsQQQ")
    volume_ratio = momentum.get("VolumeRatio")
    volume_ratio_display = report_display_value(volume_ratio, "number")
    volume_title = f"Volume {volume_ratio_display}x" if volume_ratio_display != "Not available" else "Volume ratio not available"
    volatility_proxy = momentum.get("ATRorVolatilityPct")
    volatility_source = _atr_or_volatility_source_label(momentum.get("ATRorVolatilitySource"))
    ma_stack = [
        _technical_distance_label(momentum.get("DistanceFrom10EMA"), "10 EMA"),
        _technical_distance_label(momentum.get("DistanceFrom21EMA"), "21 EMA"),
        _technical_distance_label(momentum.get("DistanceFrom50SMA"), "50 SMA"),
    ]
    return [
        {
            "kicker": "SETUP",
            "title": setup_status,
            "body": f"Current watchlist state: {final_state}. Momentum setup remains research context, not execution guidance.",
            "badges": [final_state],
        },
        {
            "kicker": "RELATIVE STRENGTH",
            "title": report_display_value(rs_percentile, "number"),
            "body": f"vs SPY {report_display_value(relative_spy, 'percent')} · vs QQQ {report_display_value(relative_qqq, 'percent')}.",
            "badges": ["RS percentile"],
        },
        {
            "kicker": "TREND STACK",
            "title": ma_stack[0],
            "body": " · ".join(ma_stack[1:]),
            "badges": ["moving averages"],
        },
        {
            "kicker": "FLOW / VOLATILITY",
            "title": volume_title,
            "body": f"{volatility_source}: {report_display_value(volatility_proxy, 'percent')}. Proxy values are approximations; missing values stay visible instead of guessed.",
            "badges": ["local price data", volatility_source],
        },
    ]


