def stock_report_review_metrics_frame(report_payload: dict[str, object]) -> pd.DataFrame:
    review_metrics = report_payload.get("review_metrics", {}) or {}
    rows: list[dict[str, object]] = []
    for benchmark in ("SPY", "QQQ"):
        snapshot = review_metrics.get(benchmark) if isinstance(review_metrics, dict) else None
        if not isinstance(snapshot, dict):
            continue
        for metric in snapshot.get("price_metrics", []) or []:
            if not isinstance(metric, dict):
                continue
            rows.append(
                {
                    "Group": f"{benchmark} benchmark/risk",
                    "Metric": str(metric.get("name", "")).replace("_", " ").title(),
                    "State": format_missing(metric.get("state")),
                    "Value": report_display_value(metric.get("value"), "percent" if metric.get("unit") == "percent" else "number"),
                    "Missing Inputs": joined_notes(metric.get("missing_inputs", [])) or "none",
                }
            )
    preferred_snapshot = review_metrics.get("SPY") if isinstance(review_metrics, dict) else None
    if not isinstance(preferred_snapshot, dict) and isinstance(review_metrics, dict) and review_metrics:
        preferred_snapshot = next((value for value in review_metrics.values() if isinstance(value, dict)), {})
    if isinstance(preferred_snapshot, dict):
        for group, key in (
            ("Fundamentals trend", "fundamentals_metrics"),
            ("Valuation multiples", "valuation_metrics"),
            ("Peer valuation dispersion", "peer_metrics"),
        ):
            for metric in preferred_snapshot.get(key, []) or []:
                if not isinstance(metric, dict):
                    continue
                rows.append(
                    {
                        "Group": group,
                        "Metric": str(metric.get("name", "")).replace("_", " ").title(),
                        "State": format_missing(metric.get("state")),
                        "Value": report_display_value(metric.get("value"), "percent" if metric.get("unit") == "percent" else "number"),
                        "Missing Inputs": joined_notes(metric.get("missing_inputs", [])) or "none",
                    }
                )
    return pd.DataFrame(rows)


def stock_report_review_metric_summary_cards(report_payload: dict[str, object]) -> list[dict[str, object]]:
    frame = stock_report_review_metrics_frame(report_payload)
    if frame.empty:
        return [
            {
                "kicker": "METRIC READINESS",
                "title": "Blocked",
                "body": "Benchmark, risk, fundamentals, valuation, and peer review metrics are not assembled for this report yet.",
                "badges": ["no inferred metrics"],
            }
        ]
    state_counts = frame["State"].astype(str).str.lower().value_counts().to_dict()
    ready = int(state_counts.get("ready", 0))
    partial = int(state_counts.get("partial", 0))
    blocked = int(state_counts.get("blocked", 0))
    benchmark_rows = frame.loc[frame["Group"].astype(str).str.contains("benchmark/risk", case=False, na=False)]
    benchmark_states = ", ".join(
        dict.fromkeys(benchmark_rows["State"].dropna().astype(str).str.lower().tolist())
    ) or "not available"
    missing_rows = frame.loc[frame["Missing Inputs"].astype(str).str.lower().ne("none")]
    first_missing = "none"
    if not missing_rows.empty:
        first = missing_rows.iloc[0]
        first_missing = f"{first['Metric']}: {first['Missing Inputs']}"
    return [
        {
            "kicker": "METRIC READINESS",
            "title": f"{ready} ready / {partial} partial / {blocked} blocked",
            "body": "Review metrics are gated one by one, so partial benchmark or peer inputs stay visible instead of becoming hidden scores.",
            "badges": ["ready", "partial", "blocked"],
        },
        {
            "kicker": "BENCHMARK GATES",
            "title": benchmark_states.title(),
            "body": "SPY and QQQ comparisons require aligned local price history before relative return or beta can be treated as ready.",
            "badges": ["SPY", "QQQ", "aligned rows"],
        },
        {
            "kicker": "NEXT BLOCKER",
            "title": "Exact input shown",
            "body": first_missing,
            "badges": ["no guessing", "source first"],
        },
    ]


def stock_report_missing_data_text(warnings: list[object]) -> str:
    if not warnings:
        return "No explicit missing-data warnings were assembled from the current inputs."
    items: list[str] = []
    for warning in warnings:
        for item in summarize_missing_fields(warning, max_items=4).split(", "):
            clean_item = item.strip()
            if clean_item and clean_item != "No explicit missing-data warnings":
                items.append(clean_item)
    unique_items = list(dict.fromkeys(items))
    if not unique_items:
        return "No explicit missing-data warnings were assembled from the current inputs."
    max_visible = 6
    shown = unique_items[:max_visible]
    remaining = len(unique_items) - len(shown)
    summary = "\n".join(f"- {item}" for item in shown)
    if remaining > 0:
        summary += f"\n- +{remaining} more visible warning{'s' if remaining != 1 else ''}; open the detailed notes before using the valuation view."
    return summary


def stock_report_source_frame(source_rows: list[dict[str, object]]) -> pd.DataFrame:
    if not source_rows:
        return pd.DataFrame(columns=["Provider", "Source Readiness", "Retrieved", "Official", "Notes"])
    rows = []
    for row in source_rows:
        rows.append(
            {
                "Provider": format_missing(row.get("provider")),
                "Source Readiness": format_missing(row.get("freshness")),
                "Retrieved": format_date_short(row.get("retrieved_at"), fallback="Not available"),
                "Official": "Yes" if row.get("official") else "No",
                "Notes": joined_notes(row.get("notes")),
            }
        )
    return pd.DataFrame(rows)


def stock_report_source_detail_summary_frame(report_payload: dict[str, object]) -> pd.DataFrame:
    readiness = report_payload.get("valuation_readiness", {}) or {}
    source_rows = report_payload.get("data_freshness", []) or []
    missing_warnings = report_payload.get("missing_data_warnings", []) or []
    ready_count = sum(1 for value in readiness.values() if isinstance(value, bool) and value)
    blocked_count = sum(1 for value in readiness.values() if isinstance(value, bool) and not value)
    return pd.DataFrame(
        [
            {"Detail": "Ticker", "Value": format_missing(report_payload.get("ticker"))},
            {"Detail": "Provider", "Value": format_missing(report_payload.get("provider_name"), "Not available")},
            {"Detail": "Report timestamp", "Value": format_date_short(report_payload.get("generated_at"), "Not available")},
            {"Detail": "Ready report checks", "Value": report_display_value(ready_count, "integer")},
            {"Detail": "Locked report checks", "Value": report_display_value(blocked_count, "integer")},
            {"Detail": "Source records", "Value": report_display_value(len(source_rows), "integer")},
            {"Detail": "Missing-input warnings", "Value": report_display_value(len(missing_warnings), "integer")},
            {
                "Detail": "Optional report data download",
                "Value": "Use Download Evidence JSON only if you need the optional saved evidence file; most readers can use this page.",
            },
        ]
    )


def stock_report_detail_frame(data: dict[str, object]) -> pd.DataFrame:
    rows = []
    for key, value in data.items():
        if isinstance(value, bool):
            display = "Yes" if value else "No"
        elif isinstance(value, list):
            display = joined_notes(value)
        elif isinstance(value, dict):
            display = ", ".join(f"{item_key}: {format_missing(item_value)}" for item_key, item_value in value.items()) or "Not available"
        elif isinstance(value, (int, float)) and not isinstance(value, bool):
            display = format_value(value)
        else:
            display = format_date_short(value) if "date" in str(key).lower() or "time" in str(key).lower() else format_missing(value)
        rows.append({"Field": display_column_label(str(key)), "Value": display})
    return pd.DataFrame(rows)


def stock_report_notes_frame(
    valuation: dict[str, object],
    relative: dict[str, object],
) -> pd.DataFrame:
    return pd.DataFrame(
        [
            {"Section": "DCF warnings", "Details": joined_notes(valuation.get("warnings", []))},
            {"Section": "DCF notes", "Details": joined_notes(valuation.get("notes", []))},
            {"Section": "Peer warnings", "Details": joined_notes(relative.get("peer_missing_data_warnings", []))},
            {"Section": "Peer missing fields", "Details": joined_notes(relative.get("missing_fields", []))},
        ]
    )


def data_health_overview_cards(
    validation_rows: pd.DataFrame,
    price_status_frame: pd.DataFrame | None,
    action_queue_frame: pd.DataFrame | None,
    coverage_frame: pd.DataFrame | None,
) -> list[dict[str, object]]:
    if validation_rows.empty:
        dataset_title = "No validation rows"
        dataset_body = "Run local validation to inspect configured CSV datasets."
        dataset_badges = ["make validate-data"]
        dataset_command = "make validate-data"
    else:
        status_series = validation_rows.get("validation_status", pd.Series(dtype=object)).astype(str)
        valid_count = int(status_series.isin({"valid", "valid_with_warnings"}).sum())
        missing_count = int(status_series.eq("missing_file").sum())
        dataset_title = f"{valid_count} usable datasets"
        dataset_body = f"{missing_count} optional local file{'s' if missing_count != 1 else ''} missing. Partial reports remain safe."
        dataset_badges = ["CSV-first", f"{len(validation_rows)} checked"]
        dataset_command = "make validate-data"

    price_counts = summarize_price_update_status(price_status_frame)
    price_problem_count = sum(
        price_counts.get(status, 0)
        for status in ["parse_error", "source_unavailable", "network_error", "no_rows", "failed"]
    )
    if price_status_frame is None:
        price_title = "Price status not ready yet"
        price_body = (
            "Use make runbook-prices-broader or make focus-price TICKER=... first. "
            "For downloaded files, run make price-normalize, make price-validate, "
            "make price-preview, and make price-apply."
        )
        price_badges = ["make runbook-prices-broader", "manual import option"]
        price_command = "make runbook-prices-broader"
    elif price_problem_count:
        price_title = f"{price_problem_count} price issue{'s' if price_problem_count != 1 else ''}"
        price_body = (
            "Use downloaded price files only as user-provided inputs, then run make price-normalize, "
            "make price-validate, make price-preview, and make price-apply."
        )
        price_badges = ["make price-status TOP_N=10", "manual import option"]
        price_command = "make price-status TOP_N=10"
    else:
        price_title = f"{price_counts.get('fetched', 0)} fetched"
        price_body = "Latest price refresh did not report blocking source errors."
        price_badges = ["make price-status TOP_N=10"]
        price_command = "make price-status TOP_N=10"

    queue_summary = action_queue_summary(action_queue_frame)
    action_title = f"{queue_summary['critical']} critical actions"
    action_body = f"{queue_summary['high']} high-priority and {queue_summary['medium']} medium-priority data fixes are queued."
    action_badges = ["make action-queue-check TOP_N=10", "read-only dashboard"]
    action_command = "make action-queue-check TOP_N=10"
    signal_ready = (
        action_queue_frame is not None
        and not action_queue_frame.empty
        and {"priority", "action_type"}.issubset(set(action_queue_frame.columns))
    )
    top_signal = top_priority_signals(action_queue_frame, limit=1) if signal_ready else []
    if top_signal:
        signal = top_signal[0]
        signal_body = compact_reason(signal.get("body"), max_sentences=2, max_chars=220)
        signal_command = format_missing(signal.get("command"), "")
        if signal_body and signal_body != "Not available":
            action_body = (
                f"{queue_summary['high']} high-priority and {queue_summary['medium']} medium-priority data fixes are queued. "
                f"Top next step: {signal_body}"
            )
        if signal_command and signal_command != "Not available":
            action_command = signal_command

    coverage_summary = summarize_ticker_coverage(coverage_frame)
    coverage_title = f"{coverage_summary['usable_price_tickers']} price-ready tickers"
    coverage_body = (
        f"{coverage_summary['dcf_ready_tickers']} DCF-ready, "
        f"{coverage_summary['peer_ready_tickers']} peer-ready, "
        f"{coverage_summary['optional_only_missing_tickers']} missing only optional files."
    )
    coverage_badges = ["make data-wizard TOP_N=10"]
    coverage_command = "make data-wizard TOP_N=10"

    return [
        {"kicker": "DATASETS", "title": dataset_title, "body": dataset_body, "badges": dataset_badges, "command": dataset_command},
        {"kicker": "PRICES", "title": price_title, "body": price_body, "badges": price_badges, "command": price_command},
        {"kicker": "NEXT ACTIONS", "title": action_title, "body": action_body, "badges": action_badges, "command": action_command},
        {"kicker": "COVERAGE", "title": coverage_title, "body": coverage_body, "badges": coverage_badges, "command": coverage_command},
    ]


