def data_health_readiness_queue_drilldown_cards(row: pd.Series | dict[str, object]) -> list[dict[str, object]]:
    lane = format_missing(row.get("Lane") if isinstance(row, dict) else row.get("Lane"), "Readiness lane")
    state = format_missing(row.get("State") if isinstance(row, dict) else row.get("State"), "Not available")
    examples = compact_card_fragment(
        row.get("Top Blocker Examples") if isinstance(row, dict) else row.get("Top Blocker Examples"),
        max_chars=210,
    )
    packet_command = format_missing(
        row.get("Proof Packet Command") if isinstance(row, dict) else row.get("Proof Packet Command"),
        "make readiness-queue TOP_N=10",
    )
    source_warning = compact_card_fragment(
        row.get("Stale / Source Warning") if isinstance(row, dict) else row.get("Stale / Source Warning"),
        max_chars=210,
    )
    proof_status = compact_card_fragment(
        row.get("Proof Record Status") if isinstance(row, dict) else row.get("Proof Record Status"),
        max_chars=180,
    )
    next_action = format_missing(
        row.get("Next Safe Action") if isinstance(row, dict) else row.get("Next Safe Action"),
        packet_command,
    )
    return [
        {
            "kicker": "LANE DRILLDOWN",
            "title": f"{lane}: {state}",
            "body": (
                f"{card_sentence('Examples', examples)} "
                f"{card_sentence('Source warning', source_warning)}"
            ),
            "badges": ["examples", "source gate"],
            "command": next_action,
        },
        {
            "kicker": "PROOF PACKET",
            "title": "Copy-only reviewed packet",
            "body": (
                f"Packet command: {packet_command}. "
                "Use this to preview scope and proof fields before any validate / preview / apply path."
            ),
            "badges": ["dry-run first", "copy-only"],
            "command": packet_command,
        },
        {
            "kicker": "PROOF RECORD",
            "title": proof_status,
            "body": (
                "Record supported, candidate_context_only, still_blocked, skipped, or excluded only after reviewed evidence, comparison, "
                "and generated-artifact classification are complete."
            ),
            "badges": ["ledger boundary", "research-only"],
            "command": "make reviewed-batch-proof",
        },
    ]


