def data_health_readiness_ops_center_cards(ops_frame: pd.DataFrame | None, *, limit: int = 3) -> list[dict[str, object]]:
    if ops_frame is None or ops_frame.empty:
        return [
            {
                "kicker": "OPS CENTER",
                "title": "Lane operations need readiness reports",
                "body": "Run make readiness first, then use the read-only operations center to choose a batch lane before drilling into individual tickers.",
                "badges": ["read-only", "lane-level"],
                "command": "make readiness-ops-center",
            }
        ]
    sorted_frame = ops_frame.copy()
    sorted_frame["_impact"] = pd.to_numeric(sorted_frame["Unlock Impact"], errors="coerce").fillna(0).astype(int)
    sorted_frame = sorted_frame.sort_values(["_impact", "Lane"], ascending=[False, True])
    cards: list[dict[str, object]] = []
    for _, row in sorted_frame.head(max(limit, 0)).iterrows():
        lane = format_missing(row.get("Lane"), "Data readiness lane")
        state = public_status_label(row.get("State"))
        workflow = format_missing(row.get("Workflow Mode"), "review")
        impact = format_missing(row.get("Unlock Impact"), "0")
        source = compact_card_fragment(row.get("Source Readiness"), max_chars=170)
        churn = compact_card_fragment(row.get("Generated Churn Policy"), max_chars=160)
        command = format_missing(row.get("Next Safe Command"), "make readiness-ops-center")
        body = (
            f"{impact} row(s) or feature states could be improved by this lane. "
            f"{card_sentence('Source readiness', source)} "
            f"{card_sentence('Churn policy', churn)} "
            f"Next safe command: {command}."
        )
        cards.append(
            {
                "kicker": "READINESS OPS",
                "title": lane,
                "body": body,
                "badges": [state, workflow],
                "command": command,
            }
        )
    return cards


def data_health_peer_readiness_v2_cards(ops_frame: pd.DataFrame | None) -> list[dict[str, object]]:
    """Summarize peer mapping, peer trend, and peer valuation gates before detailed tables."""

    if ops_frame is None or ops_frame.empty:
        return [
            {
                "kicker": "PEER READINESS V2",
                "title": "Peer sub-states need readiness rows",
                "body": "Run make readiness, then reopen Data Health to separate peer mapping, peer price, peer fundamentals, and peer valuation readiness.",
                "badges": ["read-only", "peer gates"],
                "command": "make readiness && make peer-mapping-queue TOP_N=25",
            }
        ]
    peer_rows = ops_frame.loc[
        ops_frame["Lane"].astype(str).str.lower().str.contains("peer", na=False)
    ].copy()
    if peer_rows.empty:
        return [
            {
                "kicker": "PEER READINESS V2",
                "title": "Peer lanes are not in this snapshot",
                "body": "Run make readiness-ops-center after readiness reports exist. Peer valuation stays locked until mapped peer inputs are trusted.",
                "badges": ["read-only", "blocked"],
                "command": "make readiness-ops-center",
            }
        ]
    cards: list[dict[str, object]] = []
    for _, row in peer_rows.iterrows():
        lane = format_missing(row.get("Lane"), "Peer readiness lane")
        notes = compact_card_fragment(row.get("Notes"), max_sentences=2, max_chars=420)
        command = format_missing(row.get("Next Safe Command"), "make peer-mapping-queue TOP_N=25")
        proof = compact_card_fragment(row.get("Proof Command"), max_chars=150)
        cards.append(
            {
                "kicker": "PEER READINESS V2",
                "title": lane,
                "body": (
                    f"{card_sentence('Sub-state proof', notes)} "
                    f"{card_sentence('Proof command', proof)} "
                    "Peer trend can become usable before peer valuation; sector fallback is context, not trusted peer valuation."
                ),
                "badges": [public_status_label(row.get("State")), format_missing(row.get("Workflow Mode"), "review")],
                "command": command,
            }
        )
    return cards


def data_health_peer_readiness_v2_frame(ops_frame: pd.DataFrame | None) -> pd.DataFrame:
    """Return explicit peer sub-state rows for the Data Health drilldown."""

    sub_states = [
        {
            "Sub-State": "Peer mapping",
            "Meaning": "Source-backed comparable-company rows exist for the ticker.",
            "Proof Command": "make peer-mapping-queue TOP_N=25",
        },
        {
            "Sub-State": "Peer price",
            "Meaning": "Mapped peers have local trusted price history for context.",
            "Proof Command": "make price-coverage TOP_N=25 && make readiness",
        },
        {
            "Sub-State": "Peer momentum",
            "Meaning": "Mapped peers have enough price history for trend context.",
            "Proof Command": "make readiness && make metric-readiness BENCHMARK=SPY",
        },
        {
            "Sub-State": "Peer fundamentals",
            "Meaning": "Mapped peers have trusted fundamentals rows.",
            "Proof Command": "make dcf-readiness && make readiness",
        },
        {
            "Sub-State": "Peer valuation",
            "Meaning": "Mapped peers have trusted valuation inputs such as fundamentals plus market-cap context.",
            "Proof Command": "make readiness && make peer-mapping-queue TOP_N=25",
        },
        {
            "Sub-State": "Peer valuation comparison",
            "Meaning": "The ticker and mapped peers all have trusted inputs needed for peer dispersion review.",
            "Proof Command": "make stock-report-md TICKER=<ticker>",
        },
    ]
    if ops_frame is None or ops_frame.empty:
        status_note = "needs current readiness rows"
    else:
        peer_rows = ops_frame.loc[ops_frame["Lane"].astype(str).str.lower().str.contains("peer", na=False)]
        status_note = (
            "peer lanes absent from current operations snapshot"
            if peer_rows.empty
            else "see peer operations rows; trend can be ready before valuation"
        )
    rows = []
    for item in sub_states:
        rows.append(
            {
                **item,
                "Current Evidence": status_note,
                "Guardrail": "Blocked stays blocked until source-backed local rows prove this sub-state; sector fallback is context only.",
            }
        )
    return pd.DataFrame(rows)


