def data_health_peer_source_review_frame(packet: PeerMappingSourceReviewPacket | None, limit: int = 10) -> pd.DataFrame:
    columns = [
        "Review Gate",
        "Ticker",
        "Mapping Slot",
        "Completion Status",
        "Missing Fields",
        "Import Preview Status",
        "Required Fills",
        "Target File",
        "CSV Header",
        "CSV Row",
        "Next Safe Action",
        "Import Row Scaffold",
        "Apply Boundary",
        "Post-Apply Proof",
        "Validation Path",
        "Do Not Proceed If",
        "Candidate Context State",
        "Candidate Context Source",
        "Candidate Context Count",
        "Candidate Context Peers",
        "Candidate Context Boundary",
        "Freshness Context",
    ]
    if packet is None or not packet.rows:
        return pd.DataFrame(columns=columns)
    freshness_status = format_missing(packet.freshness.status, "unknown").replace("_", " ")
    review_gate = "blocked by freshness" if packet.freshness.status in {"missing", "stale"} else "source proof required"
    required_fills = (
        "proposed_peer_ticker, peer_group, source, as_of_date, relationship_rationale, reviewer, review_date"
    )
    rows: list[dict[str, object]] = []
    for row in packet.rows[: max(limit, 0)]:
        completion = peer_mapping_source_review_completion(row, packet.freshness)
        import_preview = peer_mapping_import_preview(row, packet.freshness)
        rows.append(
            {
                "Review Gate": review_gate,
                "Ticker": row.ticker,
                "Mapping Slot": row.mapping_slot,
                "Completion Status": completion.status.replace("_", " "),
                "Missing Fields": ", ".join(completion.missing_fields) if completion.missing_fields else "none",
                "Import Preview Status": import_preview.status.replace("_", " "),
                "Required Fills": required_fills,
                "Target File": row.target_file,
                "CSV Header": import_preview.csv_header,
                "CSV Row": import_preview.csv_row or "blocked until completion-ready",
                "Next Safe Action": completion.next_safe_action,
                "Import Row Scaffold": completion.import_row_scaffold,
                "Apply Boundary": import_preview.apply_boundary,
                "Post-Apply Proof": import_preview.post_apply_proof,
                "Validation Path": row.validation_sequence,
                "Do Not Proceed If": row.do_not_proceed_if,
                "Candidate Context State": row.candidate_context_state,
                "Candidate Context Source": row.candidate_context_source,
                "Candidate Context Count": row.candidate_context_count,
                "Candidate Context Peers": row.candidate_context_peers or "-",
                "Candidate Context Boundary": row.candidate_context_note,
                "Freshness Context": f"{freshness_status}: {packet.freshness.message}",
            }
        )
    return pd.DataFrame(rows, columns=columns)


def data_health_peer_source_review_cards(packet: PeerMappingSourceReviewPacket | None) -> list[dict[str, object]]:
    if packet is None:
        return [
            {
                "kicker": "PEER SOURCE REVIEW",
                "title": "Build peer readiness first",
                "body": "No peer source-review packet is loaded. Rebuild readiness and the peer queue before editing peer import rows.",
                "badges": ["readiness first", "no guessed peers"],
                "command": "make readiness && make peer-mapping-queue TOP_N=25",
            }
        ]
    if packet.freshness.status in {"missing", "stale"}:
        return [
            {
                "kicker": "PEER SOURCE REVIEW",
                "title": "Refresh readiness before peer review",
                "body": (
                    f"Freshness status is {packet.freshness.status}. Do not use stale peer rows as proof; refresh readiness, "
                    "then regenerate the peer mapping source-review packet."
                ),
                "badges": ["freshness gate", "blocked"],
                "command": packet.freshness.refresh_command,
            }
        ]
    if not packet.rows:
        return [
            {
                "kicker": "PEER SOURCE REVIEW",
                "title": "No source-review rows",
                "body": "No missing peer-mapping rows are visible in the current peer readiness report. Rebuild the peer queue before assuming peer valuation is available.",
                "badges": ["current output", "no inferred peers"],
                "command": "make peer-mapping-queue TOP_N=25",
            }
        ]

    first = packet.rows[0]
    first_completion = peer_mapping_source_review_completion(first, packet.freshness)
    first_import_preview = peer_mapping_import_preview(first, packet.freshness)
    candidate_rows = [
        row for row in packet.rows if str(row.candidate_context_state or "").strip() == "candidate_context_only"
    ]
    tickers = ", ".join(packet.tickers[:3])
    if len(packet.tickers) > 3:
        tickers += ", ..."
    required_fills = "peer ticker, peer group, source, as-of date, rationale, reviewer, review date"
    return [
        {
            "kicker": "PEER SOURCE REVIEW",
            "title": f"{len(packet.rows)} fillable source-proof slot(s)",
            "body": (
                f"Scope: {tickers}. Use this before editing data/imports/peers.csv. "
                f"Candidate-only context appears for {len(candidate_rows)} slot(s). "
                "The packet scaffolds proof fields; it does not infer peer relationships or unlock peer valuation."
            ),
            "badges": ["manual source proof", "candidate context separated", "copy-only"],
            "command": f"DRY_RUN=1 make peer-mapping-source-review TOP_N={packet.top_n}",
        },
        {
            "kicker": "TOP PROOF SLOT",
            "title": f"{first.ticker} / {first.mapping_slot}",
            "body": (
                f"Status: {first_completion.status.replace('_', ' ')}. Missing fields: "
                f"{', '.join(first_completion.missing_fields) if first_completion.missing_fields else 'none'}. "
                f"Required fills: {required_fills}. Accepted proof must name the peer relationship or comparable business context; "
                f"candidate context for this slot is {first.candidate_context_state} via {first.candidate_context_source} "
                f"({first.candidate_context_count} lead(s): {first.candidate_context_peers or '-'}). "
                "Classification similarity alone stays fallback context."
            ),
            "badges": ["source-backed", "not a valuation input yet"],
            "command": first.focus_command,
        },
        {
            "kicker": "IMPORT ROW BOUNDARY",
            "title": first_import_preview.status.replace("_", " "),
            "body": (
                f"Header: {first_import_preview.csv_header}. Row: {first_import_preview.csv_row or 'blocked until completion-ready'}. "
                f"{first_import_preview.apply_boundary}"
            ),
            "badges": ["no hand-edit shortcut", "validate before apply"],
            "command": first_import_preview.validation_command,
        },
        {
            "kicker": "WRITE-BACK GUARD",
            "title": "Check duplicates, then prepare proof",
            "body": (
                "After source fields are reviewed, run the guard with the reviewed values. It blocks placeholders, stale readiness, self-peers, and duplicate peer pairs before any CSV edit, then prints the dry-run proof-record scaffold."
            ),
            "badges": ["copy-only", "duplicate check", "proof scaffold"],
            "command": (
                "make peer-mapping-writeback-guard TICKER=<ticker> PEER_TICKER=<peer> "
                'PEER_GROUP="<group>" SOURCE="<url>" AS_OF_DATE=<yyyy-mm-dd> '
                'REVIEWER="<name>" REVIEW_DATE=<yyyy-mm-dd> SOURCE_PROOF_STATUS=reviewed IMPORT_ROW_READY=yes'
            ),
        },
        {
            "kicker": "VALIDATE BEFORE APPLY",
            "title": "Reviewed rows still need import gates",
            "body": (
                "After source review, run validate and preview first. Apply only reviewed rows, then rebuild readiness and the peer queue before reading peer-relative context."
            ),
            "badges": ["validate", "preview", "proof after apply"],
            "command": (
                "make imports-validate IMPORT_TICKERS=<ticker-or-reviewed-batch> && "
                "make imports-preview IMPORT_TICKERS=<ticker-or-reviewed-batch> && "
                "make imports-apply IMPORT_TICKERS=<ticker-or-reviewed-batch> && make readiness && make peer-mapping-queue TOP_N=25"
            ),
        },
    ]


def data_health_peer_proof_batch_planner_frame(
    packet: PeerMappingSourceReviewPacket | None,
    batch_proof_frame: pd.DataFrame | None = None,
) -> pd.DataFrame:
    columns = ["Step", "Status", "Scope", "Copy-Ready Action", "Review Boundary"]
    if packet is None:
        return pd.DataFrame(
            [
                {
                    "Step": "1. Confirm peer proof scope",
                    "Status": "missing_packet",
                    "Scope": "no peer source-review packet",
                    "Copy-Ready Action": "make readiness && make peer-mapping-source-review TOP_N=10",
                    "Review Boundary": "Rebuild readiness and peer source-review rows before planning peer proof.",
                }
            ],
            columns=columns,
        )
    if packet.freshness.status in {"missing", "stale"}:
        return pd.DataFrame(
            [
                {
                    "Step": "1. Confirm peer proof scope",
                    "Status": f"blocked_by_{packet.freshness.status}",
                    "Scope": packet.freshness.message,
                    "Copy-Ready Action": packet.freshness.refresh_command,
                    "Review Boundary": "Do not use stale or missing peer readiness artifacts as proof.",
                }
            ],
            columns=columns,
        )
    if not packet.rows:
        return pd.DataFrame(
            [
                {
                    "Step": "1. Confirm peer proof scope",
                    "Status": "no_source_rows",
                    "Scope": "current peer queue has no source-review rows",
                    "Copy-Ready Action": "make peer-mapping-queue TOP_N=25",
                    "Review Boundary": "No peer import or proof-record row is available without source-backed peer rows.",
                }
            ],
            columns=columns,
        )

    first = packet.rows[0]
    completion = peer_mapping_source_review_completion(first, packet.freshness)
    preview = peer_mapping_import_preview(first, packet.freshness)
    guard_status = "ready_for_validate_preview" if preview.status == "ready_for_validate_preview" else "blocked"
    proof_record_command = peer_mapping_proof_record_command(first, guard_status)
    tickers = ",".join(packet.tickers[: max(packet.top_n, 1)]) or first.ticker
    source_packet_command = f"DRY_RUN=1 make peer-mapping-source-review TOP_N={packet.top_n}"
    reviewed_batch_packet = f"DRY_RUN=1 make reviewed-batch LANE=peers TICKERS={tickers}"
    latest = data_health_peer_latest_proof_row(batch_proof_frame)
    latest_status = "not_recorded"
    if not latest.empty:
        outcome_col = _data_health_case_column(batch_proof_frame, "final_outcome", "Final Outcome")
        latest_status = format_missing(latest.get(outcome_col), "not_recorded").lower() if outcome_col else "not_recorded"
    return pd.DataFrame(
        [
            {
                "Step": "1. Confirm peer proof scope",
                "Status": packet.freshness.status,
                "Scope": f"{len(packet.rows):,} source-review slot(s); tickers: {tickers}",
                "Copy-Ready Action": source_packet_command,
                "Review Boundary": "Plan a capped peer proof batch; source review does not infer comparable companies.",
            },
            {
                "Step": "2. Fill source-review fields",
                "Status": completion.status,
                "Scope": f"{first.ticker} / {first.mapping_slot}",
                "Copy-Ready Action": first.focus_command,
                "Review Boundary": (
                    "Missing fields: "
                    f"{', '.join(completion.missing_fields) if completion.missing_fields else 'none'}. "
                    "The source must name the peer relationship or comparable business context."
                ),
            },
            {
                "Step": "3. Preview reviewed batch packet",
                "Status": "dry_run_first",
                "Scope": tickers,
                "Copy-Ready Action": reviewed_batch_packet,
                "Review Boundary": "Packet preview is copy-only; peer valuation remains locked until reviewed rows pass readiness.",
            },
            {
                "Step": "4. Run write-back guard",
                "Status": preview.status,
                "Scope": f"{first.ticker} / {first.proposed_peer_ticker or '<peer_ticker>'}",
                "Copy-Ready Action": (
                    "make peer-mapping-writeback-guard TICKER=<ticker> PEER_TICKER=<peer> "
                    'PEER_GROUP="<group>" SOURCE="<url>" AS_OF_DATE=<yyyy-mm-dd> '
                    'REVIEWER="<name>" REVIEW_DATE=<yyyy-mm-dd> SOURCE_PROOF_STATUS=reviewed IMPORT_ROW_READY=yes'
                ),
                "Review Boundary": "Guard blocks placeholders, stale readiness, self-peers, and duplicate peer pairs before CSV edits.",
            },
            {
                "Step": "5. Validate, preview, and rebuild",
                "Status": "copy_only_gate",
                "Scope": first.target_file,
                "Copy-Ready Action": (
                    "make imports-validate IMPORT_TICKERS=<ticker-or-reviewed-batch> && "
                    "make imports-preview IMPORT_TICKERS=<ticker-or-reviewed-batch> && "
                    "make imports-apply IMPORT_TICKERS=<ticker-or-reviewed-batch> && make readiness && make peer-mapping-queue TOP_N=25"
                ),
                "Review Boundary": "Apply only reviewed rows after validate, preview, rejected-row review, and an explicit apply decision.",
            },
            {
                "Step": "6. Record proof outcome",
                "Status": "ready_for_review_fields" if guard_status == "ready_for_validate_preview" else "blocked_by_guard",
                "Scope": f"latest ledger outcome: {latest_status}",
                "Copy-Ready Action": proof_record_command,
                "Review Boundary": "Fill validation result, preview result, apply result, changed counts, changed tickers, source files, and artifact review before recording.",
            },
            {
                "Step": "7. Stop rule",
                "Status": "stop_if_missing_source_proof",
                "Scope": first.ticker,
                "Copy-Ready Action": "do not proceed",
                "Review Boundary": first.do_not_proceed_if,
            },
        ],
        columns=columns,
    )


def data_health_peer_proof_batch_planner_cards(
    packet: PeerMappingSourceReviewPacket | None,
    batch_proof_frame: pd.DataFrame | None = None,
) -> list[dict[str, object]]:
    planner = data_health_peer_proof_batch_planner_frame(packet, batch_proof_frame)
    if planner.empty:
        return [
            {
                "kicker": "PEER BATCH PLANNER",
                "title": "No peer batch plan available",
                "body": "Rebuild peer readiness before planning source-backed peer proof.",
                "badges": ["blocked visible", "no inferred peers"],
                "command": "make peer-mapping-queue TOP_N=25",
            }
        ]
    first = planner.iloc[0]
    packet_row = planner.loc[planner["Step"].eq("3. Preview reviewed batch packet")]
    packet_action = packet_row.iloc[0]["Copy-Ready Action"] if not packet_row.empty else first.get("Copy-Ready Action")
    stop = planner.iloc[-1]
    blocking = planner.loc[
        ~planner["Status"].astype(str).str.lower().isin(
            {"current", "fresh", "dry_run_first", "copy_only_gate", "ready_for_validate_preview", "ready_for_review_fields"}
        )
    ]
    return [
        {
            "kicker": "PEER BATCH PLANNER",
            "title": format_missing(first.get("Scope"), "peer proof scope pending"),
            "body": (
                f"{card_sentence('Blocking steps', len(blocking))} "
                f"{card_sentence('Packet', packet_action)} "
                f"{card_sentence('Stop rule', compact_card_fragment(stop.get('Review Boundary'), max_chars=180))}"
            ),
            "badges": ["capped proof", "source-backed only"],
            "command": format_missing(first.get("Copy-Ready Action"), "DRY_RUN=1 make peer-mapping-source-review TOP_N=10"),
        }
    ]


def data_health_peer_latest_proof_row(batch_proof_frame: pd.DataFrame | None) -> pd.Series:
    return latest_peer_proof_row(batch_proof_frame)


def data_health_peer_proof_loop_outcome_frame(
    packet: PeerMappingSourceReviewPacket | None,
    batch_proof_frame: pd.DataFrame | None,
    comparison: ReadinessComparison | None = None,
) -> pd.DataFrame:
    source_status = "not_loaded"
    source_detail = "Run make peer-mapping-source-review TOP_N=10."
    source_action = "DRY_RUN=1 make peer-mapping-source-review TOP_N=10"
    guard_status = "not_loaded"
    guard_detail = "Open peer source review before preparing a write-back guard."
    guard_command = "make peer-mapping-writeback-guard ..."
    proof_record_status = "not_loaded"
    proof_record_detail = "Open the write-back guard before preparing a proof-record scaffold."
    proof_record_command = "DRY_RUN=1 make reviewed-batch-proof-record ..."

    if packet is None:
        source_status = "missing_packet"
        source_detail = "Rebuild readiness and the peer source-review packet before recording peer proof."
    elif packet.freshness.status in {"missing", "stale"}:
        source_action = packet.freshness.refresh_command
        source_status = "blocked_by_freshness"
        source_detail = f"{packet.freshness.status}: {packet.freshness.message}"
        guard_status = "blocked_by_freshness"
        guard_detail = "Refresh readiness before peer write-back or proof-record review."
        guard_command = packet.freshness.refresh_command
        proof_record_status = "blocked_by_freshness"
        proof_record_detail = "Do not record peer proof from stale readiness artifacts."
        proof_record_command = packet.freshness.refresh_command
    elif not packet.rows:
        source_action = f"DRY_RUN=1 make peer-mapping-source-review TOP_N={packet.top_n}"
        source_status = "no_source_rows"
        source_detail = "No missing peer-mapping rows are visible in the current peer readiness report."
        guard_status = "not_applicable"
        guard_detail = "No peer import row is available for guard review."
        proof_record_status = "not_applicable"
        proof_record_detail = "No peer proof-record row is available without a reviewed peer source row."
    else:
        source_action = f"DRY_RUN=1 make peer-mapping-source-review TOP_N={packet.top_n}"
        completion_counts: dict[str, int] = {}
        preview_counts: dict[str, int] = {}
        for row in packet.rows:
            completion = peer_mapping_source_review_completion(row, packet.freshness)
            preview = peer_mapping_import_preview(row, packet.freshness)
            completion_counts[completion.status] = completion_counts.get(completion.status, 0) + 1
            preview_counts[preview.status] = preview_counts.get(preview.status, 0) + 1
        source_status = "ready_for_validate_preview" if set(completion_counts) == {"ready_for_validate_preview"} else "needs_field_fills"
        source_detail = ", ".join(f"{status}: {count}" for status, count in completion_counts.items())
        first = packet.rows[0]
        first_completion = peer_mapping_source_review_completion(first, packet.freshness)
        first_preview = peer_mapping_import_preview(first, packet.freshness)
        guard_ready = first_preview.status == "ready_for_validate_preview"
        guard_status = "ready_for_guard" if guard_ready else first_preview.status
        guard_detail = (
            f"First slot {first.ticker} / {first.mapping_slot}; "
            f"missing fields: {', '.join(first_completion.missing_fields) if first_completion.missing_fields else 'none'}; "
            f"preview statuses: {', '.join(f'{status}: {count}' for status, count in preview_counts.items())}"
        )
        guard_result_status = "ready_for_validate_preview" if guard_ready else "blocked"
        proof_record_status = "ready_for_review_fields" if guard_ready else "blocked_by_guard"
        proof_record_missing = peer_mapping_proof_record_missing_fields(guard_result_status)
        proof_record_detail = (
            "Missing proof-record fields: "
            f"{', '.join(proof_record_missing) if proof_record_missing else 'none'}; "
            "copy only after source review, guard, validate, preview, apply decision, readiness rebuild, and artifact hygiene."
        )
        proof_record_command = peer_mapping_proof_record_command(first, guard_result_status)

    latest = data_health_peer_latest_proof_row(batch_proof_frame)
    latest_status = "not_recorded"
    latest_detail = "No peer reviewed batch proof row recorded yet."
    latest_command = "make reviewed-batch-proof"
    if not latest.empty:
        latest_status, latest_detail, latest_command = latest_proof_status_detail(
            batch_proof_frame,
            latest,
            empty_detail=latest_detail,
        )
    comparison_status = "deferred"
    comparison_detail = "Open Proof review details before using changed counts in a peer proof row."
    comparison_command = "Open Proof review details."
    if comparison is not None:
        comparison_command = "make reviewed-batch-compare LANE=peers"
        if comparison.status != "ok":
            comparison_status = comparison.status
            comparison_detail = comparison.blocking_message or "Snapshot comparison is blocked until before/after readiness reports exist."
            comparison_command = "make readiness-snapshot" if comparison.status == "missing_before" else "make readiness"
        elif comparison.blocking_message:
            comparison_status = "stale_snapshot_warning"
            comparison_detail = (
                f"{comparison.blocking_message} Changed counts: "
                f"{compact_card_fragment(comparison.changed_readiness_counts, max_chars=150)}."
            )
        else:
            comparison_status = "ready"
            changed_tickers = ", ".join(comparison.changed_tickers) if comparison.changed_tickers else "none"
            comparison_detail = (
                f"{comparison.changed_count} changed ticker(s); "
                f"{compact_card_fragment(comparison.changed_readiness_counts, max_chars=140)}; "
                f"changed tickers: {compact_card_fragment(changed_tickers, max_chars=100)}"
            )

    return pd.DataFrame(
        [
            {
                "Proof Loop Step": "Source-review intake",
                "Status": source_status,
                "Detail": source_detail,
                "Next Safe Action": source_action,
            },
            {
                "Proof Loop Step": "Write-back guard",
                "Status": guard_status,
                "Detail": guard_detail,
                "Next Safe Action": guard_command,
            },
            {
                "Proof Loop Step": "Validate / preview / rebuild",
                "Status": "copy_only_gate",
                "Detail": "Validate and preview reviewed peer rows, apply only after review, then rebuild readiness and peer queue before peer-relative context changes.",
                "Next Safe Action": (
                    "make imports-validate IMPORT_TICKERS=<ticker-or-reviewed-batch> && "
                    "make imports-preview IMPORT_TICKERS=<ticker-or-reviewed-batch> && "
                    "make imports-apply IMPORT_TICKERS=<ticker-or-reviewed-batch> && make readiness && make peer-mapping-queue TOP_N=25"
                ),
            },
            {
                "Proof Loop Step": "Proof-record scaffold",
                "Status": proof_record_status,
                "Detail": proof_record_detail,
                "Next Safe Action": proof_record_command,
            },
            {
                "Proof Loop Step": "Before / after readiness comparison",
                "Status": comparison_status,
                "Detail": comparison_detail,
                "Next Safe Action": comparison_command,
            },
            {
                "Proof Loop Step": "Latest peer ledger outcome",
                "Status": latest_status,
                "Detail": latest_detail,
                "Next Safe Action": latest_command,
            },
        ]
    )


def data_health_peer_proof_loop_outcome_cards(
    packet: PeerMappingSourceReviewPacket | None,
    batch_proof_frame: pd.DataFrame | None,
    comparison: ReadinessComparison | None = None,
) -> list[dict[str, object]]:
    outcome = data_health_peer_proof_loop_outcome_frame(packet, batch_proof_frame, comparison)
    return proof_outcome_cards_from_frame(
        outcome,
        kicker="PEER PROOF OUTCOME",
        empty_title="No proof-loop status loaded",
        empty_body="Open peer source review before recording peer mapping or peer valuation outcomes.",
        empty_badges=["readiness first", "blocked visible"],
        empty_command="make peer-mapping-source-review TOP_N=10",
        latest_title_prefix="Latest ledger outcome",
        decision_sentence="Use this summary to decide whether peer mapping is supported, still blocked, skipped, or only scaffolded.",
        badges=["proof loop", "no inferred peers"],
        fallback_command="make reviewed-batch-proof",
        status_max_chars=220,
    )


def data_health_peer_proof_closeout_frame(
    packet: PeerMappingSourceReviewPacket | None,
    batch_proof_frame: pd.DataFrame | None,
    comparison: ReadinessComparison | None = None,
) -> pd.DataFrame:
    outcome = data_health_peer_proof_loop_outcome_frame(packet, batch_proof_frame, comparison)
    return proof_closeout_frame_from_outcome(
        outcome,
        latest_step="Latest peer ledger outcome",
        empty_evidence="Open the peer proof outcome loop before closeout.",
        empty_action="make peer-mapping-source-review TOP_N=10",
        empty_boundary="Do not close a peer proof loop without source proof, comparison, and ledger outcome.",
        fallback_action="make peer-mapping-source-review TOP_N=10",
        complete_action="make reviewed-batch-proof",
        record_action="DRY_RUN=1 make reviewed-batch-proof-record ...",
        record_evidence="Record a reviewed ledger outcome after peer source files, comparison, and generated artifacts are reviewed.",
        boundary=(
            "Closeout is evidence for peer-data readiness only; supported, still_blocked, skipped, and excluded are proof states, "
            "not investment advice, rankings, or trading instructions."
        ),
    )


def data_health_peer_proof_closeout_cards(
    packet: PeerMappingSourceReviewPacket | None,
    batch_proof_frame: pd.DataFrame | None,
    comparison: ReadinessComparison | None = None,
) -> list[dict[str, object]]:
    closeout = data_health_peer_proof_closeout_frame(packet, batch_proof_frame, comparison)
    return proof_closeout_cards_from_frame(
        closeout,
        kicker="PEER CLOSEOUT",
        empty_title="Peer closeout is not loaded",
        empty_body="Open the peer proof outcome loop before deciding whether the proof is supported, still blocked, skipped, or excluded.",
        empty_badges=["blocked visible", "no inferred peers"],
        empty_command="make peer-mapping-source-review TOP_N=10",
        fallback_command="make reviewed-batch-proof",
    )


def data_health_peer_proof_completion_checklist_frame(
    packet: PeerMappingSourceReviewPacket | None,
    batch_proof_frame: pd.DataFrame | None,
) -> pd.DataFrame:
    columns = ["Checklist Item", "Status", "Need Before Proceeding", "Next Safest Action", "Stop Rule"]
    if packet is None:
        return pd.DataFrame(
            [
                {
                    "Checklist Item": "1. Build peer source-review packet",
                    "Status": "missing_packet",
                    "Need Before Proceeding": "Rebuild readiness and generate the peer source-review packet before source proof.",
                    "Next Safest Action": "make readiness && make peer-mapping-source-review TOP_N=10",
                    "Stop Rule": "Stop if peer readiness artifacts are missing; do not infer peer rows.",
                }
            ],
            columns=columns,
        )

    proof_loop = data_health_peer_proof_loop_outcome_frame(packet, batch_proof_frame)
    source_frame = data_health_peer_source_review_frame(packet)
    freshness_status = format_missing(packet.freshness.status, "unknown")
    freshness_need = packet.freshness.message if freshness_status not in {"current", "fresh"} else "freshness current"
    source_status = "no_source_rows"
    source_need = "No peer source-review rows are loaded."
    if not source_frame.empty:
        statuses = source_frame["Completion Status"].fillna("").astype(str).value_counts()
        source_status = "ready_for_validate_preview" if set(statuses.index) == {"ready for validate preview"} else "needs_field_fills"
        missing_fields = sorted(
            {
                field.strip()
                for value in source_frame["Missing Fields"].fillna("").astype(str).tolist()
                for field in value.split(",")
                if field.strip() and field.strip().lower() != "none"
            }
        )
        source_need = "reviewed peer source fields complete" if not missing_fields else ", ".join(missing_fields)

    def _proof_row(step: str, field: str, fallback: str) -> str:
        if proof_loop.empty:
            return fallback
        rows = proof_loop.loc[proof_loop["Proof Loop Step"].eq(step)]
        if rows.empty:
            return fallback
        return format_missing(rows.iloc[0].get(field), fallback)

    guard_status = _proof_row("Write-back guard", "Status", "not_loaded")
    guard_need = _proof_row("Write-back guard", "Detail", "Open peer source review before guard review.")
    guard_command = _proof_row("Write-back guard", "Next Safe Action", "make peer-mapping-writeback-guard ...")
    proof_status = _proof_row("Proof-record scaffold", "Status", "not_loaded")
    proof_need = _proof_row("Proof-record scaffold", "Detail", "Open the write-back guard before proof-record review.")
    proof_command = _proof_row("Proof-record scaffold", "Next Safe Action", "DRY_RUN=1 make reviewed-batch-proof-record ...")
    ledger_status = _proof_row("Latest peer ledger outcome", "Status", "not_recorded")
    ledger_need = _proof_row("Latest peer ledger outcome", "Detail", "No peer reviewed batch proof row recorded yet.")
    packet_command = f"DRY_RUN=1 make peer-mapping-source-review TOP_N={packet.top_n}"
    tickers = ", ".join(packet.tickers[:10]) if packet.tickers else "<reviewed_tickers>"
    return pd.DataFrame(
        [
            {
                "Checklist Item": "1. Confirm freshness and packet scope",
                "Status": freshness_status,
                "Need Before Proceeding": f"{freshness_need}; tickers: {tickers}",
                "Next Safest Action": packet.freshness.refresh_command if freshness_status in {"missing", "stale"} else packet_command,
                "Stop Rule": "Stop if readiness is stale or missing; do not use stale peer rows as proof.",
            },
            {
                "Checklist Item": "2. Fill peer source-review fields",
                "Status": source_status,
                "Need Before Proceeding": source_need,
                "Next Safest Action": packet_command,
                "Stop Rule": "Stop if the source does not name the peer relationship or comparable business context.",
            },
            {
                "Checklist Item": "3. Pass write-back guard",
                "Status": guard_status,
                "Need Before Proceeding": guard_need,
                "Next Safest Action": guard_command,
                "Stop Rule": "Stop if placeholders, stale readiness, self-peers, or duplicate peer pairs are present.",
            },
            {
                "Checklist Item": "4. Validate, preview, and rebuild peer proof",
                "Status": "copy_only_gate",
                "Need Before Proceeding": "Validate and preview reviewed peer rows, apply only after review, rebuild readiness, then rerun the peer queue.",
                "Next Safest Action": (
                    "make imports-validate IMPORT_TICKERS=<ticker-or-reviewed-batch> && "
                    "make imports-preview IMPORT_TICKERS=<ticker-or-reviewed-batch> && "
                    "make imports-apply IMPORT_TICKERS=<ticker-or-reviewed-batch> && make readiness && make peer-mapping-queue TOP_N=25"
                ),
                "Stop Rule": "Stop if validate, preview, apply decision, or rebuilt readiness proof is missing.",
            },
            {
                "Checklist Item": "5. Record reviewed peer proof outcome",
                "Status": proof_status,
                "Need Before Proceeding": proof_need,
                "Next Safest Action": proof_command,
                "Stop Rule": "Copy proof-record command only after source files, changed counts, changed tickers, and generated artifacts are reviewed.",
            },
            {
                "Checklist Item": "6. Check latest peer ledger outcome",
                "Status": ledger_status,
                "Need Before Proceeding": ledger_need,
                "Next Safest Action": "make reviewed-batch-proof",
                "Stop Rule": "A missing or still-blocked ledger outcome is honest evidence; do not call the peer lane supported without proof.",
            },
        ],
        columns=columns,
    )


def data_health_peer_proof_completion_checklist_cards(
    packet: PeerMappingSourceReviewPacket | None,
    batch_proof_frame: pd.DataFrame | None,
) -> list[dict[str, object]]:
    checklist = data_health_peer_proof_completion_checklist_frame(packet, batch_proof_frame)
    if checklist.empty:
        return [
            {
                "kicker": "PEER PROOF CHECKLIST",
                "title": "No peer proof checklist loaded",
                "body": "Build the peer source-review packet before reviewing import or proof-record gates.",
                "badges": ["blocked visible", "no inferred peers"],
                "command": "make peer-mapping-source-review TOP_N=10",
            }
        ]
    blocking = checklist.loc[
        ~checklist["Status"].astype(str).str.lower().isin(
            {"current", "fresh", "ready_for_validate_preview", "copy_only_gate", "ready_for_review_fields", "supported"}
        )
    ]
    if blocking.empty:
        title = "Peer proof checklist ready for final review"
        first = checklist.iloc[-1]
        badges = ["ready after review", "source-backed only"]
    else:
        title = f"Finish peer proof: {len(blocking)} step(s) need review"
        first = blocking.iloc[0]
        badges = ["finish proof", "no inferred peers"]
    return [
        {
            "kicker": "PEER PROOF CHECKLIST",
            "title": title,
            "body": (
                f"{card_sentence('Next item', first.get('Checklist Item'))} "
                f"{card_sentence('Needed', compact_card_fragment(first.get('Need Before Proceeding'), max_chars=190))} "
                "Use this checklist before reading source-review, write-back, or peer proof tables."
            ),
            "badges": badges,
            "command": format_missing(first.get("Next Safest Action"), "make peer-mapping-source-review TOP_N=10"),
        }
    ]


def data_health_peer_operator_summary_frame(
    packet: PeerMappingSourceReviewPacket | None,
    batch_proof_frame: pd.DataFrame | None,
    comparison: ReadinessComparison | None = None,
) -> pd.DataFrame:
    checklist = data_health_peer_proof_completion_checklist_frame(packet, batch_proof_frame)
    outcome = data_health_peer_proof_loop_outcome_frame(packet, batch_proof_frame, comparison)
    return peer_operator_summary_frame(packet, checklist, outcome)


def data_health_peer_operator_summary_cards(
    packet: PeerMappingSourceReviewPacket | None,
    batch_proof_frame: pd.DataFrame | None,
    comparison: ReadinessComparison | None = None,
) -> list[dict[str, object]]:
    summary = data_health_peer_operator_summary_frame(packet, batch_proof_frame, comparison)
    return peer_operator_summary_cards(summary)


