def _dcf_missing_field_key(value: object) -> str:
    text = format_missing(value, "")
    if not text:
        return ""
    text = text.strip().strip("`.,;:")
    if text.lower().startswith("missing "):
        text = text[8:].strip()
    text = text.lower().replace("-", "_").replace(" ", "_")
    return re.sub(r"[^a-z0-9_]", "", text)


def dcf_missing_field_guide_frame(
    dcf_readiness_frame: pd.DataFrame | None,
    *,
    sec_configured: bool = False,
    limit: int = 6,
) -> pd.DataFrame:
    columns = [
        "Missing Input",
        "Affected Companies",
        "Example Tickers",
        "Price-Ready Examples",
        "Why It Matters",
        "Trusted Input Path",
        "Schema Fields",
        "Next Safe Sequence",
        "Validation Path",
        "Conclusion Boundary",
        "Copy-Only Command",
    ]
    if dcf_readiness_frame is None or dcf_readiness_frame.empty or "missing_dcf_fields" not in dcf_readiness_frame.columns:
        return pd.DataFrame(columns=columns)

    frame = dcf_readiness_frame.copy()
    if "ticker" in frame.columns:
        frame["ticker"] = frame["ticker"].astype(str).str.upper().str.strip()
    asset_type = frame.get("asset_type", pd.Series("company", index=frame.index)).fillna("").astype(str).str.lower()
    company = asset_type.eq("company") | asset_type.eq("")
    ready = bool_series(frame, "is_dcf_ready") if "is_dcf_ready" in frame.columns else pd.Series(False, index=frame.index)
    blocked = frame.loc[company & ~ready].copy()
    if blocked.empty:
        return pd.DataFrame(columns=columns)

    grouped: dict[str, list[str]] = {}
    price_ready_grouped: dict[str, list[str]] = {}
    for _, row in blocked.iterrows():
        ticker = format_missing(row.get("ticker"), "").upper()
        price_ready = str(row.get("has_price", "")).strip().lower() in {"true", "1", "yes", "y"}
        raw_fields = str(row.get("missing_dcf_fields") or row.get("reason_not_ready") or "").strip()
        if raw_fields.lower().startswith("missing "):
            raw_fields = raw_fields[8:].strip()
        field_parts = [part.strip() for part in re.split(r"[,;|]", raw_fields) if part.strip()]
        if not field_parts:
            field_parts = ["fundamentals"]
        for raw_field in field_parts:
            key = _dcf_missing_field_key(raw_field)
            if not key:
                continue
            grouped.setdefault(key, [])
            if ticker and ticker not in grouped[key]:
                grouped[key].append(ticker)
            price_ready_grouped.setdefault(key, [])
            if ticker and price_ready and ticker not in price_ready_grouped[key]:
                price_ready_grouped[key].append(ticker)

    rows: list[dict[str, object]] = []
    for key, tickers in sorted(grouped.items(), key=lambda item: (-len(item[1]), item[0]))[:limit]:
        detail = DCF_INPUT_TRIAGE.get(key, DCF_INPUT_TRIAGE["fundamentals"])
        label = public_status_label(key.replace("_", " "))
        price_ready_examples = price_ready_grouped.get(key, [])
        example_candidates = price_ready_examples if key not in {"price", "market_cap_or_price_and_shares"} and price_ready_examples else tickers
        example = example_candidates[0] if example_candidates else "TICKER"
        if key in {"price", "market_cap_or_price_and_shares"}:
            trusted_path = "data/imports/prices.csv or data/staged/prices/"
            schema_fields = "ticker, date, open, high, low, close, volume, source"
            command = f"make focus-price TICKER={example}"
            next_sequence = (
                f"1. Inspect `{command}`. 2. Run `make price-refresh-loop DRY_RUN=1` for a capped plan "
                "or prepare trusted OHLCV rows. 3. Run `make price-validate`, `make price-preview`, "
                "`make price-apply`, then `make dcf-readiness`."
            )
            validation_path = "make price-validate -> make price-preview -> make price-apply -> make dcf-readiness"
        else:
            trusted_path = "data/imports/fundamentals.csv or reviewed SEC staging rows in data/staged/fundamentals/"
            schema_fields = "ticker, period/report_date, revenue, free_cash_flow or fcf_margin, shares_outstanding, cash, debt, source, updated_at"
            command = f"make focus-fundamentals TICKER={example}"
            second_step = (
                f"2. Run `make sec-stage TICKERS={example}` when SEC_USER_AGENT is configured, "
                "or fill `data/imports/fundamentals.csv` with trusted manual rows."
                if sec_configured
                else "2. Run `make templates`, then fill `data/imports/fundamentals.csv` with trusted manual rows."
            )
            next_sequence = (
                f"1. Inspect `{command}`. {second_step} "
                f"3. Run `{scoped_import_sequence(ticker, separator='`, `')}`, then `make dcf-readiness`."
            )
            validation_path = f"{scoped_import_sequence(ticker)} -> make dcf-readiness"
        rows.append(
            {
                "Missing Input": label,
                "Affected Companies": len(tickers),
                "Example Tickers": ", ".join(tickers[:5]) if tickers else "Not available",
                "Price-Ready Examples": ", ".join(price_ready_examples[:5]) if price_ready_examples else "None yet",
                "Why It Matters": detail["why"],
                "Trusted Input Path": trusted_path,
                "Schema Fields": schema_fields,
                "Next Safe Sequence": next_sequence,
                "Validation Path": validation_path,
                "Conclusion Boundary": "DCF math, fair value/share, undervalued, overvalued, and peer-relative conclusions stay withheld until this trusted input passes readiness.",
                "Copy-Only Command": command,
            }
        )
    return pd.DataFrame(rows, columns=columns)


def dcf_missing_field_guide_cards(field_guide_frame: pd.DataFrame | None) -> list[dict[str, object]]:
    if field_guide_frame is None or field_guide_frame.empty:
        return [
            {
                "kicker": "DCF FIELD GUIDE",
                "title": "No blocked DCF fields loaded",
                "body": "Run DCF readiness before assuming company valuation inputs are complete.",
                "badges": ["readiness first", "no inference"],
                "command": "make dcf-readiness",
            }
        ]
    frame = field_guide_frame.copy()
    first = frame.iloc[0]
    affected = pd.to_numeric(frame.get("Affected Companies"), errors="coerce").fillna(0)
    total_affected = int(affected.sum())
    first_input = format_missing(first.get("Missing Input"), "the top missing input")
    first_examples = format_missing(first.get("Example Tickers"), "Not available")
    return [
        {
            "kicker": "DCF FIELD GUIDE",
            "title": f"{len(frame)} missing input type(s)",
            "body": (
                f"{total_affected} company field gap(s) are blocking DCF readiness. "
                f"Start with {first_input} for {first_examples}. "
                "Treat these as repair steps, not company-quality conclusions."
            ),
            "badges": ["field-level blockers", "no valuation inference"],
            "command": "make dcf-readiness",
        },
        {
            "kicker": "TOP MISSING INPUT",
            "title": first_input,
            "body": (
                f"Affected companies: {format_missing(first.get('Affected Companies'), '0')}. "
                f"Examples: {first_examples}. "
                f"Why it matters: {format_missing(first.get('Why It Matters'), '')}"
            ),
            "badges": ["one field first", "trusted data only"],
            "command": format_missing(first.get("Copy-Only Command"), "make dcf-readiness"),
        },
        {
            "kicker": "TRUSTED INPUT PATH",
            "title": format_missing(first.get("Trusted Input Path"), "Trusted input path"),
            "body": (
                f"Next proof: {validation_sequence_summary(first.get('Next Safe Sequence'))} "
                f"Schema fields: {format_missing(first.get('Schema Fields'), 'listed in make templates')}. "
                f"Validation proof: {validation_sequence_summary(first.get('Validation Path'))} "
                f"Boundary: {format_missing(first.get('Conclusion Boundary'), '')}"
            ),
            "badges": ["validate", "preview before apply"],
            "command": format_missing(first.get("Copy-Only Command"), "make dcf-readiness"),
        },
    ]


def fundamentals_dcf_function_quality_frame(
    ticker_readiness_frame: pd.DataFrame | None,
    dcf_readiness_frame: pd.DataFrame | None = None,
) -> pd.DataFrame:
    if ticker_readiness_frame is None or ticker_readiness_frame.empty:
        return pd.DataFrame(
            [
                {
                    "Function Area": "Fundamentals / DCF",
                    "Current Coverage": "Readiness not ready yet",
                    "Supported Today": "Nothing yet; run readiness before interpreting fundamentals or DCF status.",
                    "Not Supported Yet": "Any company valuation conclusion.",
                    "Methodology / Provenance": "Project readiness checks after make readiness.",
                    "Next Step": "make readiness",
                }
            ]
        )

    frame = ticker_readiness_frame.copy()
    company = frame.get("asset_type", pd.Series("", index=frame.index)).fillna("").astype(str).str.lower().eq("company")
    price_ready = bool_series(frame, "price_ready")
    fundamentals_ready = bool_series(frame, "fundamentals_ready")
    dcf_ready = bool_series(frame, "dcf_ready")
    peer_ready = bool_series(frame, "peer_ready")
    active = bool_series(frame, "in_active_universe")
    price_ready_missing_fundamentals = int((company & price_ready & ~fundamentals_ready).sum())
    active_missing_fundamentals = int((company & active & price_ready & ~fundamentals_ready).sum())
    fundamentals_ready_count = int((company & fundamentals_ready).sum())
    dcf_ready_count = int((company & dcf_ready).sum())
    dcf_ready_peer_blocked_count = int((company & dcf_ready & ~peer_ready).sum())

    missing_field_text = "Missing DCF field detail not loaded"
    excluded_count = 0
    if dcf_readiness_frame is not None and not dcf_readiness_frame.empty:
        dcf_frame = dcf_readiness_frame.copy()
        asset_type = dcf_frame.get("asset_type", pd.Series("", index=dcf_frame.index)).fillna("").astype(str).str.lower()
        excluded_count = int(asset_type.ne("company").sum())
        if "missing_dcf_fields" in dcf_frame.columns:
            missing_counts = dcf_frame["missing_dcf_fields"].fillna("").astype(str).str.split(r"[,;|]", regex=True).explode().str.strip()
            missing_counts = missing_counts.loc[missing_counts.ne("")]
            if not missing_counts.empty:
                missing_field_text = ", ".join(f"{field}: {count}" for field, count in missing_counts.value_counts().head(4).items())
            else:
                missing_field_text = "No missing DCF fields reported for saved rows"

    return pd.DataFrame(
        [
            {
                "Function Area": "Trusted fundamentals",
                "Current Coverage": f"{fundamentals_ready_count} fundamentals-ready company row(s)",
                "Supported Today": "Company snapshot and DCF input review when trusted local or SEC-backed rows exist.",
                "Not Supported Yet": "Filling missing revenue, cash-flow, margin, or share-count fields by inference.",
                "Methodology / Provenance": "Project import/readiness checks using trusted local CSV and SEC-staged rows.",
                "Next Step": "make sec-stage-queue TOP_N=25",
            },
            {
                "Function Area": "Price-ready but missing fundamentals",
                "Current Coverage": f"{price_ready_missing_fundamentals} company row(s); {active_missing_fundamentals} active-universe row(s)",
                "Supported Today": "Prioritizing which real fundamentals to stage, validate, preview, and apply next.",
                "Not Supported Yet": "Company valuation, quality score, or DCF interpretation.",
                "Methodology / Provenance": "Project readiness gates surface missing fundamentals instead of creating placeholder values.",
                "Next Step": "make sec-stage-queue TOP_N=25",
            },
            {
                "Function Area": "DCF-ready companies",
                "Current Coverage": f"{dcf_ready_count} company row(s)",
                "Supported Today": "Assumption and sensitivity review after required company DCF fields pass readiness.",
                "Not Supported Yet": "Recommendations or conclusions that require unavailable optional context.",
                "Methodology / Provenance": "Project DCF readiness and valuation method in src/valuation.py.",
                "Next Step": "make dcf-readiness",
            },
            {
                "Function Area": "Missing DCF fields",
                "Current Coverage": missing_field_text,
                "Supported Today": "Seeing exactly which input fields block company valuation.",
                "Not Supported Yet": "Treating missing inputs as a negative company signal.",
                "Methodology / Provenance": "Project DCF readiness report; missing fields are displayed, not guessed.",
                "Next Step": "make dcf-readiness",
            },
            {
                "Function Area": "DCF-ready but peer-blocked",
                "Current Coverage": f"{dcf_ready_peer_blocked_count} company row(s)",
                "Supported Today": "Standalone DCF review while peer-relative valuation stays withheld.",
                "Not Supported Yet": "Peer-relative valuation without source-backed peer mappings and peer inputs.",
                "Methodology / Provenance": "Project peer readiness checks; fallback sector context is not trusted peer valuation.",
                "Next Step": "make peer-mapping-queue TOP_N=10",
            },
            {
                "Function Area": "ETF / index / fund rows",
                "Current Coverage": f"{excluded_count} row(s) excluded from operating-company DCF",
                "Supported Today": "Market, theme, liquidity, or risk monitor context.",
                "Not Supported Yet": "Operating-company fundamentals or DCF valuation.",
                "Methodology / Provenance": "Project asset-type gating marks DCF excluded, not failed.",
                "Next Step": stock_report_md_command("QQQ"),
            },
        ]
    )


PEER_STUDIO_FILTERS = [
    "DCF-ready but peer-blocked",
    "Missing peer mapping",
    "Peer price missing",
    "Peer fundamentals missing",
    "Peer valuation blocked",
    "Peer trend comparison ready",
    "All peer-blocked",
]


def build_peer_mapping_studio_frame(
    peer_readiness_frame: pd.DataFrame | None,
    ticker_readiness_frame: pd.DataFrame | None = None,
    peer_unlock_worklist_frame: pd.DataFrame | None = None,
    *,
    filter_mode: str = "DCF-ready but peer-blocked",
    ticker_search: str = "",
    active_universe_only: bool = False,
    dcf_ready_only: bool = False,
    row_limit: int | None = 50,
) -> pd.DataFrame:
    if peer_readiness_frame is None or peer_readiness_frame.empty:
        return pd.DataFrame()
    frame = peer_readiness_frame.copy()
    if "ticker" not in frame.columns:
        return pd.DataFrame()
    frame["ticker"] = frame["ticker"].astype(str).str.upper().str.strip()

    if ticker_readiness_frame is not None and not ticker_readiness_frame.empty and "ticker" in ticker_readiness_frame.columns:
        readiness_columns = [
            column
            for column in [
                "ticker",
                "name",
                "asset_type",
                "theme",
                "in_active_universe",
                "price_ready",
                "dcf_ready",
                "fundamentals_ready",
                "overall_readiness_state",
                "decision_bucket",
                "next_action",
            ]
            if column in ticker_readiness_frame.columns
        ]
        readiness = ticker_readiness_frame[readiness_columns].copy()
        readiness["ticker"] = readiness["ticker"].astype(str).str.upper().str.strip()
        frame = frame.merge(readiness, on="ticker", how="left", suffixes=("", "_ticker"))

    if peer_unlock_worklist_frame is not None and not peer_unlock_worklist_frame.empty and "ticker" in peer_unlock_worklist_frame.columns:
        unlock_columns = [
            column
            for column in [
                "ticker",
                "priority",
                "unlock_stage",
                "workflow_group",
                "workflow_scope",
                "next_action_summary",
                "peer_trend_status",
                "peer_valuation_status",
                "next_input_file",
                "validation_sequence",
                "focus_command",
                "example_command",
                "copy_only_note",
            ]
            if column in peer_unlock_worklist_frame.columns
        ]
        unlock = peer_unlock_worklist_frame[unlock_columns].copy()
        unlock["ticker"] = unlock["ticker"].astype(str).str.upper().str.strip()
        frame = frame.merge(unlock, on="ticker", how="left", suffixes=("", "_unlock"))

    peer_ready = bool_series(frame, "peer_ready")
    dcf_ready = bool_series(frame, "dcf_ready")
    blocker = frame.get("peer_blocker_type", pd.Series("", index=frame.index)).fillna("").astype(str)

    if active_universe_only:
        frame = frame.loc[bool_series(frame, "in_active_universe")].copy()
        peer_ready = bool_series(frame, "peer_ready")
        dcf_ready = bool_series(frame, "dcf_ready")
        blocker = frame.get("peer_blocker_type", pd.Series("", index=frame.index)).fillna("").astype(str)
    if dcf_ready_only:
        frame = frame.loc[dcf_ready].copy()
        peer_ready = bool_series(frame, "peer_ready")
        dcf_ready = bool_series(frame, "dcf_ready")
        blocker = frame.get("peer_blocker_type", pd.Series("", index=frame.index)).fillna("").astype(str)

    if filter_mode == "DCF-ready but peer-blocked":
        frame = frame.loc[dcf_ready & ~peer_ready].copy()
    elif filter_mode == "Missing peer mapping":
        frame = frame.loc[blocker.eq("missing_peer_mapping")].copy()
    elif filter_mode == "Peer price missing":
        frame = frame.loc[blocker.eq("peer_price_missing")].copy()
    elif filter_mode == "Peer fundamentals missing":
        frame = frame.loc[blocker.eq("peer_fundamentals_missing")].copy()
    elif filter_mode == "Peer valuation blocked":
        frame = frame.loc[blocker.eq("peer_valuation_blocked")].copy()
    elif filter_mode == "Peer trend comparison ready":
        frame = frame.loc[bool_series(frame, "peer_trend_comparison_ready")].copy()
    elif filter_mode == "All peer-blocked":
        frame = frame.loc[~peer_ready].copy()

    if ticker_search.strip():
        search_columns = [
            column
            for column in [
                "ticker",
                "name",
                "theme",
                "peer_blocker_type",
                "missing_peer_reason",
                "next_peer_action",
                "sample_peers",
            ]
            if column in frame.columns
        ]
        if search_columns:
            mask = frame[search_columns].astype(str).apply(
                lambda row: row.str.contains(ticker_search, case=False, na=False).any(),
                axis=1,
            )
            frame = frame.loc[mask].copy()

    if "priority" in frame.columns:
        frame["priority"] = pd.to_numeric(frame["priority"], errors="coerce").fillna(999).astype(int)
    else:
        frame["priority"] = 999
    peer_ready = bool_series(frame, "peer_ready")
    dcf_ready = bool_series(frame, "dcf_ready")
    price_ready = bool_series(frame, "price_ready")
    active_scope = bool_series(frame, "in_active_universe")
    blocker = frame.get("peer_blocker_type", pd.Series("", index=frame.index)).fillna("").astype(str)
    missing_mapping = blocker.eq("missing_peer_mapping")
    missing_unlock_metadata = frame["priority"].ge(999)
    frame.loc[missing_unlock_metadata & dcf_ready & missing_mapping & ~peer_ready, "priority"] = 1
    frame.loc[missing_unlock_metadata & ~dcf_ready & price_ready & missing_mapping & ~peer_ready, "priority"] = 2
    if "workflow_scope" in frame.columns:
        frame["workflow_scope_rank"] = frame["workflow_scope"].map({"active_universe": 0, "master_universe": 1}).fillna(2).astype(int)
    else:
        frame["workflow_scope_rank"] = 2
        frame["workflow_scope"] = ""
    frame.loc[frame["workflow_scope"].fillna("").astype(str).str.strip().eq("") & active_scope, "workflow_scope"] = "active_universe"
    frame.loc[frame["workflow_scope"].fillna("").astype(str).str.strip().eq(""), "workflow_scope"] = "master_universe"
    frame["workflow_scope_rank"] = frame["workflow_scope"].map({"active_universe": 0, "master_universe": 1}).fillna(2).astype(int)
    if "workflow_group" not in frame.columns:
        frame["workflow_group"] = ""
    frame.loc[
        frame["workflow_group"].fillna("").astype(str).str.strip().eq("") & dcf_ready & missing_mapping & ~peer_ready,
        "workflow_group",
    ] = "dcf_ready_peer_mapping"
    frame.loc[
        frame["workflow_group"].fillna("").astype(str).str.strip().eq("") & price_ready & missing_mapping & ~peer_ready,
        "workflow_group",
    ] = "price_ready_peer_mapping"
    fallback_fields = {
        "unlock_stage": "add_source_backed_peer_mappings",
        "next_action_summary": "Add at least two trusted, source-backed peer rows; fallback sector/industry context is not trusted peer data.",
        "peer_trend_status": "peer_trend_blocked",
        "peer_valuation_status": "peer_valuation_blocked",
        "next_input_file": "data/imports/peers.csv",
        "validation_sequence": f"make templates -> fill source-backed peers -> {scoped_import_sequence()}",
        "example_command": "make peer-mapping-queue TOP_N=25",
        "copy_only_note": "Copy commands only; review import file rows before applying local CSV changes.",
    }
    fallback_mask = missing_mapping & ~peer_ready
    for column, fallback in fallback_fields.items():
        if column not in frame.columns:
            frame[column] = ""
        empty = frame[column].fillna("").astype(str).str.strip().eq("")
        frame.loc[fallback_mask & empty, column] = fallback
    if "next_action" not in frame.columns:
        frame["next_action"] = ""
    peer_action = frame["next_action_summary"].fillna("").astype(str).str.strip()
    frame.loc[fallback_mask & peer_action.ne(""), "next_action"] = peer_action.loc[fallback_mask & peer_action.ne("")]
    if "focus_command" not in frame.columns:
        frame["focus_command"] = ""
    empty_focus = frame["focus_command"].fillna("").astype(str).str.strip().eq("")
    frame.loc[fallback_mask & empty_focus, "focus_command"] = frame.loc[fallback_mask & empty_focus, "ticker"].apply(
        lambda ticker: f"make focus-peers TICKER={ticker}"
    )
    asset_type = frame.get("asset_type", pd.Series("", index=frame.index)).fillna("").astype(str).str.lower()
    monitor_proxy = asset_type.isin({"etf", "index_proxy", "fund"}) | asset_type.str.contains("etf|index|fund", na=False)
    if monitor_proxy.any():
        frame.loc[monitor_proxy, "workflow_group"] = "monitor_proxy_context"
        frame.loc[monitor_proxy, "next_action_summary"] = (
            "ETF/index/fund rows use stock-report monitoring context; fallback sector or peer context is not trusted peer data."
        )
        frame.loc[monitor_proxy, "next_action"] = frame.loc[monitor_proxy, "next_action_summary"]
        frame.loc[monitor_proxy, "peer_valuation_status"] = "operating_company_dcf_excluded"
        frame.loc[monitor_proxy, "next_input_file"] = frame.loc[monitor_proxy, "ticker"].apply(
            lambda ticker: f"outputs/stock_reports/{str(ticker).strip().lower()}.md"
        )
        frame.loc[monitor_proxy, "validation_sequence"] = frame.loc[monitor_proxy, "ticker"].apply(
            lambda ticker: f"{stock_report_md_command(ticker)} -> review source readiness and DCF exclusion"
        )
        frame.loc[monitor_proxy, "focus_command"] = frame.loc[monitor_proxy, "ticker"].apply(stock_report_md_command)
        frame.loc[monitor_proxy, "copy_only_note"] = "Copy command only; monitor context is not peer valuation."
    if "ticker" in frame.columns:
        frame = frame.sort_values(["priority", "workflow_scope_rank", "workflow_group", "ticker"], kind="stable").copy()
    frame = frame.drop(columns=["workflow_scope_rank"], errors="ignore")
    if row_limit is not None and row_limit > 0:
        frame = frame.head(row_limit).copy()
    return frame


def peer_mapping_studio_table_columns(frame: pd.DataFrame) -> list[str]:
    preferred = [
        "priority",
        "ticker",
        "name",
        "asset_type",
        "theme",
        "in_active_universe",
        "dcf_ready",
        "peer_ready",
        "peer_blocker_type",
        "unlock_stage",
        "workflow_group",
        "workflow_scope",
        "next_action_summary",
        "peer_trend_status",
        "peer_valuation_status",
        "mapping_status",
        "peer_count",
        "ready_peer_count",
        "peer_price_ready_count",
        "peer_momentum_ready_count",
        "peer_fundamentals_ready_count",
        "peer_valuation_ready_count",
        "sample_peers",
        "peer_missing_price_tickers",
        "peer_missing_fundamentals_tickers",
        "peer_missing_valuation_tickers",
        "missing_peer_reason",
        "next_peer_action",
        "next_input_file",
        "validation_sequence",
        "focus_command",
        "example_command",
        "copy_only_note",
    ]
    return [column for column in preferred if column in frame.columns]


def decision_next_action_summary(row: pd.Series) -> str:
    ticker = format_missing(row.get("ticker"), "Ticker")
    blocker = format_missing(row.get("primary_blocker"), "").lower().replace(" ", "_")
    asset_type = format_missing(row.get("asset_type"), row.get("asset_type_readiness", "")).lower()
    if asset_type in {"etf", "index_proxy", "fund"}:
        return f"Review {ticker} as ETF/index/fund monitor context; operating-company DCF and peer valuation stay excluded."
    dcf_ready = str(row.get("dcf_ready", "")).strip().lower() in {"true", "1", "yes", "y"}
    peer_ready = str(row.get("peer_ready", "")).strip().lower() in {"true", "1", "yes", "y"}
    stale_peer_action = "peer mappings and peer metrics" in format_missing(row.get("next_best_action"), "").lower()
    if blocker in {"peer", "peers"} and (dcf_ready or not peer_ready or stale_peer_action):
        return peer_mapping_unlock_action(ticker)
    if blocker == "fundamentals":
        return f"Import trusted fundamentals for {ticker}; use SEC staging workflow when configured or data/imports/fundamentals.csv, then validate and preview."
    if blocker == "price":
        return f"Refresh a capped price worklist before deeper analysis; start with make price-refresh-loop DRY_RUN=1, then review the planned batches."
    if blocker in {"earnings", "analyst_estimates", "optional_context"}:
        return f"Optional context for {ticker} stays unavailable until trusted local CSV rows are staged, validated, previewed, and applied."
    return compact_reason(row.get("next_best_action"), max_sentences=1, max_chars=180)


def decision_next_action_proof(row: pd.Series) -> str:
    ticker = format_missing(row.get("ticker"), "").upper()
    blocker = format_missing(row.get("primary_blocker"), "").lower().replace(" ", "_")
    asset_type = format_missing(row.get("asset_type"), row.get("asset_type_readiness", "")).lower()
    report_command = stock_report_md_command(ticker) if ticker else "make project-status"
    if asset_type in {"etf", "index_proxy", "fund"}:
        return f"Proof after review: run `{report_command}` and confirm operating-company DCF is excluded, not failed."
    if blocker == "price":
        return f"Proof after data changes: run `make price-coverage TOP_N=25`, `make readiness`, then `{report_command}`."
    if blocker in {"fundamentals", "dcf"}:
        return f"Proof after data changes: run `make dcf-readiness`, `make readiness`, then `{report_command}`."
    if blocker in {"peer", "peers"}:
        return f"Proof after data changes: run `make peer-mapping-queue TOP_N=25`, `make readiness`, then `{report_command}`."
    if blocker in {"earnings", "analyst_estimates", "optional_context"}:
        return f"Proof after data changes: run `make optional-context-readiness`, `make readiness`, then `{report_command}`."
    return f"Proof before interpretation: run `make readiness`, then `{report_command}`."


def decision_next_action_title(row: pd.Series) -> str:
    ticker = format_missing(row.get("ticker"), "selected ticker")
    blocker = format_missing(row.get("primary_blocker"), "").lower().replace(" ", "_")
    asset_type = format_missing(row.get("asset_type"), row.get("asset_type_readiness", "")).lower()
    if asset_type in {"etf", "index_proxy", "fund"}:
        return f"Monitor context for {ticker}"
    if blocker in {"peer", "peers"}:
        return f"Peer mapping for {ticker}"
    if blocker == "fundamentals":
        return f"Fundamentals for {ticker}"
    if blocker == "price":
        return "Price coverage worklist"
    if blocker in {"earnings", "analyst_estimates", "optional_context"}:
        return f"Optional context for {ticker}"
    if ticker != "selected ticker":
        return f"Next research step for {ticker}"
    return "Top safe research step"


def decision_workflow_summary_cards(
    decisions_frame: pd.DataFrame | None,
    ticker_readiness_frame: pd.DataFrame | None = None,
) -> list[dict[str, object]]:
    if decisions_frame is None or decisions_frame.empty:
        return [
            {
                "kicker": "DECISIONS",
                "title": "Decision workflow not ready yet",
                "body": "Rebuild the local readiness snapshot before reading decision buckets.",
                "badges": ["blocked"],
                "command": "make pipeline",
            }
        ]

    frame = decisions_frame.copy()
    if "ticker" in frame.columns:
        frame["ticker"] = frame["ticker"].astype(str).str.upper().str.strip()
    if (
        ticker_readiness_frame is not None
        and not ticker_readiness_frame.empty
        and "ticker" in frame.columns
        and "ticker" in ticker_readiness_frame.columns
    ):
        readiness_columns = [
            column
            for column in ["ticker", "in_active_universe", "dcf_ready", "peer_ready", "asset_type"]
            if column in ticker_readiness_frame.columns
        ]
        readiness = ticker_readiness_frame[readiness_columns].copy()
        readiness["ticker"] = readiness["ticker"].astype(str).str.upper().str.strip()
        frame = frame.merge(readiness, on="ticker", how="left", suffixes=("", "_readiness"))
    bucket_counts = frame.get("decision_bucket", pd.Series(dtype=object)).fillna("Unknown").astype(str).value_counts()
    subtype_counts = frame.get("decision_subtype", pd.Series(dtype=object)).fillna("Unknown").astype(str).value_counts()
    blocker_counts = frame.get("primary_blocker", pd.Series(dtype=object)).fillna("none").astype(str).replace({"": "none"}).value_counts()
    confidence_source = (
        frame.get("data_confidence")
        if "data_confidence" in frame.columns
        else frame.get("confidence", pd.Series(dtype=object))
    )
    confidence_counts = (
        confidence_source.fillna("unknown").astype(str).str.strip().replace({"": "unknown"}).value_counts()
        if confidence_source is not None
        else pd.Series(dtype=object)
    )
    next_actions = frame.get("next_best_action", pd.Series(dtype=object)).fillna("").astype(str)
    action_rows = frame.loc[next_actions.str.strip().ne("")].copy()
    if not action_rows.empty:
        bucket_rank = action_rows.get("decision_bucket", pd.Series("", index=action_rows.index)).astype(str).map(
            {"Research Now": 0, "Blocked by Data": 1, "Monitor": 2}
        ).fillna(3).astype(int)
        active_rank = (~bool_series(action_rows, "in_active_universe")).astype(int)
        peer_unlock_rank = (
            ~(
                bool_series(action_rows, "dcf_ready")
                & ~bool_series(action_rows, "peer_ready")
                & action_rows.get("primary_blocker", pd.Series("", index=action_rows.index)).fillna("").astype(str).str.lower().eq("peers")
            )
        ).astype(int)
        action_rows = action_rows.assign(_bucket_rank=bucket_rank, _active_rank=active_rank, _peer_unlock_rank=peer_unlock_rank)
        action_rows = action_rows.sort_values(["_bucket_rank", "_active_rank", "_peer_unlock_rank", "ticker"], kind="stable")
        top_action_row = action_rows.iloc[0]
        top_action = decision_next_action_summary(top_action_row)
    else:
        top_action_row = pd.Series(dtype=object)
        top_action = "Run make project-status for next steps."
    research_now = int(bucket_counts.get("Research Now", 0))
    blocked = int(bucket_counts.get("Blocked by Data", 0))
    monitor = int(bucket_counts.get("Monitor", 0))
    excluded = int(bucket_counts.get("Excluded", 0))
    review_later = int(bucket_counts.get("Review Later", 0))
    top_blocker = str(blocker_counts.index[0]) if not blocker_counts.empty else "none"
    top_subtype = str(subtype_counts.index[0]) if not subtype_counts.empty else "Not available"
    optional_blocker_text = (
        frame.get("blocked_features", pd.Series("", index=frame.index)).fillna("").astype(str).str.lower()
        + " "
        + frame.get("primary_blocker", pd.Series("", index=frame.index)).fillna("").astype(str).str.lower()
    )
    subtype_text = frame.get("decision_subtype", pd.Series("", index=frame.index)).fillna("").astype(str)
    research_now_optional_locked = frame.loc[
        frame.get("decision_bucket", pd.Series("", index=frame.index)).fillna("").astype(str).eq("Research Now")
        & (
            subtype_text.str.contains("Optional Context Locked", case=False, na=False)
            | optional_blocker_text.str.contains("earnings|analyst_estimates|optional_context", na=False)
        )
    ].copy()
    optional_tickers = (
        research_now_optional_locked.get("ticker", pd.Series(dtype=object)).dropna().astype(str).str.upper().str.strip().head(5).tolist()
        if not research_now_optional_locked.empty
        else []
    )
    cards = [
        {
            "kicker": "DECISION BUCKETS",
            "title": f"{research_now} research / {blocked} blocked",
            "body": f"Monitor: {monitor}. Excluded: {excluded}. Review later: {review_later}. Buckets are readiness-gated review labels, not execution guidance.",
            "badges": ["readiness-gated", "research-only"],
            "command": "make project-status",
        },
        {
            "kicker": "TOP DECISION SUBTYPE",
            "title": top_subtype,
            "body": ", ".join(f"{key}: {int(value)}" for key, value in list(subtype_counts.items())[:3]),
            "badges": ["reason codes"],
            "command": "make readiness",
        },
        {
            "kicker": "TOP PRIMARY BLOCKER",
            "title": top_blocker,
            "body": ", ".join(f"{key}: {int(value)}" for key, value in list(blocker_counts.items())[:3]),
            "badges": ["blocked by data"],
            "command": "make onboarding TOP_N=10",
        },
        {
            "kicker": "DATA CONFIDENCE",
            "title": "Coverage signal, not conviction",
            "body": (
                ", ".join(f"{key}: {int(value)}" for key, value in list(confidence_counts.items())[:3])
                if not confidence_counts.empty
                else "No data-confidence column found yet. Treat decision rows as review states until readiness is regenerated."
            )
            + " Data confidence describes local input coverage and falls when core, peer, earnings, or estimate context is missing.",
            "badges": ["data quality", "not a rating"],
            "command": "make research-health TOP_N=10",
        },
        {
            "kicker": "NEXT DECISION ACTION",
            "title": decision_next_action_title(top_action_row),
            "body": (
                f"{compact_reason(top_action, max_sentences=1, max_chars=180)} "
                f"{decision_next_action_proof(top_action_row)}"
            ),
            "badges": ["copy command only", "no execution"],
            "command": purpose_unlock_command(
                top_action_row.get("ticker"),
                top_action_row.get("primary_blocker"),
                top_action,
            ),
        },
    ]
    if not research_now_optional_locked.empty:
        ticker_text = ", ".join(optional_tickers) if optional_tickers else "Research Now rows"
        cards.append(
            {
                "kicker": "OPTIONAL CONTEXT LOCK",
                "title": f"{len(research_now_optional_locked)} research row(s)",
                "body": (
                    f"Optional Context Locked row(s): {ticker_text}. Research Now rows have supported core or DCF context, but earnings or analyst-estimate context remains unavailable "
                    "until trusted local CSV rows exist. Proof after data changes: run `make optional-context-readiness`, `make readiness`, then reopen the relevant single-stock report."
                ),
                "badges": ["core research ok", "optional locked"],
                "command": "make optional-context-worklist TOP_N=25",
            }
        )
    return cards


def final_decision_quality_cards(decisions_frame: pd.DataFrame | None) -> list[dict[str, object]]:
    if decisions_frame is None or decisions_frame.empty:
        return [
            {
                "kicker": "DECISION QUALITY",
                "title": "Decision outputs not ready yet",
                "body": "Build the local research views before interpreting Research Now, Monitor, or Blocked by Data buckets.",
                "badges": ["refresh first"],
                "command": "make pipeline",
            }
        ]
    buckets = decisions_frame.get("decision_bucket", pd.Series(dtype=object)).fillna("Unknown").astype(str)
    research_now = int(buckets.eq("Research Now").sum())
    monitor = int(buckets.eq("Monitor").sum())
    blocked = int(buckets.eq("Blocked by Data").sum())
    return [
        {
            "kicker": "RESEARCH NOW",
            "title": f"{research_now} row(s)",
            "body": "Ready for deeper research review only. Treat this as a review-queue label; it is not a direct action, allocation instruction, or recommendation.",
            "badges": ["research review", "not advice"],
            "command": "make research-health TOP_N=10",
        },
        {
            "kicker": "MONITOR",
            "title": f"{monitor} row(s)",
            "body": "Useful for market, theme, ETF/index, liquidity, or risk context where company valuation may be excluded.",
            "badges": ["context", "valuation may be excluded"],
            "command": stock_report_md_command("QQQ"),
        },
        {
            "kicker": "BLOCKED BY DATA",
            "title": f"{blocked} row(s)",
            "body": "Blocked rows are missing-data work, not weak-company conclusions. Open Data Health or the next-action columns before interpreting them.",
            "badges": ["missing data", "no inference"],
            "command": "make onboarding TOP_N=10",
        },
        {
            "kicker": "METHODOLOGY",
            "title": "Project readiness gates",
            "body": "Decision buckets are assembled from local readiness, blocker, and source readiness outputs in project code; shipped decisions come from project code and local data.",
            "badges": ["project rules", "transparent"],
            "command": "make project-status",
        },
    ]


def decision_interpretation_ladder_frame() -> pd.DataFrame:
    return pd.DataFrame(
        [
            {
                "Step": "1. Read the bucket",
                "What It Means": "Research Now, Monitor, and Blocked by Data are review states, not direct actions.",
                "What To Check Next": "Confirm whether the row is deeper research, monitor context, or missing-data work.",
                "Safe Command": "make project-status",
            },
            {
                "Step": "2. Read the subtype",
                "What It Means": "Subtype explains why the broad bucket exists, such as DCF-ready but peer-blocked or ETF market proxy.",
                "What To Check Next": "Use decision_subtype before comparing rows inside the same bucket.",
                "Safe Command": "make research-decisions",
            },
            {
                "Step": "3. Read the blocker",
                "What It Means": "primary_blocker and missing_data explain which trusted local input is still missing.",
                "What To Check Next": "Do not interpret valuation, peers, earnings, or estimates until the blocker is resolved.",
                "Safe Command": "make onboarding TOP_N=10",
            },
            {
                "Step": "4. Read data confidence",
                "What It Means": "Data confidence is a data-quality state that drops when important context is missing.",
                "What To Check Next": "Treat low or limited data confidence as a reason to inspect sources, source readiness, and gaps first.",
                "Safe Command": "make research-health TOP_N=10",
            },
            {
                "Step": "5. Copy the next action",
                "What It Means": "The next local step points to the safest workflow to review; it is not a dashboard action or recommendation.",
                "What To Check Next": "Run the command manually only after reviewing source readiness notes.",
                "Safe Command": "make status-check TOP_N=5",
            },
        ]
    )


def decision_interpretation_ladder_cards() -> list[dict[str, object]]:
    frame = decision_interpretation_ladder_frame()
    bucket = frame.iloc[0]
    blocker = frame.iloc[2]
    next_action = frame.iloc[4]
    return [
        {
            "kicker": "DECISION READING ORDER",
            "title": "Read the bucket",
            "body": format_missing(bucket.get("What It Means"), ""),
            "badges": ["review state", "not advice"],
            "command": format_missing(bucket.get("Safe Command"), ""),
        },
        {
            "kicker": "BLOCKER BEFORE CONCLUSION",
            "title": "Read the blocker",
            "body": format_missing(blocker.get("What To Check Next"), ""),
            "badges": ["missing data first", "no inference"],
            "command": format_missing(blocker.get("Safe Command"), ""),
        },
        {
            "kicker": "NEXT ACTION IS COPY-ONLY",
            "title": "Copy the next action",
            "body": format_missing(next_action.get("What It Means"), ""),
            "badges": ["manual review workflow", "research-only"],
            "command": format_missing(next_action.get("Safe Command"), ""),
        },
    ]


def final_decision_table_guide_cards(decisions_frame: pd.DataFrame | None) -> list[dict[str, object]]:
    if decisions_frame is None or decisions_frame.empty:
        return [
            {
                "kicker": "TABLE GUIDE",
                "title": "Generate decisions first",
                "body": "The table-reading guide appears after local decision outputs exist.",
                "badges": ["refresh first"],
                "command": "make research-decisions",
            }
        ]

    confidence_source = (
        decisions_frame.get("data_confidence")
        if "data_confidence" in decisions_frame.columns
        else decisions_frame.get("confidence", pd.Series(dtype=object))
    )
    confidence_values = (
        confidence_source
        .fillna("")
        .astype(str)
        .str.strip()
        .replace("", pd.NA)
        .dropna()
        .str.lower()
    )
    blocker_values = (
        decisions_frame.get("primary_blocker", decisions_frame.get("missing_data", pd.Series(dtype=object)))
        .fillna("")
        .astype(str)
        .str.strip()
        .replace("", pd.NA)
        .dropna()
        .str.lower()
    )
    low_confidence_count = int(confidence_values.str.contains("low|limited", na=False).sum()) if not confidence_values.empty else 0
    top_blocker = str(blocker_values.value_counts().index[0]) if not blocker_values.empty else "not available"
    next_action_count = int(
        decisions_frame.get("next_action", decisions_frame.get("next_best_action", pd.Series("", index=decisions_frame.index)))
        .fillna("")
        .astype(str)
        .str.strip()
        .ne("")
        .sum()
    )
    return [
        {
            "kicker": "BUCKET",
            "title": "Review state, not a call",
            "body": "Read decision_bucket as where the ticker belongs in the research review: deeper review, monitor context, or missing-data work.",
            "badges": ["review label", "not advice"],
        },
        {
            "kicker": "DATA CONFIDENCE",
            "title": f"{low_confidence_count} low-data-confidence row(s)",
            "body": (
                "Data confidence is input coverage, not conviction or recommendation strength. It falls when core inputs, "
                "peer context, source readiness, earnings, or analyst estimates are missing."
            ),
            "badges": ["data confidence", "missing inputs"],
        },
        {
            "kicker": "BLOCKER",
            "title": f"Top blocker: {top_blocker}",
            "body": "Use primary_blocker, missing_data, blocked_features, and excluded_features before interpreting any ticker-level output.",
            "badges": ["read blockers first"],
            "command": "make readiness",
        },
        {
            "kicker": "NEXT ACTION",
            "title": f"{next_action_count} row(s) with next steps",
            "body": "Next-action fields point to copyable local workflow steps. They do not run anything from the dashboard.",
            "badges": ["copy-only", "local workflow"],
            "command": "make research-health TOP_N=10",
        },
    ]


