def single_stock_status_cards(snapshot: dict[str, object]) -> list[dict[str, object]]:
    if not snapshot or snapshot.get("status") == "missing":
        return [
            {
                "kicker": "TICKER STATUS",
                "title": format_missing(snapshot.get("ticker") if snapshot else "", "Missing ticker"),
                "body": format_missing(snapshot.get("main_reason") if snapshot else "", "Ticker is not available in current outputs."),
                "badges": ["missing"],
                "command": str(snapshot.get("next_action") if snapshot else "make universe-report"),
            }
        ]

    ready_features = format_missing(snapshot.get("ready_features"), "-")
    blocked_features = format_missing(snapshot.get("blocked_features"), "-")
    excluded_features = format_missing(snapshot.get("excluded_features"), "-")
    price_window = "Price coverage unavailable"
    first_date = format_missing(snapshot.get("price_first_date"), "")
    last_date = format_missing(snapshot.get("price_last_date"), "")
    if first_date or last_date:
        price_window = f"Price rows span {first_date or 'unknown'} to {last_date or 'unknown'}."
    elif format_missing(snapshot.get("price_rows"), ""):
        price_window = f"Price rows/days: {format_missing(snapshot.get('price_rows'))}."
    ticker = format_missing(snapshot.get("ticker"), "TICKER").upper()
    asset_type = format_missing(snapshot.get("asset_type"), "").lower()
    dcf_status = format_missing(snapshot.get("dcf_status"), "").lower()
    peer_ready = bool(snapshot.get("peer_ready"))
    candidate_peer_count = _peer_candidate_count_from_obj(snapshot)
    peer_title = "Peer ready" if peer_ready else format_missing(snapshot.get("peer_blocker_type"), "missing_peer_mapping")
    peer_body = (
        "Peer context is available or not required for this view."
        if peer_ready
        else format_missing(snapshot.get("next_peer_action"), "Add source-backed peer mappings before peer-relative valuation is reviewed.")
    )
    peer_command = stock_report_md_command(ticker) if peer_ready else f"make focus-peers TICKER={ticker}"
    if dcf_status == "excluded" or asset_type in {"etf", "index_proxy", "fund"}:
        peer_title = "monitor context"
        peer_body = "ETF/index proxy peer mappings are optional context; operating-company peer valuation is excluded."
        peer_command = stock_report_md_command(ticker)
    elif dcf_status and dcf_status != "ready":
        peer_title = "blocked until fundamentals / DCF"
        peer_body = "Peer-relative valuation should wait until trusted fundamentals and DCF inputs are ready."
        peer_command = stock_report_md_command(ticker)
    elif candidate_peer_count > 0:
        peer_title = "candidate peers available"
        peer_body = f"{peer_body} {_peer_candidate_note(snapshot)}"
        peer_command = stock_report_md_command(ticker)
    next_command = single_stock_next_command(snapshot)
    data_confidence = first_meaningful_text(
        snapshot.get("data_confidence"),
        snapshot.get("confidence"),
        fallback="Not available",
    )
    status_body = format_missing(snapshot.get("main_reason"), "Readiness state available.")
    if next_command == "make optional-context-worklist TOP_N=25":
        next_action_text = compact_reason(snapshot.get("next_action"), max_sentences=1, max_chars=160)
        if next_action_text != "Not available" and next_action_text.lower() not in status_body.lower():
            status_body = f"{status_body} {next_action_text}"

    return [
        {
            "kicker": "ONE-MINUTE READ",
            "title": format_missing(snapshot.get("ticker"), "Selected ticker"),
            "body": format_missing(snapshot.get("one_minute_summary"), "Readiness state available."),
            "badges": ["readiness first", "single name"],
            "command": stock_report_md_command(snapshot.get("ticker")),
        },
        {
            "kicker": "TICKER STATUS",
            "title": f"{format_missing(snapshot.get('ticker'))}: {format_missing(snapshot.get('status'))}",
            "body": status_body,
            "badges": [
                f"decision: {format_missing(snapshot.get('decision_subtype'))}",
                f"data confidence: {data_confidence}",
            ],
            "command": next_command,
        },
        {
            "kicker": "FEATURE BADGES",
            "title": f"Ready: {ready_features}",
            "body": f"Blocked: {blocked_features}. Excluded: {excluded_features}. Missing data: {format_missing(snapshot.get('missing_data'), '-')}",
            "badges": ["readiness first"],
            "command": "make readiness",
        },
        {
            "kicker": "PEER PATH",
            "title": peer_title,
            "body": peer_body,
            "badges": [
                f"trend: {format_missing(snapshot.get('peer_trend_comparison_ready'))}",
                f"valuation: {format_missing(snapshot.get('peer_valuation_comparison_ready'))}",
            ],
            "command": peer_command,
        },
        {
            "kicker": "SOURCE READINESS",
            "title": price_window,
            "body": f"Last readiness update: {format_missing(snapshot.get('updated_at'), 'not available')}. Optional context requires trusted local CSV input.",
            "badges": ["local CSV", "source readiness"],
            "command": "make project-status",
        },
    ]


def split_momentum_readiness(frame: pd.DataFrame, coverage_frame: pd.DataFrame | None = None) -> tuple[pd.DataFrame, pd.DataFrame]:
    if frame.empty or "Ticker" not in frame.columns:
        return frame.copy(), pd.DataFrame(columns=frame.columns)
    ready_tickers = ticker_set_from_bool(coverage_frame, "usable_for_momentum")
    if ready_tickers:
        ready_mask = frame["Ticker"].astype(str).str.upper().str.strip().isin(ready_tickers)
    else:
        numeric_columns = [column for column in ["Close", "RSPercentile", "Return1M", "AvgVolume20D"] if column in frame.columns]
        ready_mask = frame[numeric_columns].apply(pd.to_numeric, errors="coerce").notna().any(axis=1) if numeric_columns else pd.Series(False, index=frame.index)
    return frame.loc[ready_mask].copy(), frame.loc[~ready_mask].copy()


def split_dcf_readiness(dcf_readiness_frame: pd.DataFrame | None) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    if dcf_readiness_frame is None or dcf_readiness_frame.empty:
        empty = pd.DataFrame()
        return empty, empty, empty
    frame = dcf_readiness_frame.copy()
    asset_type = frame.get("asset_type", pd.Series("company", index=frame.index)).fillna("company").astype(str).str.lower()
    ready_mask = bool_series(frame, "is_dcf_ready")
    company_mask = asset_type.eq("company")
    return frame.loc[company_mask & ready_mask].copy(), frame.loc[company_mask & ~ready_mask].copy(), frame.loc[~company_mask].copy()


def valuation_readiness_operator_frame(
    ready_companies: pd.DataFrame,
    blocked_companies: pd.DataFrame,
    excluded_rows: pd.DataFrame,
) -> pd.DataFrame:
    def example_tickers(frame: pd.DataFrame, limit: int = 5) -> str:
        if frame.empty or "ticker" not in frame.columns:
            return "No examples"
        tickers = (
            frame["ticker"]
            .dropna()
            .astype(str)
            .str.upper()
            .str.strip()
        )
        tickers = [ticker for ticker in tickers.tolist() if ticker and ticker.lower() not in {"nan", "none"}]
        if not tickers:
            return "No examples"
        suffix = f" +{len(tickers) - limit} more" if len(tickers) > limit else ""
        return ", ".join(tickers[:limit]) + suffix

    top_missing = "trusted fundamentals, free cash flow or margin, share count, and source readiness"
    if not blocked_companies.empty and "missing_dcf_fields" in blocked_companies.columns:
        missing_counts: dict[str, int] = {}
        for value in blocked_companies["missing_dcf_fields"].dropna().astype(str):
            for field in re.split(r"[,;|]", value):
                cleaned = field.strip()
                if cleaned and cleaned.lower() not in {"nan", "none", "not available"}:
                    missing_counts[cleaned] = missing_counts.get(cleaned, 0) + 1
        if missing_counts:
            top_missing = ", ".join(
                field for field, _count in sorted(missing_counts.items(), key=lambda item: (-item[1], item[0]))[:3]
            )

    return pd.DataFrame(
        [
            {
                "Evaluation Mode": "DCF-ready review",
                "Valuation State": "Ready company rows",
                "Count": len(ready_companies),
                "Example Tickers": example_tickers(ready_companies),
                "What It Means": "DCF inputs are present enough to review assumptions, scenarios, and sensitivity as research context.",
                "What Stays Withheld": "Recommendations and allocation instructions remain outside this research-only product.",
                "Next Command": "make dcf-readiness",
            },
            {
                "Evaluation Mode": "Locked by missing inputs",
                "Valuation State": "Blocked company rows",
                "Count": len(blocked_companies),
                "Example Tickers": example_tickers(blocked_companies),
                "What It Means": f"Company valuation is locked until missing inputs are filled. Most common blockers: {top_missing}.",
                "What Stays Withheld": "No undervalued or overvalued conclusion is shown for blocked rows.",
                "Next Command": "make sec-stage-queue TOP_N=25",
            },
            {
                "Evaluation Mode": "Monitor-only context",
                "Valuation State": "ETF / fund monitor rows",
                "Count": len(excluded_rows),
                "Example Tickers": example_tickers(excluded_rows),
                "What It Means": "These rows can still support market, theme, liquidity, or risk monitoring.",
                "What Stays Withheld": "Operating-company DCF is excluded, not failed.",
                "Next Command": "make stock-report-md TICKER=QQQ",
            },
        ]
    )


def _plain_missing_input_list(value: object, fallback: str = "trusted DCF inputs") -> str:
    text = format_missing(value, fallback)
    if text == fallback:
        return fallback
    parts = [
        public_status_label(part).replace("_", " ").strip()
        for part in re.split(r"[,;|]", text)
        if part.strip() and part.strip().lower() not in {"nan", "none", "not available"}
    ]
    return ", ".join(parts) if parts else fallback


def valuation_blocked_unlock_frame(blocked_companies: pd.DataFrame, limit: int = 25) -> pd.DataFrame:
    columns = [
        "Ticker",
        "Current State",
        "Valuation Boundary",
        "Missing Trusted Inputs",
        "What This Means",
        "Next Trusted Input",
        "Next Safe Sequence",
        "Validation Path",
        "Copy-Only Command",
    ]
    if blocked_companies.empty:
        return pd.DataFrame(columns=columns)

    def row_bool(row: pd.Series, column: str, default: bool = True) -> bool:
        if column not in row or pd.isna(row.get(column)):
            return default
        value = row.get(column)
        if isinstance(value, bool):
            return value
        return str(value).strip().lower() in {"true", "1", "yes", "y"}

    rows: list[dict[str, object]] = []
    for _, row in blocked_companies.head(limit).iterrows():
        ticker = format_missing(row.get("ticker"), "TICKER").upper()
        missing_inputs = _plain_missing_input_list(
            first_meaningful_text(row.get("missing_dcf_fields"), row.get("reason_not_ready"), fallback="")
        )
        has_price = row_bool(row, "has_price", default=True)
        if not has_price:
            next_input = "Add or refresh trusted local price rows before reviewing valuation."
            command = f"make focus-price TICKER={ticker}"
            safe_sequence = (
                f"1. Inspect `{command}`. 2. Use `make price-refresh-loop DRY_RUN=1` for a capped broad plan "
                "or prepare trusted OHLCV rows in `data/imports/prices.csv`. "
                "3. Run `make price-validate`, `make price-preview`, `make price-apply`, then `make dcf-readiness`."
            )
            validation_path = "make price-validate -> make price-preview -> make price-apply -> make dcf-readiness"
        else:
            next_input = "Add trusted company fundamentals such as revenue, free cash flow or margin, and shares outstanding."
            command = f"make focus-fundamentals TICKER={ticker}"
            safe_sequence = (
                f"1. Inspect `{command}`. 2. Use `make sec-stage TICKERS={ticker}` when SEC_USER_AGENT is configured, "
                "or fill `data/imports/fundamentals.csv` with trusted manual rows. "
                f"3. Run `{scoped_import_sequence(ticker, separator='`, `')}`, then `make dcf-readiness`."
            )
            validation_path = f"{scoped_import_sequence(ticker)} -> make dcf-readiness"
        rows.append(
            {
                "Ticker": ticker,
                "Current State": "Valuation locked by missing inputs",
                "Valuation Boundary": "No intrinsic, peer-relative, undervalued, or overvalued conclusion until trusted inputs pass readiness.",
                "Missing Trusted Inputs": missing_inputs,
                "What This Means": "No fair value, undervalued, or overvalued conclusion is shown until these inputs pass readiness.",
                "Next Trusted Input": next_input,
                "Next Safe Sequence": safe_sequence,
                "Validation Path": validation_path,
                "Copy-Only Command": command,
            }
        )
    return pd.DataFrame(rows, columns=columns)


def valuation_excluded_context_frame(excluded_rows: pd.DataFrame, limit: int = 25) -> pd.DataFrame:
    columns = ["Ticker", "Asset Type", "Current State", "Valuation Boundary", "What This Means", "Copy-Only Command"]
    if excluded_rows.empty:
        return pd.DataFrame(columns=columns)
    rows: list[dict[str, object]] = []
    for _, row in excluded_rows.head(limit).iterrows():
        ticker = format_missing(row.get("ticker"), "TICKER").upper()
        asset_type = public_status_label(row.get("asset_type"), "ETF / index / fund")
        rows.append(
            {
                "Ticker": ticker,
                "Asset Type": asset_type,
                "Current State": "Operating-company DCF excluded",
                "Valuation Boundary": "DCF excluded, not failed; peer-relative company valuation is not shown for monitor-context rows.",
                "What This Means": "Use monitor context such as market, theme, liquidity, or risk review; DCF is excluded, not failed.",
                "Copy-Only Command": stock_report_md_command(ticker),
            }
        )
    return pd.DataFrame(rows, columns=columns)


def valuation_decision_guide_cards(
    ready_companies: pd.DataFrame,
    blocked_companies: pd.DataFrame,
    excluded_rows: pd.DataFrame,
) -> list[dict[str, object]]:
    operator_frame = valuation_readiness_operator_frame(ready_companies, blocked_companies, excluded_rows)
    kicker_by_state = {
        "Ready company rows": "READY TO REVIEW",
        "Blocked company rows": "LOCKED BY DATA",
        "ETF / fund monitor rows": "MONITOR ONLY",
    }
    badge_by_state = {
        "Ready company rows": ["assumptions", "sensitivity"],
        "Blocked company rows": ["missing inputs", "no valuation call"],
        "ETF / fund monitor rows": ["DCF excluded", "context only"],
    }
    cards: list[dict[str, object]] = []
    for _, row in operator_frame.iterrows():
        state = format_missing(row.get("Valuation State"), "Valuation state")
        mode = format_missing(row.get("Evaluation Mode"), state)
        examples = format_missing(row.get("Example Tickers"), "No examples")
        meaning = format_missing(row.get("What It Means"), "Not available")
        withheld = format_missing(row.get("What Stays Withheld"), "Not available")
        cards.append(
            {
                "kicker": kicker_by_state.get(state, "VALUATION STATE"),
                "title": f"{format_missing(row.get('Count'), 0)} {mode.lower()}",
                "body": f"Examples: {examples}. {meaning} Withheld: {withheld}",
                "badges": badge_by_state.get(state, ["research-only"]),
                "command": format_missing(row.get("Next Command"), "make dcf-readiness"),
            }
        )
    return cards


def valuation_quick_read_cards(
    ready_companies: pd.DataFrame | None,
    blocked_companies: pd.DataFrame | None,
    excluded_rows: pd.DataFrame | None,
) -> list[dict[str, object]]:
    ready = pd.DataFrame() if ready_companies is None else ready_companies
    blocked = pd.DataFrame() if blocked_companies is None else blocked_companies
    excluded = pd.DataFrame() if excluded_rows is None else excluded_rows

    def first_ticker(frame: pd.DataFrame, fallback: str = "TICKER") -> str:
        if frame.empty or "ticker" not in frame.columns:
            return fallback
        values = frame["ticker"].dropna().astype(str).str.upper().str.strip()
        values = values.loc[values.ne("")]
        return values.iloc[0] if not values.empty else fallback

    ready_ticker = first_ticker(ready, "NVDA")
    blocked_ticker = first_ticker(blocked, "TICKER")
    excluded_ticker = first_ticker(excluded, "QQQ")
    blocked_missing = "trusted price, fundamentals, free cash flow or margin, and share count"
    if not blocked.empty and "missing_dcf_fields" in blocked.columns:
        missing_values = blocked["missing_dcf_fields"].fillna("").astype(str).str.strip()
        missing_values = missing_values.loc[missing_values.ne("")]
        if not missing_values.empty:
            blocked_missing = plain_dashboard_input_copy(missing_values.iloc[0])

    if ready.empty and blocked.empty and excluded.empty:
        first_title = "Generate DCF readiness first"
        first_body = "No valuation readiness rows are loaded, so valuation should stay current-only and blocked until the local readiness files exist."
        first_command = "make dcf-readiness"
        first_badges = ["readiness first", "no guessing"]
    elif not ready.empty:
        first_title = "Review valuation-ready companies first"
        first_body = (
            f"Start with a valuation-ready example such as {ready_ticker}. Rows with complete valuation inputs can support assumption, scenario, sensitivity, and source readiness review; "
            "they are still research context, not price targets."
        )
        first_command = stock_report_md_command(ready_ticker)
        first_badges = ["valuation inputs ready", "scenario review"]
    elif not blocked.empty:
        first_title = "Fix missing valuation inputs first"
        first_body = (
            f"Start with {blocked_ticker}. Company valuation remains locked by {blocked_missing}; missing inputs are not undervalued, "
            "overvalued, or weak-company conclusions."
        )
        first_command = f"make focus-fundamentals TICKER={blocked_ticker}"
        first_badges = ["blocked by data", "no conclusion"]
    else:
        first_title = "Use monitor context only"
        first_body = (
            f"Start with {excluded_ticker}. ETF/index/fund rows can support market, theme, liquidity, or risk context; "
            "company valuation is excluded, not failed."
        )
        first_command = stock_report_md_command(excluded_ticker)
        first_badges = ["monitor context", "valuation excluded"]

    ready_command = stock_report_md_command(ready_ticker) if not ready.empty else "make dcf-readiness"
    blocked_command = f"make focus-fundamentals TICKER={blocked_ticker}" if not blocked.empty else "make sec-stage-queue TOP_N=25"
    excluded_command = stock_report_md_command(excluded_ticker) if not excluded.empty else "make stock-report-md TICKER=QQQ"
    if ready.empty:
        analyze_title = "0 valuation-ready company row(s)"
        analyze_body = (
            "What you can analyze now: no company valuation assumptions or sensitivity should be reviewed yet. "
            "Use the locked-input and monitor-context cards until trusted valuation rows exist."
        )
    else:
        analyze_title = f"{len(ready)} valuation-ready company row(s)"
        analyze_body = (
            f"What you can analyze now: open the {ready_ticker} report for valuation assumptions, scenarios, "
            "sensitivity, and source readiness. Peer trend can be reviewed only when mapped peer price history is ready; "
            "peer comparison still needs trusted peer inputs. This is a valuation-readiness review, "
            "not a recommendation, price target, or full investment conclusion."
        )
    excluded_subject = excluded_ticker if not excluded.empty else "ETF/index/fund rows"
    excluded_verb = "uses" if not excluded.empty and len(excluded) == 1 else "use"

    return [
        {
            "kicker": "FIRST READ",
            "title": first_title,
            "body": f"What this means: {first_body}",
            "badges": first_badges,
            "command": first_command,
        },
        {
            "kicker": "PROOF PATH",
            "title": "Prove readiness before interpretation",
            "body": (
                "Read valuation only after the relevant readiness path passes. "
                "DCF assumptions, locked-input worklists, and monitor-context rows stay separated so missing data "
                "does not become a hidden conclusion."
            ),
            "badges": ["proof first", "research-only"],
            "command": first_command,
        },
        {
            "kicker": "ANALYZE NOW",
            "title": analyze_title,
            "body": analyze_body,
            "badges": ["assumptions", "sensitivity"],
            "command": ready_command,
        },
        {
            "kicker": "STILL LOCKED",
            "title": f"{len(blocked)} company row(s) need inputs",
            "body": (
                f"What is still locked: {'for ' + blocked_ticker + ', fair value/share' if not blocked.empty else 'company rows withhold fair value/share'}, intrinsic-value interpretation, "
                f"and re-rating context until {blocked_missing} pass readiness."
            ),
            "badges": ["missing inputs", "valuation withheld"],
            "command": blocked_command,
        },
        {
            "kicker": "EXCLUDED",
            "title": f"{len(excluded)} ETF/index/fund row(s)",
            "body": (
                f"What is excluded: {excluded_subject} {excluded_verb} monitor context because company valuation "
                "does not apply; use market or risk context instead."
            ),
            "badges": ["not failed", "monitor only"],
            "command": excluded_command,
        },
    ]


