def render_data_health_top_operator_summary_block(
    *,
    readiness_summary: dict[str, object],
    queue_outcome_summary: pd.DataFrame,
    readiness_freshness: FreshnessStatus,
    proof_closeout_dcf_frame: pd.DataFrame,
    proof_closeout_peer_frame: pd.DataFrame,
    ticker_readiness_frame: pd.DataFrame | None,
    prior_ticker_readiness_frame: pd.DataFrame | None,
    batch_proof_summary_frame: pd.DataFrame,
    base_dir: Path,
) -> None:
    """Render the first operator proof summaries before lane-specific drawers."""

    render_section_header(
        "Queue Outcome Summary",
        "Latest reviewed-batch outcomes and the primary lane switcher before opening drawers.",
    )
    render_signal_cards(data_health_readiness_queue_outcome_summary_cards(queue_outcome_summary), show_commands=False, variant="queue")
    render_section_header(
        "Proof Checklist Summary",
        "DCF and peer proof checklist status before opening detailed source or proof drawers.",
    )
    render_signal_cards(
        data_health_proof_checklist_summary_cards(readiness_summary, queue_outcome_summary),
        show_commands=False,
        variant="queue",
    )
    render_section_header(
        "Proof Planner Outcome Summary",
        "DCF and peer planner states side by side before opening lane-specific proof drawers.",
    )
    render_signal_cards(
        data_health_proof_planner_outcome_summary_cards(
            readiness_summary,
            queue_outcome_summary,
            readiness_freshness,
        ),
        show_commands=False,
        variant="queue",
    )
    render_section_header(
        "Proof Closeout Summary",
        "DCF and peer closeout states side by side before opening lane-specific evidence drawers.",
    )
    render_signal_cards(
        data_health_proof_closeout_summary_cards(proof_closeout_dcf_frame, proof_closeout_peer_frame),
        show_commands=False,
        variant="queue",
    )
    render_section_header(
        "Readiness Coverage Delta",
        "Prior/current readiness deltas, still-blocked lanes, and generated-artifact review status before raw CSV reports.",
    )
    render_signal_cards(
        data_health_readiness_delta_board_cards(
            ticker_readiness_frame,
            prior_ticker_readiness_frame,
            batch_proof_summary_frame,
        ),
        show_commands=False,
        variant="queue",
    )
    with st.expander("Readiness coverage delta board", expanded=False):
        st.dataframe(
            clean_display_frame(
                data_health_readiness_delta_board_frame(
                    ticker_readiness_frame,
                    prior_ticker_readiness_frame,
                    batch_proof_summary_frame,
                )
            ),
            width="stretch",
            hide_index=True,
        )
    render_section_header(
        "Generated Artifact Review",
        "Classify local generated CSV/report churn before staging or public sharing.",
    )
    render_signal_cards(data_health_generated_churn_review_cards(base_dir), show_commands=False, variant="queue")
    with st.expander("Generated churn review drawer", expanded=False):
        render_section_header(
            "Generated Churn Decision",
            "These rows mirror make diff-hygiene: generated CSV/JSON churn is excluded unless intentionally reviewed evidence.",
        )
        st.dataframe(
            clean_display_frame(data_health_generated_churn_review_frame(base_dir)),
            width="stretch",
            hide_index=True,
        )
        render_section_header(
            "Generated Artifact Paths",
            "Dirty generated files are listed for review, not staging by default.",
        )
        st.dataframe(
            clean_display_frame(data_health_generated_churn_detail_frame(base_dir)),
            width="stretch",
            hide_index=True,
        )


def metric_console_state_label(row: pd.Series) -> str:
    blocked = int(row.get("Blocked Rows", 0) or 0)
    partial = int(row.get("Partial Rows", 0) or 0)
    ready = int(row.get("Ready Rows", 0) or 0)
    excluded = int(row.get("Excluded Rows", 0) or 0)
    if blocked:
        return "blocked"
    if partial:
        return "partial"
    if ready:
        return "ready"
    if excluded:
        return "excluded"
    return "neutral"


def metric_console_next_action(frame: pd.DataFrame | None) -> dict[str, str]:
    if frame is None or frame.empty:
        return {
            "family": "Metric readiness queue",
            "blocker": "No SPY/QQQ metric-readiness rows are available yet.",
            "next_proof": "Open the evidence drawer after local readiness artifacts exist.",
        }
    blockers = frame.get("Top Blocker", pd.Series(index=frame.index, dtype=object)).fillna("").astype(str)
    actionable = frame.loc[blockers.str.strip().str.lower().ne("none")]
    row = actionable.iloc[0] if not actionable.empty else frame.iloc[0]
    family = format_missing(row.get("Blocker Family"), "metric readiness").title()
    blocker = compact_card_fragment(format_missing(row.get("Top Blocker"), "No blocker recorded."), max_chars=128)
    next_check = format_missing(row.get("Next Check"), "Open the evidence drawer for the copy-only check.")
    proof_hint = operator_queue_preview_copy(next_check)
    if not proof_hint or proof_hint == "open the evidence drawer":
        proof_hint = "Open the evidence drawer for the copy-only check."
    return {
        "family": family,
        "blocker": blocker,
        "next_proof": proof_hint,
    }


def metric_console_source_lane(family: object) -> str:
    family_text = str(family or "").strip().lower()
    if family_text == "benchmark / risk":
        return "Local ticker prices plus SPY/QQQ benchmark prices"
    if family_text == "fundamentals trend":
        return "Trusted local fundamentals rows"
    if family_text == "valuation multiples":
        return "Trusted fundamentals plus market-cap context"
    if family_text == "peer dispersion":
        return "Source-backed peer mappings plus trusted peer inputs"
    if family_text == "none":
        return "No source blocker recorded"
    return "Metric source lane depends on the row-level blocker"


def metric_console_proof_gate(family: object, freshness: object) -> str:
    freshness_text = str(freshness or "").strip().lower()
    if freshness_text in {"missing", "stale"}:
        return "Refresh readiness artifacts before relying on exact counts"
    family_text = str(family or "").strip().lower()
    if family_text == "benchmark / risk":
        return "Enough aligned local ticker and benchmark price rows"
    if family_text == "fundamentals trend":
        return "At least two dated trusted fundamentals rows"
    if family_text == "valuation multiples":
        return "Trusted fundamentals plus market cap or price/share count"
    if family_text == "peer dispersion":
        return "Mapped peers with trusted valuation inputs"
    if family_text == "none":
        return "No metric blocker recorded; keep research-only wording"
    return "Open evidence drawer for row-level proof"


def data_health_metric_operator_console_frame(
    frame: pd.DataFrame | None,
    *,
    limit: int = 5,
    freshness_status: FreshnessStatus | None = None,
) -> pd.DataFrame:
    summary = data_health_metric_readiness_family_summary_frame(frame)
    if summary.empty:
        return pd.DataFrame(
            [
                {
                    "Blocker Family": "metric readiness queue",
                    "State": "blocked",
                    "Rows": 0,
                    "Blocked / Partial": 0,
                    "Benchmarks": "SPY, QQQ",
                    "Source / Freshness": "Metric source lane unavailable / freshness unknown",
                    "Proof Gate": "Refresh readiness artifacts before relying on exact counts",
                    "Next Proof": "Open the evidence drawer after local readiness artifacts exist.",
                }
            ]
        )
    rows: list[dict[str, object]] = []
    for _, row in summary.head(max(limit, 1)).iterrows():
        blocked_partial = int(row.get("Blocked Rows", 0) or 0) + int(row.get("Partial Rows", 0) or 0)
        next_check = operator_queue_preview_copy(row.get("First Next Check"))
        if not next_check or next_check == "open the evidence drawer":
            next_check = "Open evidence drawer for copy-only check."
        if freshness_status is not None and freshness_status.status in {"missing", "stale"}:
            freshness = freshness_status.status
        else:
            freshness_values = (
                frame.loc[
                    frame.get("Blocker Family", pd.Series(index=frame.index, dtype=object)).astype(str).eq(str(row.get("Blocker Family"))),
                    "Freshness",
                ]
                if frame is not None and not frame.empty and "Freshness" in frame.columns and "Blocker Family" in frame.columns
                else pd.Series(dtype=object)
            )
            freshness = "unknown" if freshness_values.empty else ", ".join(dict.fromkeys(freshness_values.dropna().astype(str).str.lower().tolist())) or "unknown"
        source_lane = metric_console_source_lane(row.get("Blocker Family"))
        rows.append(
            {
                "Blocker Family": str(row.get("Blocker Family", "none")),
                "State": metric_console_state_label(row),
                "Rows": int(row.get("Queue Rows", 0) or 0),
                "Blocked / Partial": blocked_partial,
                "Benchmarks": format_missing(row.get("Benchmarks"), "SPY, QQQ"),
                "Source / Freshness": f"{source_lane} / {freshness}",
                "Proof Gate": metric_console_proof_gate(row.get("Blocker Family"), freshness),
                "Next Proof": next_check,
            }
        )
    return pd.DataFrame(rows)


def data_health_metric_operator_console_html(frame: pd.DataFrame | None, freshness_status: FreshnessStatus | None = None) -> str:
    rows = 0 if frame is None else len(frame)
    states = (
        pd.Series(dtype=object)
        if frame is None or frame.empty or "Overall State" not in frame.columns
        else frame["Overall State"].fillna("").astype(str).str.lower()
    )
    partial_blocked = int(states.isin({"partial", "blocked"}).sum()) if not states.empty else 0
    excluded = int(states.eq("excluded").sum()) if not states.empty else 0
    benchmarks = "SPY, QQQ"
    freshness = "unknown"
    if frame is not None and not frame.empty:
        benchmarks = ", ".join(dict.fromkeys(frame.get("Benchmark", pd.Series(index=frame.index, dtype=object)).dropna().astype(str).tolist())) or benchmarks
        if freshness_status is not None and freshness_status.status in {"missing", "stale"}:
            freshness = freshness_status.status
        else:
            freshness_values = frame.get("Freshness", pd.Series(index=frame.index, dtype=object)).dropna().astype(str).str.lower()
            if not freshness_values.empty:
                freshness = ", ".join(dict.fromkeys(freshness_values.tolist()))
    next_action = metric_console_next_action(frame)
    console_frame = data_health_metric_operator_console_frame(frame, freshness_status=freshness_status)
    row_html = ""
    for _, row in console_frame.iterrows():
        state = str(row.get("State", "neutral")).lower()
        if state not in {"ready", "partial", "blocked", "excluded"}:
            state = "neutral"
        row_html += (
            "<div class='metric-board-row'>"
            "<div>"
            f"<div class='metric-family-name'>{html.escape(str(row.get('Blocker Family', 'Metric readiness'))).title()}</div>"
            f"<div class='metric-family-sub'>{html.escape(format_missing(row.get('Benchmarks'), 'SPY, QQQ'))}</div>"
            "</div>"
            f"<div><span class='state-pill {state}'>{html.escape(state)}</span></div>"
            f"<div class='metric-board-cell'>{html.escape(str(row.get('Blocked / Partial', 0)))} / {html.escape(str(row.get('Rows', 0)))}</div>"
            f"<div class='metric-board-cell'>Source/freshness: {html.escape(format_missing(row.get('Source / Freshness'), 'Source unavailable.'))}</div>"
            f"<div class='metric-board-cell'>Proof gate: {html.escape(format_missing(row.get('Proof Gate'), 'Open evidence drawer.'))}</div>"
            f"<div class='metric-board-cell'>Next proof: {html.escape(format_missing(row.get('Next Proof'), 'Open evidence drawer.'))}</div>"
            "</div>"
        )
    return (
        "<div class='metric-console'>"
        "<div class='metric-console-main'>"
        "<div class='metric-console-kicker'>Metrics Lane</div>"
        "<div class='metric-console-title'>Readiness first, metric review second.</div>"
        "<div class='metric-console-copy'>"
        "SPY/QQQ review metrics stay blocked, partial, ready, or excluded based on trusted local inputs. "
        "No metric row is a recommendation."
        "</div>"
        "<div class='metric-console-stats'>"
        "<div class='metric-console-stat'>"
        "<div class='metric-console-stat-label'>Queue Rows</div>"
        f"<div class='metric-console-stat-value'>{rows:,}</div>"
        "</div>"
        "<div class='metric-console-stat'>"
        "<div class='metric-console-stat-label'>Needs Proof</div>"
        f"<div class='metric-console-stat-value'>{partial_blocked:,}</div>"
        "</div>"
        "<div class='metric-console-stat'>"
        "<div class='metric-console-stat-label'>Excluded</div>"
        f"<div class='metric-console-stat-value'>{excluded:,}</div>"
        "</div>"
        "</div>"
        "<div class='metric-next-box'>"
        "<div class='metric-next-label'>Next Readiness Action</div>"
        f"<div class='metric-next-title'>{html.escape(next_action['family'])}</div>"
        f"<div class='metric-next-copy'>{html.escape(next_action['blocker'])} Next proof: {html.escape(next_action['next_proof'])}</div>"
        "</div>"
        f"<div class='metric-console-copy'>Benchmarks: {html.escape(benchmarks)}. Freshness: {html.escape(freshness)}. Commands and row proof stay in the evidence drawer.</div>"
        "</div>"
        "<div class='metric-console-board'>"
        "<div class='metric-board-header'>"
        "<div>Family</div><div>State</div><div>Blocked</div><div>Source / Freshness</div><div>Proof Gate</div><div>Next Proof</div>"
        "</div>"
        f"{row_html}"
        "</div>"
        "</div>"
    )


def render_data_health_metric_operator_console(frame: pd.DataFrame | None, freshness_status: FreshnessStatus | None = None) -> None:
    st.markdown(data_health_metric_operator_console_html(frame, freshness_status=freshness_status), unsafe_allow_html=True)


def data_health_operator_snapshot_cards(
    readiness_summary: dict[str, object],
    ops_frame: pd.DataFrame | None,
    frontier_frame: pd.DataFrame | None,
    freshness: FreshnessStatus | None = None,
) -> list[dict[str, object]]:
    """Return the first-read operator snapshot without command-heavy detail."""

    freshness = freshness or readiness_freshness_status(BASE_DIR)
    price_ready = int(readiness_summary.get("price_ready") or 0)
    dcf_ready = int(readiness_summary.get("dcf_ready") or 0)
    peer_ready = int(readiness_summary.get("peer_ready") or 0)
    blocked = int(readiness_summary.get("blocked_by_data") or readiness_summary.get("blocked") or 0)
    top_lane = "No lane selected"
    top_impact = "0"
    top_move = "Run coverage frontier after readiness artifacts exist."
    if frontier_frame is not None and not frontier_frame.empty:
        top = frontier_frame.iloc[0]
        top_lane = format_missing(top.get("Lane"), "Coverage frontier")
        top_impact_value = pd.to_numeric(pd.Series([top.get("Unlock Impact")]), errors="coerce").iloc[0]
        top_impact = "0" if pd.isna(top_impact_value) else f"{int(top_impact_value):,}"
        top_move = compact_card_fragment(top.get("Possible State Move"), max_chars=150)

    return [
        {
            "kicker": "EXECUTIVE SNAPSHOT",
            "title": f"{price_ready:,} price / {dcf_ready:,} DCF / {peer_ready:,} peer-ready",
            "body": (
                f"{blocked:,} row(s) still show data blockers. "
                "Readiness gates decide what analysis appears; locked inputs stay visible instead of becoming conclusions."
            ),
            "badges": ["readiness first", "blocked visible"],
        },
        {
            "kicker": "NEXT DATA ACTION",
            "title": top_lane,
            "body": (
                f"{top_impact} rows could move after reviewed proof. {card_sentence('Path', top_move)} "
                "Use this as the first operator queue, not a security ranking."
            ),
            "badges": ["one next lane", "not ranking"],
        },
        {
            "kicker": "OPERATING MODE",
            "title": f"Freshness: {public_status_label(freshness.status).lower()}",
            "body": (
                f"{freshness.message} "
                "Commands, proof rows, and raw tables are grouped below in evidence drawers so the first screen stays readable."
            ),
            "badges": ["commands collapsed", "proof available"],
        },
    ]


def output_tab_summary_cards(title: str, frame: pd.DataFrame) -> list[dict[str, object]]:
    status_columns = ["FinalState", "SetupStatus", "ReviewState", "ThemeStatus", "FinalValueCategory", "Classification"]
    if title == "Value / Re-rating":
        status_columns = ["ValuationStatus", "FinalValueCategory"]
    status, status_count = dominant_value(frame, status_columns)
    theme, theme_count = dominant_value(frame, ["Theme", "Sector", "SectorETF"])
    missing_count = non_empty_count(frame, [column for column in frame.columns if "missing" in column.lower()])
    reason_count = non_empty_count(frame, [column for column in frame.columns if "reason" in column.lower()])
    row_count = len(frame)
    valuation_ready_count = 0
    valuation_locked_count = 0
    if title == "Value / Re-rating" and "ValuationStatus" in frame.columns:
        valuation_status = frame["ValuationStatus"].fillna("").astype(str).str.strip().str.lower()
        valuation_ready_count = int(valuation_status.eq("ready").sum())
        valuation_locked_count = int(valuation_status.isin({"not_ready", "not ready", "blocked"}).sum())
    if theme_count:
        theme_body = (
            f"Most common theme/sector context across {theme_count} row{'s' if theme_count != 1 else ''}. "
            f"{reason_count} row{'s' if reason_count != 1 else ''} include explanatory notes."
        )
    else:
        theme_body = f"No populated theme or sector context is available in this output. {reason_count} row{'s' if reason_count != 1 else ''} include explanatory notes."
    return [
        {
            "kicker": title.upper(),
            "title": f"{row_count} row{'s' if row_count != 1 else ''}",
            "body": OUTPUT_TAB_GUIDANCE.get(title, "Local research state with transparent reasons and visible gaps."),
            "badges": ["Local research state"],
        },
        {
            "kicker": "VALUATION INPUT STATE" if title == "Value / Re-rating" else "STATE",
            "title": status,
            "body": f"Most common visible state across {status_count} row{'s' if status_count != 1 else ''}.",
            "badges": ["status context"],
        },
        {
            "kicker": "VALUATION READINESS" if title == "Value / Re-rating" else "DATA GAPS",
            "title": (
                f"{valuation_ready_count} broad input-ready row(s) / {valuation_locked_count} locked"
                if title == "Value / Re-rating" and "ValuationStatus" in frame.columns
                else f"{missing_count} row{'s' if missing_count != 1 else ''}"
            ),
            "body": (
                "This broad output counts rows marked input-ready for valuation context. Use the quick-read cards and valuation readiness panel for exact company DCF-ready counts; missing-data fields may still show peer, quality, or multiple context limits."
                if title == "Value / Re-rating" and "ValuationStatus" in frame.columns
                else "Rows with explicit missing-data fields stay visible instead of being silently scored."
            ),
            "badges": ["valuation readiness", "context limits"] if title == "Value / Re-rating" else ["missing data"],
        },
        {
            "kicker": "THEME",
            "title": theme,
            "body": theme_body,
            "badges": ["explainable"],
        },
    ]


