def compact_table_columns(frame: pd.DataFrame) -> list[str]:
    priority = [
        "Month",
        "Rank",
        "Ticker",
        "CompanyName",
        "Theme",
        "Sector",
        "SectorETF",
        "ETF",
        "PrimaryPurpose",
        "FinalState",
        "SetupStatus",
        "ReviewState",
        "ThemeStatus",
        "FinalValueCategory",
        "PeerRelativeStatus",
        "RelativeOpportunityScore",
        "CompositeScore",
        "MomentumScore",
        "TechnicalContextScore",
        "RiskPenalty",
        "LiquidityScore",
        "WatchlistScore",
        "WatchlistRank",
        "RSPercentile",
        "PriceHistoryDays",
        "NextBestAction",
        "FocusCommand",
        "ExampleCommand",
        "RankReasonSummary",
        "ReasonSummary",
        "DataGaps",
        "Return1M",
        "Return3M",
        "Return6M",
        "RSPercentile",
        "QualityScore",
        "ValuationScore",
        "ValueTrapRiskScore",
        "ConcentrationRisk",
    ]
    selected = [column for column in priority if column in frame.columns]
    if len(selected) < 6:
        selected.extend(
            column
            for column in frame.columns
            if column not in selected
            and column
            not in {
                "Reason",
                "RankReason",
                "MissingDataFields",
                "SourceFiles",
                "GeneratedAt",
                "Source",
                "Description",
                "MemberTickers",
            }
        )
    return selected[:14]


def table_focus_cards(frame: pd.DataFrame) -> list[dict[str, object]]:
    row_count = len(frame)
    row_label = "row" if row_count == 1 else "rows"
    is_valuation_view = "ValuationStatus" in frame.columns and "FinalValueCategory" in frame.columns
    lead_state, lead_state_count = dominant_value(
        frame,
        (
            ["ValuationStatus", "FinalValueCategory", "PeerRelativeStatus"]
            if is_valuation_view
            else ["FinalState", "SetupStatus", "ReviewState", "ThemeStatus", "FinalValueCategory", "PeerRelativeStatus"]
        ),
    )
    lead_context, lead_context_count = dominant_value(frame, ["PrimaryPurpose", "Theme", "Sector", "SectorETF", "ETF"])
    missing_count = non_empty_count(frame, [column for column in frame.columns if "missing" in column.lower()])
    missing_label = "row" if missing_count == 1 else "rows"
    score_count = non_empty_count(
        frame,
        [
            column
            for column in frame.columns
            if any(token in column.lower() for token in ("score", "percentile", "return", "relativeopportunity"))
        ],
    )
    return [
        {
            "kicker": "VISIBLE ROWS",
            "title": f"{row_count} {row_label}",
            "body": "Current filtered view. Use search and status/theme filters to narrow the table before opening full details.",
            "badges": ["filter-aware"],
        },
        {
            "kicker": "LEAD STATE",
            "title": lead_state,
            "body": f"Most common visible state across {lead_state_count} row{'s' if lead_state_count != 1 else ''}.",
            "badges": ["status first"],
        },
        {
            "kicker": "LEAD CONTEXT",
            "title": lead_context,
            "body": f"Most common purpose/theme context across {lead_context_count} row{'s' if lead_context_count != 1 else ''}.",
            "badges": ["research lens"],
        },
        {
            "kicker": "VALUATION CONTEXT" if is_valuation_view else "DATA COVERAGE",
            "title": (
                f"{missing_count} {missing_label} with context limits"
                if is_valuation_view and missing_count
                else ("No visible context limits" if is_valuation_view else f"{missing_count} {missing_label} with gaps")
            ),
            "body": (
                f"{score_count} row{'s' if score_count != 1 else ''} include score, return, or relative context; DCF readiness is separate from peer or multiple completeness."
                if is_valuation_view
                else f"{score_count} row{'s' if score_count != 1 else ''} include score, return, or percentile context in the visible view."
            ),
            "badges": ["DCF separate", "context limits"] if is_valuation_view else ["missing data stays visible"],
        },
    ]


