def render_value_readiness_tab(frame: pd.DataFrame) -> None:
    dcf_readiness_frame, dcf_readiness_message = load_dcf_readiness()
    ready_companies, not_ready_companies, excluded = split_dcf_readiness(dcf_readiness_frame)
    render_section_header("Valuation Quick Read", "Which valuation path to inspect first before reading detailed valuation outputs.")
    render_signal_cards(valuation_quick_read_cards(ready_companies, not_ready_companies, excluded), show_commands=False)
    with st.expander("More valuation context, boundaries, and method", expanded=False):
        render_section_header("Value / Re-rating At A Glance", "Plain-English valuation states before rankings or deeper valuation tables.")
        render_signal_cards(valuation_plain_language_cards(ready_companies, not_ready_companies, excluded))
        render_section_header("Valuation Boundaries", "What valuation can and cannot mean with the current trusted local inputs.")
        render_signal_cards(valuation_function_quality_cards(ready_companies, not_ready_companies, excluded))
        render_section_header("Intrinsic vs Relative Value", "Where standalone DCF ends, where peer valuation begins, and why blocked data stays locked.")
        render_signal_cards(valuation_boundary_explainer_cards())
        render_section_header("Valuation Method Path", "How source rows become DCF context without becoming a hidden conclusion.")
        render_signal_cards(valuation_method_path_cards())
        st.write(
            "This view separates DCF-ready company analysis, missing-data work, ETF/index monitor context, "
            "peer-relative valuation, and support dependencies so missing inputs do not look like conclusions. "
            "Operating-company valuation context is shown only for DCF-ready companies."
        )
        st.dataframe(
            clean_display_frame(valuation_function_quality_frame(ready_companies, not_ready_companies, excluded)),
            width="stretch",
            hide_index=True,
        )
        st.write(
            "This is the compact input-to-output contract behind the DCF view. It keeps the formula path visible "
            "and shows why missing fields block valuation instead of being filled."
        )
        st.dataframe(
            clean_display_frame(valuation_method_contract_frame()),
            width="stretch",
            hide_index=True,
        )
        render_section_header("Valuation Decision Guide", "A plain-language map of which valuation rows can be reviewed, which stay locked, and why.")
        render_signal_cards(valuation_decision_guide_cards(ready_companies, not_ready_companies, excluded))
        st.dataframe(
            clean_display_frame(valuation_readiness_operator_frame(ready_companies, not_ready_companies, excluded)),
            width="stretch",
            hide_index=True,
        )
    if dcf_readiness_frame is None:
        render_notice_card(
            "DCF readiness not ready yet",
            dcf_readiness_message or dcf_readiness_proof_caption(),
            "make dcf-readiness",
            tone="warning",
        )
        return
    if ready_companies.empty:
        render_notice_card(
            "DCF conclusions are blocked",
            "No operating-company ticker currently has all required DCF inputs. The table below lists the exact missing fields instead of showing ranked valuation context.",
            "make dcf-readiness",
            tone="warning",
        )
    else:
        ready_tickers = set(ready_companies["ticker"].dropna().astype(str).str.upper())
        value_ready = frame.loc[frame["Ticker"].astype(str).str.upper().isin(ready_tickers)].copy() if "Ticker" in frame.columns else pd.DataFrame()
        render_table(value_ready, "value-re-rating", show_reason_details=False)
    if not not_ready_companies.empty:
        with st.expander("Companies waiting for valuation inputs", expanded=False):
            st.write(
                "Start here when company valuation is locked. These rows are missing trusted inputs; "
                "they are not negative company conclusions."
            )
            st.dataframe(
                clean_display_frame(valuation_blocked_unlock_frame(not_ready_companies)),
                width="stretch",
                hide_index=True,
            )
        with st.expander("Valuation input checklist", expanded=False):
            columns = _readiness_columns(not_ready_companies, ["ticker", "asset_type", "missing_dcf_fields", "reason_not_ready", "has_price", "has_free_cash_flow", "has_shares_outstanding", "has_revenue", "has_fcf_margin"])
            st.dataframe(clean_display_frame(not_ready_companies[columns]), width="stretch", hide_index=True)
    if not excluded.empty:
        with st.expander("ETF / index proxy exclusions", expanded=False):
            st.write(
                "These rows can still be useful as market, sector, or theme monitors. "
                "They are excluded from operating-company DCF because that method does not fit the asset type."
            )
            st.dataframe(
                clean_display_frame(valuation_excluded_context_frame(excluded)),
                width="stretch",
                hide_index=True,
            )
        with st.expander("ETF / index exclusion checklist", expanded=False):
            columns = _readiness_columns(excluded, ["ticker", "asset_type", "reason_not_ready"])
            st.dataframe(clean_display_frame(excluded[columns]), width="stretch", hide_index=True)
    with st.expander("Complete valuation context table", expanded=False):
        st.caption(valuation_legacy_output_note())
        st.write(
            "Reader boundary is added by the dashboard so saved value categories are interpreted as readiness context, "
            "not standalone conclusions."
        )
        st.dataframe(clean_display_frame(valuation_legacy_diagnostic_frame(frame)), width="stretch", hide_index=True)


def render_final_decision_tab(frame: pd.DataFrame, show_reason_details: bool) -> None:
    decisions, decisions_message = load_output(OUTPUTS_DIR / "research_decisions.csv")
    if decisions is not None and not decisions.empty:
        render_section_header("Decision Quality", "How to interpret Research Now, Monitor, and Blocked by Data before reading the table.")
        render_signal_cards(decision_interpretation_ladder_cards(), show_commands=False)
        with st.expander("Decision interpretation ladder", expanded=False):
            st.dataframe(clean_display_frame(decision_interpretation_ladder_frame()), width="stretch", hide_index=True)
        render_signal_cards(final_decision_quality_cards(decisions), show_commands=False)
        with st.expander("More decision detail: review states, proof queue, and table guide", expanded=False):
            render_section_header("Research Decisions", "Readiness-aware decision buckets. Blocked tickers are kept in missing-data states.")
            render_signal_cards(decision_workflow_summary_cards(decisions))
            bucket_counts = decisions.get("decision_bucket", pd.Series(dtype=object)).fillna("Unknown").astype(str).value_counts()
            render_metric_cards([(bucket, int(count), "Ticker-level decision bucket") for bucket, count in bucket_counts.items()])
            proof_queue = decision_proof_queue_frame(decisions, limit=12)
            render_section_header("Decision Proof Queue", "Plain-English translation of what can be reviewed now, what stays locked, and what proves an unlock.")
            render_signal_cards(decision_proof_queue_cards(proof_queue))
            if not proof_queue.empty:
                with st.expander("Decision proof queue detail", expanded=False):
                    st.dataframe(clean_display_frame(proof_queue), width="stretch", hide_index=True)
            render_section_header("How To Read The Table", "Interpret buckets, confidence, blockers, and next actions before reading individual rows.")
            render_signal_cards(final_decision_table_guide_cards(decisions))
            decision_columns = final_decision_default_columns(decisions)
            with st.expander("Research decision table", expanded=False):
                st.dataframe(clean_display_frame(decisions[decision_columns]), width="stretch", hide_index=True)
    else:
        render_notice_card(
            "Research decisions not ready yet",
            decisions_message or "Build the readiness-aware decision buckets before reading the table.",
            "make research-decisions",
            tone="warning",
        )
    with st.expander("Complete research-state table", expanded=False):
        render_table(frame, "final-watchlist", show_reason_details)


def get_local_provider():
    try:
        return build_provider("local", base_dir=BASE_DIR)
    except Exception:  # pragma: no cover - defensive dashboard path
        return None


def _count_missing_warning_rows(output_frames: dict[str, tuple[pd.DataFrame | None, str | None]]) -> int:
    identifiers: set[str] = set()
    for filename, (frame, _message) in output_frames.items():
        if frame is None or frame.empty:
            continue
        missing_columns = [column for column in frame.columns if "missing" in column.lower()]
        if not missing_columns:
            continue
        identifier_column = "Ticker" if "Ticker" in frame.columns else "Theme" if "Theme" in frame.columns else None
        if identifier_column is None:
            continue
        mask = pd.Series(False, index=frame.index)
        for column in missing_columns:
            values = frame[column].fillna("").astype(str).str.strip()
            mask = mask | values.ne("") & values.ne("nan")
        identifiers.update(frame.loc[mask, identifier_column].astype(str).tolist())
    return len({value for value in identifiers if value})


def _latest_local_price_date(catalog: LocalDataCatalog) -> str:
    metadata = catalog.dataset_metadata("prices")
    return format_date_short(metadata.latest_data_timestamp, fallback="Unavailable")


def _monthly_top_n() -> int:
    try:
        return MonthlyPickConfig.from_yaml(BASE_DIR / "config.yaml").top_n
    except Exception:  # pragma: no cover - dashboard fallback
        return 5


def _fundamentals_coverage_count(catalog: LocalDataCatalog) -> int:
    frame = catalog.load_dataframe("fundamentals")
    if frame is None or frame.empty or "ticker" not in frame.columns:
        return 0
    return int(frame["ticker"].dropna().nunique())


def _dcf_ready_count(catalog: LocalDataCatalog) -> int:
    frame = catalog.load_dataframe("fundamentals")
    if frame is None or frame.empty:
        return 0
    empty_series = pd.Series(index=frame.index, dtype=float)
    fcf_ready = frame.get("free_cash_flow", empty_series).notna() | frame.get("fcf", empty_series).notna()
    revenue_margin_ready = frame.get("revenue", empty_series).notna() & frame.get("fcf_margin", empty_series).notna()
    if "ticker" not in frame.columns:
        return 0
    return int(frame.loc[fcf_ready | revenue_margin_ready, "ticker"].dropna().nunique())


def _peer_ready_count(catalog: LocalDataCatalog) -> int:
    peers = catalog.load_dataframe("peers")
    fundamentals = catalog.load_dataframe("fundamentals")
    if peers is None or peers.empty or fundamentals is None or fundamentals.empty:
        return 0
    peer_column = "peer_ticker" if "peer_ticker" in peers.columns else None
    if "ticker" not in peers.columns or peer_column is None or "ticker" not in fundamentals.columns:
        return 0
    fundamentals_set = set(fundamentals["ticker"].dropna().astype(str))
    ready_subjects = set()
    for _, row in peers.iterrows():
        subject = str(row.get("ticker", "")).upper().strip()
        peer = str(row.get(peer_column, "")).upper().strip()
        if subject and peer and peer in fundamentals_set and subject != peer:
            ready_subjects.add(subject)
    return len(ready_subjects)


