def _selector_option_index(options: list[str], preferred: str) -> int:
    preferred_text = str(preferred or "All").strip()
    return options.index(preferred_text) if preferred_text in options else 0


def render_stock_selector(
    output_frames: dict[str, tuple[pd.DataFrame | None, str | None]],
    *,
    public_mode: bool = True,
) -> None:
    ticker_readiness_frame, ticker_readiness_message = load_ticker_readiness_report()
    dcf_readiness_frame, _ = load_dcf_readiness()
    optional_tables = load_optional_context_readiness()
    earnings_readiness_frame, _ = optional_tables["earnings_readiness"]
    analyst_readiness_frame, _ = optional_tables["analyst_estimates_readiness"]
    decisions_frame, decisions_message = load_output(OUTPUTS_DIR / "research_decisions.csv")
    final_frame, final_message = output_frames.get("final_watchlist.csv", (None, None))
    coverage_frame, _ = load_output(OUTPUTS_DIR / "ticker_data_coverage.csv")
    summary = dashboard_readiness_summary(
        coverage_frame,
        dcf_readiness_frame,
        earnings_readiness_frame,
        analyst_readiness_frame,
        ticker_readiness_frame,
    )
    selector_frame = stock_selector_queue_frame(decisions_frame, final_frame, ticker_readiness_frame, limit=120)

    render_section_header(
        STOCK_SELECTOR_PATH_TITLE,
        "Filter readiness-backed research candidates before opening a single-stock report.",
    )
    render_signal_cards(stock_selector_cockpit_cards(summary), show_commands=False, variant="queue")
    render_context_note(
        "Research-only selector.",
        "This page helps choose what to review next. It keeps blockers, excluded states, and proof freshness visible before deeper analysis.",
        tone="success",
    )

    if ticker_readiness_message or decisions_message or final_message:
        render_notice_card(
            "Saved selector data may need refresh",
            ticker_readiness_message or decisions_message or final_message or "Refresh readiness before relying on exact counts.",
            "make status-check TOP_N=5",
            tone="warning",
            public=public_mode,
        )

    if selector_frame.empty:
        render_notice_card(
            "Selector queue is empty",
            "Build saved research decisions or the final watchlist before using the selector surface.",
            "make status-check TOP_N=5",
            tone="warning",
            public=public_mode,
        )
        return

    render_section_header("Research Queue", "Use filters to narrow the next one-ticker review candidate.")
    saved_presets = stock_selector_saved_filter_presets()
    preset_label = st.selectbox(
        "Saved filter",
        [preset["label"] for preset in saved_presets],
        index=0,
        help="Fast product presets for common review paths. They only adjust filters; they do not create conclusions.",
        key="stock-selector-saved-filter",
    )
    selected_preset = next((preset for preset in saved_presets if preset["label"] == preset_label), saved_presets[0])
    with st.form("stock-selector-filter-form"):
        filter_cols = st.columns([1.05, 1.05, 1.15, 1.2, 1.65])
        state_options = _stock_selector_filter_options(selector_frame, "Research State")
        readiness_options = _stock_selector_filter_options(selector_frame, "Readiness")
        detail_options = _stock_selector_filter_options(selector_frame, "Review Detail")
        theme_options = _stock_selector_filter_options(selector_frame, "Sector / Theme")
        state_filter = filter_cols[0].selectbox(
            "Research state",
            state_options,
            index=_selector_option_index(state_options, selected_preset["state"]),
            key="stock-selector-state",
        )
        readiness_filter = filter_cols[1].selectbox(
            "Readiness",
            readiness_options,
            index=_selector_option_index(readiness_options, selected_preset["readiness"]),
            key="stock-selector-readiness",
        )
        detail_filter = filter_cols[2].selectbox(
            "Review detail",
            detail_options,
            index=_selector_option_index(detail_options, selected_preset["detail"]),
            key="stock-selector-detail",
        )
        theme_filter = filter_cols[3].selectbox(
            "Sector / theme",
            theme_options,
            index=_selector_option_index(theme_options, selected_preset["theme"]),
            key="stock-selector-theme",
        )
        search = filter_cols[4].text_input(
            "Search ticker, theme, blocker, or proof step",
            value=selected_preset["search"],
            key="stock-selector-search",
        ).strip()
        st.form_submit_button("Apply filters")

    filtered = stock_selector_apply_filters(
        selector_frame,
        state_filter=state_filter,
        readiness_filter=readiness_filter,
        detail_filter=detail_filter,
        theme_filter=theme_filter,
        search=search,
    )

    count_label = f"{len(filtered):,} of {len(selector_frame):,} saved rows"
    render_context_note(
        "Filtered result set.",
        f"{count_label} match the current filters. Open Single-Stock Report for one ticker, or Data Health if the blocker is the main question.",
    )
    shortlist_options = filtered["Ticker"].astype(str).str.upper().drop_duplicates().head(30).tolist()
    selected_shortlist = st.multiselect(
        "Compare selected rows",
        shortlist_options,
        default=shortlist_options[: min(3, len(shortlist_options))],
        max_selections=5,
        help="Optional comparison tray for readiness, blockers, and proof steps. It does not create conclusions or account actions.",
        key="stock-selector-shortlist",
    )
    st.markdown(
        stock_selector_shortlist_html(stock_selector_shortlist_frame(filtered, selected_shortlist)),
        unsafe_allow_html=True,
    )
    st.markdown(
        stock_selector_result_table_html(filtered, total_count=len(selector_frame), limit=30),
        unsafe_allow_html=True,
    )
    with st.expander("Full filtered selector rows", expanded=False):
        render_context_note(
            "Detailed selector evidence.",
            "The full filtered table stays available for audit, but the public first-read view uses readiness rows and explicit actions.",
        )
        st.dataframe(clean_display_frame(filtered.head(120)), width="stretch", hide_index=True)

    if public_mode:
        render_section_header("Next Reading Path", "Move from selection to proof without turning the queue into a conclusion.")
        render_action_cards(
            [
                (
                    "Open one review",
                    "Use the selected ticker action above to open the one-stock review.",
                    "?mode=public&page=single-stock-report&ticker=NVDA&open=1",
                    "neutral",
                ),
                (
                    "Check data proof",
                    "Use Data Health when the selector row is partial, blocked, or stale.",
                    "?mode=public&page=data-health&drawer=proof",
                    "neutral",
                ),
                (
                    "Inspect proof history",
                    "Review durable proof rows before trusting changed readiness states.",
                    "?mode=public&page=proof-history",
                    "neutral",
                ),
            ]
        )


def price_refresh_operator_plan_cards(summary: dict[str, object] | None = None) -> list[dict[str, object]]:
    summary = summary or {}
    master = int(summary.get("master_universe") or summary.get("universe_count") or 0)
    price_ready = int(summary.get("price_ready") or 0)
    missing = max(master - price_ready, 0) if master else 0
    missing_label = f"{missing:,} ticker(s)" if missing else "missing-price tickers"
    broad_target = min(max(missing, 100), 3500) if missing else 3500
    broad_target = ((broad_target + 99) // 100) * 100
    planned_batches = max((broad_target + 99) // 100, 1)
    avoided_small_batches = max((broad_target + 24) // 25, 1)

    return [
        {
            "kicker": "CURRENT PRICE STATE",
            "title": "Check what is missing now",
            "body": (
                f"About {missing_label} still need price history. Read the current snapshot first so the dry run has a clear target."
            ),
            "badges": ["read first", "local snapshot"],
            "command": "make status-check TOP_N=5",
        },
        {
            "kicker": "DRY-RUN PLAN",
            "title": "Preview the broad refresh first",
            "body": (
                "Use a dry run with MAX_CANDIDATES so the loop "
                f"calculates capped batches for you before any local CSV files change. "
                f"Current plan: about {planned_batches} 100-ticker batch(es), replacing about {avoided_small_batches} small 25-ticker commands."
            ),
            "badges": ["dry run first", "no manual repeats"],
            "command": f"make price-refresh-loop DRY_RUN=1 MAX_CANDIDATES={broad_target} TOP_N=100 PROVIDER=auto",
        },
        {
            "kicker": "BEFORE UPDATE",
            "title": "Save the current readiness snapshot",
            "body": (
                "A snapshot lets the dashboard compare current and prior readiness after the refresh, instead of guessing what changed."
            ),
            "badges": ["compare later", "local only"],
            "command": "make readiness-snapshot",
        },
        {
            "kicker": "CAPPED RUN",
            "title": "Run the loop only after reviewing the plan",
            "body": (
                "Use the same MAX_CANDIDATES and TOP_N from the dry run. "
                f"The loop handles the {planned_batches} capped batch(es) for you, updates local CSVs only, "
                "then you review the local file changes."
            ),
            "badges": ["capped batches", "review changes"],
            "command": f"make price-refresh-loop MAX_CANDIDATES={broad_target} TOP_N=100 PROVIDER=auto SLEEP_SECONDS=30",
        },
        {
            "kicker": "VERIFY & HYGIENE",
            "title": "Prove what changed before staging",
            "body": (
                "Rebuild price coverage, readiness, and project status, then inspect local CSV changes before staging anything."
            ),
            "badges": ["prove readiness", "review changes"],
            "command": "make price-coverage TOP_N=25 && make readiness && make project-status && make diff-hygiene",
        },
    ]


