def roadmap_milestone_status_frame(summary: dict[str, object] | None = None) -> pd.DataFrame:
    summary = summary or {}
    master = int(summary.get("master_universe") or summary.get("master_count") or summary.get("universe_count") or 0)
    fundamentals_ready = int(summary.get("fundamentals_ready") or 0)
    dcf_ready = int(summary.get("dcf_ready") or 0)
    peer_ready = int(summary.get("peer_ready") or 0)
    earnings_ready = int(summary.get("earnings_ready") or 0)
    estimates_ready = int(summary.get("analyst_estimates_ready") or summary.get("analyst_ready") or 0)

    def _count_text(count: int, label: str) -> str:
        return f"{count:,}/{master:,} {label}" if master else f"{count:,} {label}"

    return pd.DataFrame(
        [
            {
                "Roadmap Area": "Product workflow",
                "Current Status": "Implemented",
                "Evidence": "Universe Layers, grouped Next Steps, source readiness notes, row limits, and copy-only commands are visible in the dashboard.",
                "Next Safe Step": "Use Home, Single-Stock Report, or Data Health to choose a capped or ticker-targeted command.",
                "Copy Command": "make dashboard-smoke",
            },
            {
                "Roadmap Area": "Batch operations workflow",
                "Current Status": "Implemented, proof-first",
                "Evidence": "Data Health now opens with an operations cockpit, lane operations board, coverage frontier, reviewed proof timeline, and reviewed-batch packet path.",
                "Next Safe Step": "Inspect the lane frontier, then create a copy-only reviewed batch packet before any capped execution.",
                "Copy Command": "DRY_RUN=1 make reviewed-batch LANE=prices TOP_N=10",
            },
            {
                "Roadmap Area": "Fundamentals / DCF data proof",
                "Current Status": "Waiting on trusted data",
                "Evidence": f"{_count_text(fundamentals_ready, 'fundamentals-ready')} and {_count_text(dcf_ready, 'DCF-ready')}; counts should improve only after SEC staging workflow or trusted manual CSV imports.",
                "Next Safe Step": "Inspect the top fundamentals blocker, then stage SEC or trusted manual fundamentals rows.",
                "Copy Command": "make sec-stage-queue TOP_N=25",
            },
            {
                "Roadmap Area": "Peer readiness",
                "Current Status": "Workflow improved, data still sparse",
                "Evidence": f"{_count_text(peer_ready, 'peer-ready')}; missing peer mappings and peer inputs stay explicit instead of inferred.",
                "Next Safe Step": "Open the Peer Mapping Studio and add only source-backed peer rows.",
                "Copy Command": "make peer-mapping-queue TOP_N=25",
            },
            {
                "Roadmap Area": "Optional context",
                "Current Status": "Locked until trusted rows exist",
                "Evidence": f"{_count_text(earnings_ready, 'earnings-ready')} and {_count_text(estimates_ready, 'analyst-estimate-ready')}; empty optional context is intentional, not inferred analysis.",
                "Next Safe Step": "Use the read-only optional-context summary first; validate, preview, and apply only after trusted local rows exist.",
                "Copy Command": "make optional-context-summary TOP_N=10",
            },
            {
                "Roadmap Area": "Decision clarity",
                "Current Status": "Readiness-gated",
                "Evidence": "Research Now, Monitor, and Blocked by Data remain tied to required inputs, exclusions, primary blockers, and next actions.",
                "Next Safe Step": "Regenerate decisions after trusted data changes, then review the decision table.",
                "Copy Command": "make research-decisions",
            },
            {
                "Roadmap Area": "Verification",
                "Current Status": "Run on demand",
                "Evidence": "Pipeline/onboarding/test commands prove the current saved research views still build and the dashboard still starts.",
                "Next Safe Step": "Run scoped verification after product or trusted-data changes.",
                "Copy Command": "make verify",
            },
        ]
    )


def roadmap_milestone_status_cards(summary: dict[str, object] | None = None) -> list[dict[str, object]]:
    frame = roadmap_milestone_status_frame(summary)
    cards: list[dict[str, object]] = []
    for _, row in frame.iterrows():
        status = format_missing(row.get("Current Status"), "Status")
        area = format_missing(row.get("Roadmap Area"), "Roadmap")
        evidence = format_missing(row.get("Evidence"), "")
        next_step = format_missing(row.get("Next Safe Step"), "")
        cards.append(
            {
                "kicker": status.upper(),
                "title": area,
                "body": f"{evidence} Next: {next_step}",
                "badges": ["roadmap status", "data-honest"],
                "command": format_missing(row.get("Copy Command"), ""),
            }
        )
    return cards


def _plain_home_function_quality_frame(summary: dict[str, object] | None = None) -> pd.DataFrame:
    summary = summary or {}
    master = int(summary.get("master_universe") or summary.get("universe_count") or 0)

    def _count_text(key: str, label: str) -> str:
        count = int(summary.get(key) or 0)
        if master:
            return f"{count:,} / {master:,} {label}."
        if count:
            return f"{count:,} {label}."
        return f"{label.title()} count not loaded on this page yet."

    price_status = _count_text("price_ready", "price-ready")
    dcf_status = _count_text("dcf_ready", "DCF-ready")
    peer_status = _count_text("peer_ready", "peer-ready")
    earnings_status = _count_text("earnings_ready", "earnings-ready")
    estimates_status = _count_text("analyst_estimates_ready", "analyst-estimate-ready")
    return pd.DataFrame(
        [
            {
                "Function Area": "Readiness gates",
                "Quality Verdict": "Strong today",
                "Best Use Today": "Trust this first when deciding whether a ticker can support deeper review.",
                "Current Status": "Strong when the local readiness reports are current; this is the first layer every page should respect.",
                "Supported Today": "Strongest layer; decides whether deeper analysis is allowed.",
                "Needs Trusted Data": "Ticker universe, prices, fundamentals, peers, earnings, and estimate readiness rows.",
                "Methodology / Provenance": "Project rules in src/readiness_engine.py.",
            },
            {
                "Function Area": "Price / momentum",
                "Quality Verdict": "Good when price history is ready",
                "Best Use Today": "Review trend, setup, liquidity, and market context for tickers with enough local prices.",
                "Current Status": price_status,
                "Supported Today": "Local setup, trend, liquidity, and market-context review when price history exists.",
                "Needs Trusted Data": "Verified local OHLCV rows with enough history.",
                "Methodology / Provenance": "Project calculations in src/indicators.py and src/momentum_engine.py.",
            },
            {
                "Function Area": "Fundamentals / DCF",
                "Quality Verdict": "Good for DCF-ready companies only",
                "Best Use Today": "Review the DCF input path, assumptions, scenarios, and sensitivity when trusted fundamentals and price inputs exist.",
                "Current Status": dcf_status,
                "Supported Today": "DCF-ready company analysis with visible input path, assumptions, and sensitivity.",
                "Needs Trusted Data": "Revenue, free cash flow or margin, shares, price, cash, debt, and source readiness.",
                "Methodology / Provenance": "Project assumptions in src/value_engine.py and src/valuation.py.",
            },
            {
                "Function Area": "Peer comparison",
                "Quality Verdict": "Ready when peer data exists",
                "Best Use Today": "Use as a peer missing-data list until source-backed peer mappings and metrics are ready.",
                "Current Status": peer_status,
                "Supported Today": "Peer context after source-backed peer rows and peer metrics exist.",
                "Needs Trusted Data": "Manual peer mappings plus peer fundamentals or peer market context.",
                "Methodology / Provenance": "Project peer readiness and valuation checks; no guessed peer mappings.",
            },
            {
                "Function Area": "Earnings / estimates",
                "Quality Verdict": "Intentionally locked without trusted rows",
                "Best Use Today": "Treat as optional context setup; do not interpret empty coverage as analysis.",
                "Current Status": f"{earnings_status} {estimates_status}",
                "Supported Today": "Optional context only after trusted local rows exist; empty coverage means intentionally unavailable.",
                "Needs Trusted Data": "Trusted local earnings and analyst-estimate CSV rows with validation/preview/apply review.",
                "Methodology / Provenance": "Project optional-context readiness and import workflow.",
            },
            {
                "Function Area": "Single-stock report",
                "Quality Verdict": "Clearest visitor-facing review",
                "Best Use Today": "Open one ticker to see ready, blocked, excluded, optional, and source readiness states step by step.",
                "Current Status": "Clear for one ticker's ready, blocked, excluded, and monitor-only analysis.",
                "Supported Today": "One-ticker review of supported, blocked, excluded, and monitor-only analysis.",
                "Needs Trusted Data": "Current local readiness, price, DCF, peer, optional-context, and source readiness outputs.",
                "Methodology / Provenance": "Project report assembly in src/stock_report.py and src/dashboard.py separates source rows from product calculations and blocked-section wording.",
            },
            {
                "Function Area": "Dependencies",
                "Quality Verdict": "Support layer, not analysis rules",
                "Best Use Today": "Use support packages and optional adapters to handle data and UI while project code keeps the rules.",
                "Current Status": "Support layer only; analysis rules remain in project code.",
                "Supported Today": "Data handling, UI, tests, and optional research-grade provider access.",
                "Needs Trusted Data": "Local CSV inputs remain the source of truth by default.",
                "Methodology / Provenance": "Support packages and optional provider adapters help run the product; analysis rules remain under src/.",
            },
        ]
    )


def render_home_page(
    catalog: LocalDataCatalog,
    output_frames: dict[str, tuple[pd.DataFrame | None, str | None]],
    *,
    show_details: bool = False,
    public_mode: bool = True,
) -> None:
    ticker_readiness_frame, ticker_readiness_message = load_ticker_readiness_report()
    dcf_readiness_frame, _ = load_dcf_readiness()
    optional_tables = load_optional_context_readiness()
    earnings_readiness_frame, _ = optional_tables["earnings_readiness"]
    analyst_readiness_frame, _ = optional_tables["analyst_estimates_readiness"]
    decisions_frame, decisions_message = load_output(OUTPUTS_DIR / "research_decisions.csv")
    coverage_frame, _ = load_output(OUTPUTS_DIR / "ticker_data_coverage.csv")

    summary = dashboard_readiness_summary(
        coverage_frame,
        dcf_readiness_frame,
        earnings_readiness_frame,
        analyst_readiness_frame,
        ticker_readiness_frame,
    )
    generated_stale_warning = dashboard_generated_artifact_stale_warning(BASE_DIR)
    freshness = readiness_freshness_status(BASE_DIR)

    if not public_mode:
        render_section_header(
            "Home",
            "A readiness-first research cockpit for choosing what to review next.",
        )
        render_signal_cards(dashboard_page_reader_summary_cards("Home"))
        render_signal_cards(_plain_home_readiness_cards(summary, decisions_frame), show_commands=False)

    if public_mode:
        render_public_proof_strip(_public_home_snapshot_items(summary))
        render_section_header(
            "First 30 Seconds",
            "What the product does, how to read it, and when to stop before looking at examples.",
        )
        render_signal_cards(public_home_first_30_second_cards(summary), show_commands=False)
        render_section_header(
            "Connected Workflow",
            "A compact map from readiness snapshot to one-ticker review, source-proof lane, and stop rule.",
        )
        render_signal_cards(public_home_review_map_cards(summary), show_commands=False, variant="queue")
        render_section_header(
            "Visitor Path",
            "A simple four-step path for reading the project without opening operator tables.",
        )
        render_signal_cards(public_home_visitor_path_cards(summary), show_commands=False, variant="queue")
    if generated_stale_warning:
        render_notice_card(
            "Generated status may be stale",
            generated_stale_warning,
            "make readiness",
            tone="warning",
            public=public_mode,
        )
    if freshness.status in {"missing", "stale"}:
        render_notice_card(
            "Readiness snapshot may be stale",
            freshness.message,
            freshness.refresh_command,
            tone="warning",
            public=public_mode,
        )
    if public_mode:
        render_section_header("Where To Go Next", "Choose the next surface without reading operator tables first.")
        render_action_cards(_plain_home_route_choice_cards(summary))
        with st.expander("Optional: workflow and next-step details", expanded=False):
            render_section_header(
                "Research Workflow",
                "One connected loop: readiness snapshot, selector queue, one-ticker report, source-proof lane, then proof history before trusting changed states.",
            )
            render_signal_cards(_plain_home_real_workflow_cards(summary), show_commands=False)
            render_section_header("What To Do Next", "The product prioritizes useful research coverage before deeper analysis.")
            render_signal_cards(_plain_home_next_step_cards(summary)[:4], show_commands=False)
    else:
        render_section_header(
            "Research Workflow",
            "One connected loop: readiness snapshot, selector queue, one-ticker report, source-proof lane, then proof history before trusting changed states.",
        )
        render_research_loop_strip(**home_research_loop_context(summary, freshness))
        render_signal_cards(_plain_home_real_workflow_cards(summary), show_commands=True)
        render_section_header("What To Do Next", "The product prioritizes useful research coverage before deeper analysis.")
        render_signal_cards(_plain_home_next_step_cards(summary), show_commands=False)
        render_section_header("Where To Go", "Choose the page that matches what you want to review.")
        render_action_cards(_plain_home_route_choice_cards(summary))

    if public_mode:
        with st.expander("Example state walkthrough", expanded=False):
            render_section_header(
                "Example State Walkthrough",
                "Real local examples for ready, blocked, excluded, peer-limited, and fundamentals-gated states.",
            )
            render_signal_cards(_plain_home_first_run_path_cards(), show_commands=False)
            st.dataframe(clean_display_frame(_plain_home_demo_example_frame()), width="stretch", hide_index=True)
        render_context_note(
            "Research-only boundary.",
            "Examples are secondary evidence, not the main workflow and not recommendations. They show which analysis is supported, locked, or excluded by the current local data.",
            tone="success",
        )

    if show_details:
        render_context_note(
            "Extra review detail is on.",
            "These sections explain methodology, local commands, and unlock workflows. Turn reader tips off for the clean visitor view.",
        )

    if show_details:
        with st.expander("Optional: coverage details", expanded=False):
            render_section_header("Current Data Coverage", "A quick public snapshot of what is ready, what is locked, and which safe proof path comes first.")
            render_signal_cards(_plain_home_current_data_coverage_cards(summary), show_commands=False)

        with st.expander("Optional: how evaluation works", expanded=False):
            render_section_header("How Evaluation Works", "How the product moves from trusted data to supported analysis without overclaiming.")
            render_signal_cards(_plain_home_evaluation_workflow_cards(), show_commands=False)

        with st.expander("Optional: price update plan", expanded=False):
            render_section_header("Scalable Price Updates", "How to expand price coverage without repeating tiny batches by hand.")
            render_signal_cards(price_refresh_operator_plan_cards(summary), show_commands=False)

        with st.expander("Optional: example reports", expanded=False):
            render_section_header("Example Reports", "Use these small examples to see each analysis mode without running a full-market refresh.")
            st.dataframe(clean_display_frame(_plain_home_demo_example_frame()), width="stretch", hide_index=True)
            render_context_note(
                "Example boundary.",
                "These are report examples, not recommendations. They show ready, blocked, and excluded analysis states from local data.",
            )

    if ticker_readiness_message or decisions_message:
        render_notice_card(
            "Some reports need refreshing",
            ticker_readiness_message or decisions_message or "Refresh the local reports before relying on this page.",
            "",
            tone="warning",
        )

    if show_details:
        with st.expander("Optional: methodology, roadmap, and transparency", expanded=False):
            render_section_header("Methodology Ladder", "How the product gets from local data to report wording without guessing missing inputs.")
            st.dataframe(clean_display_frame(methodology_ladder_frame()), width="stretch", hide_index=True)
            st.caption("Full methodology: docs/METHODOLOGY.md")

            render_section_header("Roadmap Status", "What is already implemented, what is waiting on trusted data, and the safest next command.")
            render_signal_cards(roadmap_milestone_status_cards(summary), show_commands=False)
            with st.expander("Roadmap status table", expanded=False):
                st.dataframe(clean_display_frame(roadmap_milestone_status_frame(summary)), width="stretch", hide_index=True)

            render_section_header("Analysis Capability", "What the current functions are good at, where they are limited, and how the methodology is kept transparent.")
            render_signal_cards(_plain_home_capability_cards())
            render_section_header("Methodology And Provenance", "Plain-language provenance for the analysis functions and development aids.")
            render_signal_cards(_plain_home_provenance_cards())
            with st.expander("Detailed analysis capability review", expanded=False):
                st.write(
                    "This public review explains which functions are strong today, which data gaps still limit the product, "
                    "and why the analysis shown to users comes from project code and local CSV inputs."
                )
                st.dataframe(clean_display_frame(_plain_home_function_quality_frame(summary)), width="stretch", hide_index=True)
                st.code("docs/analysis_capability_audit.md", language="text")

        with st.expander("Optional: local commands", expanded=False):
            st.write("Preview capped refreshes first. Use update commands only when you intentionally want to change local files.")
            st.code(
                "\n".join(
                    [
                        "make status-check TOP_N=5",
                        "make price-refresh-loop DRY_RUN=1",
                        "make price-refresh-loop DRY_RUN=1 MAX_CANDIDATES=3500 TOP_N=100 PROVIDER=auto",
                        "make readiness-snapshot",
                        "make price-refresh-loop MAX_CANDIDATES=3500 TOP_N=100 PROVIDER=auto SLEEP_SECONDS=30",
                        "make diff-hygiene",
                        "make readiness",
                        "make project-status",
                        "make stock-report-md TICKER=NVDA",
                        "make dashboard-smoke",
                    ]
                ),
                language="bash",
            )
            st.caption("Broad refresh changes should be inspected before they are committed or shared publicly.")


def render_monthly_picks(catalog: LocalDataCatalog) -> None:
    render_advanced_page_shell(
        "Monthly Picks",
        "A compact, data-gated research-candidate list. Scores help decide what to review next; they are not advice, allocation guidance, or a conclusion list.",
    )
    top_n = _monthly_top_n()
    monthly_tables = load_monthly_outputs()
    picks_frame, picks_message = monthly_tables["monthly_research_picks.csv"]
    track_frame, _track_message = monthly_tables["monthly_picks_track_record.csv"]
    equity_frame, _equity_message = monthly_tables["monthly_picks_equity_curve.csv"]
    latest_price = _latest_local_price_date(catalog)
    universe = catalog.load_dataframe("universe")
    universe_count = 0 if universe is None or universe.empty else len(universe)
    candidate_count = 0 if picks_frame is None else len(picks_frame)
    action_queue_frame, _ = load_action_queue()
    render_signal_cards(
        monthly_picks_landing_cards(
            picks_frame,
            track_frame,
            equity_frame,
            top_n,
            latest_price,
            universe_count,
        ),
        show_commands=False,
    )
    render_signal_cards(
        monthly_picks_next_step_cards(
            picks_frame,
            track_frame,
            equity_frame,
            top_n,
            action_queue_frame,
        ),
        show_commands=False,
    )
    render_signal_cards(monthly_picks_quality_cards(picks_frame, track_frame, equity_frame, top_n), show_commands=False)
    render_section_header("Candidate Review Guide", "How to use candidate cards before opening deeper evidence.")
    render_signal_cards(monthly_picks_reader_guide_cards(picks_frame, top_n, action_queue_frame), show_commands=False)
    render_section_header("How To Read Monthly Picks", "Candidate quality, limits, and method provenance before reading any ranked names.")
    render_signal_cards(monthly_picks_function_quality_cards())

    render_metric_cards(
        [
            ("Candidates", f"{candidate_count} of {top_n}", "Conservative filters may return fewer"),
            ("Current Month", "Not ready yet" if picks_frame is None or picks_frame.empty else picks_frame.iloc[0].get("Month", "Not available"), "Built from local monthly context"),
            ("Benchmark", "SPY", "For local track-record comparison"),
            ("Universe", universe_count, "Current local universe size"),
            ("Latest Price", latest_price, "Latest local price date"),
        ]
    )
    blocker_command = monthly_picks_next_step_cards(
        pd.DataFrame() if picks_frame is not None and picks_frame.empty else picks_frame,
        track_frame,
        equity_frame,
        top_n,
        action_queue_frame,
    )[0]["command"]

    if picks_frame is None:
        render_notice_card(
            "Monthly context not ready yet",
            picks_message or "Build local monthly proof before interpreting this tab. This stays research-only and may still return fewer than five names.",
            "",
        )
    elif picks_frame.empty:
        render_notice_card(
            "No monthly candidates passed the current filters",
            "The output exists, but the conservative scoring rules did not find supported local candidates. Improve price/fundamental coverage before broadening interpretation.",
            "",
            tone="warning",
        )
    else:
        st.info(monthly_pick_availability_message(candidate_count, top_n))
        if candidate_count < top_n:
            st.warning(
                "The candidate list is intentionally shorter than the configured top count because the current local data "
                "or conservative filters did not support filling the remaining slots."
            )
        priority_signals = top_priority_signals(action_queue_frame, limit=2)
        if priority_signals:
            render_signal_cards(priority_signals)
        render_section_header("Research Candidates", "Ordered research candidates, not allocation instructions.")
        ordered_picks = picks_frame.sort_values(["Rank", "CompositeScore"], ascending=[True, False])
        st.markdown(
            "<div class='pick-grid'>"
            + "".join(monthly_pick_card_html(row) for _, row in ordered_picks.iterrows())
            + "</div>",
            unsafe_allow_html=True,
        )
        with st.expander("Candidate scoring and table detail", expanded=False):
            score_chart_frame = monthly_pick_score_chart_frame(ordered_picks)
            if not score_chart_frame.empty:
                render_chart_panel(
                    "Score context",
                    "This chart compares transparent local score components for the current candidate set. Missing components stay blank instead of being inferred.",
                    score_chart_frame,
                    chart_kind="bar",
                )
            display_columns = [
                column
                for column in [
                    "Rank",
                    "Ticker",
                    "Theme",
                    "Sector",
                    "CompositeScore",
                    "MomentumScore",
                    "QualityScore",
                    "ValuationContextScore",
                    "RiskPenalty",
                    "LiquidityScore",
                    "MAStackStatus",
                    "RSI14",
                    "Reason",
                    "MissingDataFields",
                ]
                if column in picks_frame.columns
            ]
            st.dataframe(clean_display_frame(picks_frame[display_columns]), width="stretch", hide_index=True)

    render_section_header("Track Record", "Shown only when local historical prices support benchmark comparison.")
    if equity_frame is not None and not equity_frame.empty and {"Month", "PicksEquity", "BenchmarkEquity"}.issubset(equity_frame.columns):
        chart_frame = equity_frame.set_index("Month")[["PicksEquity", "BenchmarkEquity"]]
        render_chart_panel(
            "Equity curve",
            "Compares the locally calculated monthly picks equity curve against the benchmark only when enough local price history exists.",
            chart_frame,
            chart_kind="line",
        )
    else:
        render_notice_card(
            "Track record needs more local history",
            track_record_status_message(track_frame, equity_frame),
            "",
        )
    with st.expander("Track-record table and archive detail", expanded=False):
        if track_frame is not None and not track_frame.empty:
            st.dataframe(clean_display_frame(track_frame), width="stretch", hide_index=True)
            render_section_header("Archive", "Prior local monthly pick lists and returns when calculable.")
            archive_columns = [column for column in ["Month", "Picks", "AveragePickReturn", "BenchmarkReturn", "ExcessReturn", "Notes"] if column in track_frame.columns]
            st.dataframe(clean_display_frame(track_frame[archive_columns]), width="stretch", hide_index=True)
        else:
            render_notice_card(
                "Track-record table not ready yet",
                "Track-record proof is still unavailable. Run the current blocker path first; if local price history is still short afterward, the track-record state will stay explicit instead of fabricating performance.",
                blocker_command,
            )
            render_notice_card(
                "No monthly archive yet",
                "The archive appears only after enough local monthly pick and price-history rows exist. Nothing is backfilled or invented.",
                blocker_command,
            )

    with st.expander("Methodology", expanded=False):
        st.write("Monthly review ordering uses local research outputs, local price history, optional local fundamentals, and transparent score components.")
        st.write("Missing inputs reduce data confidence and remain visible in the review.")
        st.write("Track-record proof is calculated only from local historical price data; insufficient history is shown explicitly.")


